import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchBA: [CaseTemplate] = [rodeoLotStabbing, gravelPlantPayroll, boxCutterStation, jewelrySmashGrab, dayCareNightFire, nurseSalineSwap, motelMethRoom, pillMillClinic, cockfightBarnRaid, carChokeBar, gpsTrackerEx, fakeProfileCampaign, doorbellHackFamilies, schoolRansomLock, bankFileSale, fakeFundraiserOnline, churchInvestmentPonzi, homeBuilderDeposits, realtorEscrowTake, chopShopTrucks, cyclistDawnHitRun, flowersAtWork, lakeCabinRansom, roadMergeShooting, churchStairShove, ranchPipeAssault, raceTrackBrawl, schoolBoardContract, lyingWitnessStand, hiddenGunFriend, restaurantOrderHack, churchFireFormer, tireSparePills, pawnStrawBuy, forgedDeedLot, cafeBurnedForInsurance, groupHomeWanderFreeze, roofingWidowScam, loanSharkThreats, bailBondsJailer, barnFeudFire, chaserStagedInjuries, hayrideTractorWreck, teacherHallAttack, illegalFireworksBlast, medicSpitBite, countyClerkFees, crossbowNeighborDispute, lakeBoatCrashDeath, checkKitingRing]

    static let rodeoLotStabbing = SmallCases.make(
        key: "story.rodeoLotStabbing",
        category: .violent,
        headlines: ["Cowboy Stabbed in Rodeo Arena Parking Lot After Lost Bet", "Suspect Arrested at Trailer Hitch"],
        law: "awdwik",
        threshold: 8,
        spec: "Assaulted {V} with a knife with intent to kill, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was stabbed in the abdomen in a rodeo arena parking lot on {DATE} after an argument over a bet. {D} was found at a livestock trailer with a bloody knife. {DL} says {V} had a bottle and charged first.",
        state: [E(.statement, 3, "Rodeo Hand", "{D} stabbed {V} after they argued about money."), E(.physical, 3, "Knife", "A bloody knife behind a trailer tire.", .search), E(.forensic, 2, "Medical Report", "One wound near the liver.")],
        defense: [E(.statement, 1, "Bottle", "{DL} says {V} charged with a bottle.")],
        role: "Rodeo hand",
        exam: [.direct("What happened in the parking lot at the rodeo arena?", "\"{D} and {V} argued over a bet, and then {DL} stabbed {V} in the abdomen. I was standing close enough to see the argument turn physical.\""), .direct("What had they argued about?", "\"Money, from a wager between the two of them. The voices got louder, and then I saw the knife come out.\""), .direct("What did deputies find afterward?", "\"A bloody knife behind a trailer tire near the livestock trailer, and {D.he} was found right there. {V} had one wound near the liver.\""), .direct("Where were you standing when the argument got heated?", "\"I was leaning on my truck about thirty feet away, coiling a rope after my event. It was around 9 p.m. and the lot was lit by two floodlights from the arena.\""), .direct("How did {V} look right after the stabbing?", "\"{V} doubled over, grabbed at the abdomen, and dropped to one knee. Blood came through {V.his} shirt, and a couple of us ran over and pressed on the wound.\""), .direct("What did {D} do right after?", "\"{D.He} walked fast toward the livestock trailers and I lost sight. When deputies arrived about twenty minutes later, {D.he} was standing by one of the trailers.\""), .cross("{V} had a bottle, didn't {V.he}?", "\"I saw a bottle on the ground near {V}'s boot. I did not see {V} swing it.\""), .cross("Did you see who made the first move?", "\"No. I looked away for a moment. I cannot say for sure who stepped toward whom.\""), .cross("Rodeo hands carry knives for rope work, don't they?", "\"Many of us do. It is a work tool, and that is not unusual.\""), .cross("How loud was the argument before the stabbing?", "\"Loud enough that people turned. Both of them were cussing. I could not tell you the exact words, only that the bet and money came up.\""), .cross("Was it dark where {V} was standing?", "\"Dim. The floodlights did not reach every corner, so there was shadow near the trailers where the two of them were standing.\"")],
        defenseRole: "Arena announcer",
        defenseExam: [.direct("What did you see from the announcer stand?", "\"I saw {V} lunge toward {D} with a bottle in hand. It was quick, and {DF} was backing away.\""), .direct("How far were you from the two of them?", "\"About forty yards across the lot. I had a clear view of the two of them from up on the stand.\""), .direct("What was {D} doing when the lunge came?", "\"{D.He} had a hand up and was stepping back. It looked defensive to me, but it all happened fast.\""), .direct("What do you do at the arena and what is your view like?", "\"I announce the events from a booth above the stands, which looks out over the arena and part of the parking lot.\""), .direct("What drew your attention to the lot?", "\"Raised voices carried up. I looked down and saw two people squaring off near a trailer under the floodlight.\""), .direct("What happened after the lunge?", "\"There was a scuffle and a cry. A few people rushed over, and someone shouted for a medic. I called the paramedics over the speaker.\""), .cross("Could you see what was in {V}'s hand from forty yards?", "\"I saw something glass. I took it to be a bottle, but I could not see it closely.\""), .cross("Did you see the knife come out?", "\"No. I did not see the knife until afterward. I saw the lunge and then people rushing in.\""), .cross("Do you know the defendant personally?", "\"Yes. We work the same events. I am friendly with {D.him}, and I know that matters.\""), .cross("Was anything between you and the two people that blocked your view?", "\"A couple of parked trucks, so I saw them between vehicles. I will not say I had a perfect view.\""), .cross("Did you hear what they said to each other?", "\"No, not from forty yards. I saw gestures and a lunge, but not the words.\"")],
        theory: ("{D} stabbed a cowboy.", "A defense."),
        allocution: "\"I am sorry {V} was hurt. I was scared that night, and I wish I had walked away instead of reaching for my knife. I will carry that with me.\"",
        truths: ("{DL} told a hand 'he'll learn' before the fight.", "A broken bottle lay by {V}'s boot."),
        defendant: [.direct("Did you stab {V}?", "\"Yes, I did. {V} charged at me with a bottle, and I was afraid. I used my knife without thinking.\""), .direct("Why were you carrying a knife?", "\"For rope work. I carry it every day at the rodeo, and I did not bring it to fight.\""), .direct("Why did you hide it behind the trailer tire?", "\"I panicked. I did not know what to do after what I had done, and I put it down and stood there.\""), .direct("How did the bet start and how much was it?", "\"We bet on a ride at the arena earlier that day, and I lost a couple hundred dollars. I paid half, and {V} wanted the rest right then.\""), .direct("What happened in the seconds before you pulled the knife?", "\"{V} kept coming closer, yelling, with something glass in hand. I backed up until I hit the trailer. I did not have anywhere to go.\""), .direct("What did you do after the stabbing?", "\"I walked away fast, hid the knife, and stood by the trailer. When deputies came I told them what had happened and did not run.\""), .cross("You told a friend 'that one will learn' before the fight, didn't you?", "\"I said something like that. It was talk. I did not plan to hurt anyone.\""), .cross("You stabbed {V} near the liver. Is that how you stop a bottle?", "\"I did not aim. It was one thrust, and I was afraid. I never meant to hurt {V.him} that badly.\""), .cross("Why hide the knife if you acted in self-defense?", "\"Because I was scared. I know it looks bad, but I was not thinking clearly.\""), .cross("You were angry about the bet, weren't you?", "\"I was sore about it, yes. I'd lost more than I could afford, and I said things I shouldn't have.\""), .cross("Even if {V} had a bottle, why was a knife needed?", "\"I was scared, and the knife was what I had on my belt. I did not think it through. It was one move and then it was done.\"")],
        openings: ("{V} was stabbed in the abdomen in a rodeo arena parking lot after an argument over a bet. Deputies found {D} beside a livestock trailer, with a bloody knife hidden behind a tire.", "{V} charged at {D} with a bottle, and {DL} used a rope-work knife out of fear. The defense will show a broken bottle by {V}'s boot and a split-second decision."),
        closings: ("An argument over money, a knife, a wound near the liver, and a blade hidden behind a tire. A person who acts in true self-defense does not hide the weapon.", "A charging person with a bottle, a frightened rodeo hand, and a single thrust. {D} panicked afterward, as people do, and acted to protect {D.himself}."),
        timeline: [(-1, "The bet is lost."), (0, "9 p.m.: the argument."), (0, "9:08 p.m.: the stabbing."), (0, "9:30 p.m.: {DL} is arrested.")],
        identified: "A rodeo hand and a knife.",
        aggravating: ["The offense involved a weapon"],
        mood: .divided,
        impact: "I nearly bled out in that parking lot. The doctors told me the blade stopped close to my liver, and I still cannot lift or work the way I did before.",
        doctrines: ["selfDefense"],
        genders: ["V": .male])

    static let gravelPlantPayroll = SmallCases.make(
        key: "story.gravelPlantPayroll",
        category: .robbery,
        headlines: ["Masked Men Rob Gravel Plant Payroll Clerk at Gunpoint", "Getaway Truck Found Burned"],
        law: "dangerousRobbery",
        threshold: 8,
        spec: "Took $22,000 belonging to {V} by endangering and threatening {V.his} life with a firearm, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Two masked men took $22,000 from a gravel plant payroll clerk at gunpoint on {DATE}. A truck used in the getaway was found burned. {D}, a former plant hand, was identified by voice. {DL} says {D.he} was at a job site.",
        state: [E(.statement, 3, "Clerk", "'I know that voice. It's {D}.'"), E(.digital, 2, "Phone Location", "{DL}'s phone near the plant at 7:50."), E(.physical, 3, "Burned Truck", "A truck owned by {D}'s cousin.", .search)],
        defense: [E(.document, 1, "Job Ticket", "A ticket placing {DL} at a job site.")],
        role: "Payroll clerk",
        exam: [.direct("What happened at the gravel plant on {DATE}?", "\"Two masked people came in at gunpoint and took $22,000 from me, the payroll clerk. It was just before the morning payroll.\""), .direct("Do you recognize anyone from that robbery?", "\"I recognized a voice. One of them spoke, and I know that voice. It's {D}, a former plant hand I worked beside.\""), .direct("What was found afterward?", "\"A truck used in the getaway was found burned. It's owned by {D.his} cousin. {D.his} phone also pinged near the plant at 7:50.\""), .direct("How did the robbers enter the office?", "\"Two people in ski masks came through the door at 7:45, one pointing a pistol at me. I was alone counting payroll envelopes for the morning crew.\""), .direct("What did they say to you?", "\"The one with the pistol told me to put the cash in a bag and not to push the alarm. The other mostly watched the door and said a few words.\""), .direct("How long were they inside?", "\"Less than two minutes. They took $22,000 and left through the same door. I heard a truck start in the gravel lot and pull out fast.\""), .cross("Both robbers were masked, weren't they?", "\"Yes, they were. I couldn't see a face. I'm going by the voice, and I'm very sure of it.\""), .cross("How long did you hear the voice?", "\"Only a few sentences, under pressure. I was terrified. But I worked with {D.him}, and I know how {D.he} talks.\""), .cross("Could the voice have been someone who sounds like {DL}?", "\"I suppose that's possible. It would have to be a close match. I'm telling you what I believe.\""), .cross("Which robber spoke, the one with the gun or the other?", "\"The one who stood by the door spoke the sentence I recognized. The one with the pistol gave orders in a lower voice.\""), .cross("How many months had it been since you last heard {D}'s voice?", "\"About a month, since {D.he} left the plant. Before that I heard it almost daily at the window during payday.\"")],
        defenseRole: "Job-site foreman",
        defenseExam: [.direct("Was {DL} at your job site on the morning of the robbery?", "\"Yes. {D} was there all morning, working on the crew. I was the foreman and I kept track of everyone.\""), .direct("How do you know?", "\"We had a job ticket, and I saw {D.him} on the site. We were working on a project that had a deadline.\""), .direct("What kind of worker is {DL}?", "\"Dependable. {D.He} shows up and works hard. I've never had any trouble with {D.him}.\""), .direct("How long have you been a foreman?", "\"Nine years on paving and gravel crews. I keep a daily log, assign the crew, and turn in job tickets for every site.\""), .direct("What time did your crew start that morning?", "\"We were on site at 7:30 and I stamped the job ticket then. {D.He} arrived with the crew in the same truck.\""), .direct("What was {D} doing at 7:45?", "\"Spreading gravel with a rake near the edge of the slab. I could see {D.him} from where I was reading grade stakes.\""), .cross("Were you watching {DL} every minute?", "\"Mostly. I had other people to watch too. I can't say I saw {D.him} every single minute.\""), .cross("Could {DL} have left for a while?", "\"Possibly, for a short time. We had a few breaks. I don't recall {D.he} leaving, but I can't rule it out.\""), .cross("Did you tell deputies about the job ticket?", "\"Yes. I gave them what I had. It's what I know.\""), .cross("Did the defendant step away at any point before 8 a.m.?", "\"I do not recall it, but with two dozen things going on I cannot rule out a short break for water or a phone call.\""), .cross("How far is the plant from your job site?", "\"About twenty miles, maybe a thirty minute drive. That means it would take quite a trip to get there and back in a morning.\"")],
        theory: ("{D} robbed a payroll.", "An alibi."),
        allocution: "\"I was at a job site that morning, working a ticket that was stamped before the plant was ever hit. I understand someone thinks they knew my voice, and I understand the clerk is frightened. But I have worked hard and stayed out of trouble since I left that plant. I ask the court to look at where I really was.\"",
        truths: ("{DL} had been fired a month earlier.", "The job ticket was stamped at 7:30 a.m. at a site twenty miles away."),
        defendant: [.direct("Where were you on the morning of the robbery?", "\"At a job site. I'd started work early, and I was there for most of the morning. I wasn't anywhere near the gravel plant.\""), .direct("Why was your phone near the plant at 7:50?", "\"I don't know. I may have been in the area, since the plant is not far from some of our jobs. I never went in.\""), .direct("What about your cousin's truck?", "\"I don't know anything about it being burned. My cousin lets other people use the truck. I didn't use it that day.\""), .direct("What do you do for work now?", "\"I took a job on a paving crew a few weeks after the plant let me go. We start at the job site early, usually by seven thirty.\""), .direct("Where were you at 7:45 a.m. that morning?", "\"At a job site about twenty miles from the plant, laying gravel base. I stamped a job ticket when I arrived.\""), .direct("How are you coping with what happened?", "\"I was upset about losing my job, and I will not hide that. But I would not rob anyone, and I am not that kind of person.\""), .cross("You used to work at the gravel plant, didn't you?", "\"Yes. I know the layout and the people. That's why I'm a suspect. But I didn't rob anyone.\""), .cross("The clerk says it was your voice, doesn't {V.he}?", "\"The clerk is mistaken. I understand the clerk was scared. But I wasn't there.\""), .cross("The burned truck belongs to your cousin, doesn't it?", "\"Yes. I have no idea who took it. I didn't set it on fire.\""), .cross("Why was your phone near the plant at 7:50 if you were twenty miles away?", "\"I cannot explain it. Phone location can be rough, and I do not know what the record reflects, but I was at the job site.\""), .cross("Your cousin's truck burned and you cannot say who had it. How is that not a coincidence?", "\"I do not know. My cousin lends it out, and I did not have it that morning. I wish I had better answers.\"")],
        openings: ("Two masked people took $22,000 from a gravel plant payroll clerk at gunpoint. The clerk knew one voice: {D}, a former plant hand. A getaway truck owned by {D.his} cousin was found burned, and {D.his} phone was near the plant. The State will present it all.", "The defense evidence includes a job ticket and a foreman who put {D} at a job site all morning. Both robbers were masked, and a voice alone is not enough to convict."),
        closings: ("A voice the clerk knows, a truck owned by {D}'s cousin, and a phone near the plant at 7:50. Each piece alone could be explained, but together they are not a coincidence.", "Both robbers wore masks, and a frightened clerk heard a few sentences. A foreman puts {D} at work all morning. The State has not proved who was behind that mask."),
        timeline: [(-30, "{DL} is fired."), (0, "7:45 a.m.: the robbery."), (0, "8:10 a.m.: the truck burns."), (1, "{DL} is identified.")],
        identified: "A voice.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        impact: "I still hear that voice behind me at the window, telling me not to move. I counted the payroll for those men for six years, and that morning I thought I would never see my kids again. I jump when anyone walks into the office now, and I haven't been able to go back.",
        doctrines: ["alibi", "eyewitnessID"])

    static let boxCutterStation = SmallCases.make(
        key: "story.boxCutterStation",
        category: .robbery,
        headlines: ["Gas Station Clerk Robbed With Box Cutter at Closing", "Clerk Hands Over $410"],
        law: "commonLawRobbery",
        threshold: 8,
        spec: "Took $410 belonging to {V} by violence or fear, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A man raised a box cutter at a gas station clerk at closing on {DATE} and took $410. {D} was arrested hours later with the cash and a box cutter in his truck. {DL} says the cash was from a pawned tool.",
        state: [E(.video, 3, "Store Camera", "A man in a cap raises a box cutter."), E(.physical, 3, "Truck Search", "$410 and a box cutter under the seat.", .search), E(.statement, 2, "Clerk", "'He wore a gray cap.'")],
        defense: [E(.document, 1, "Pawn Slip", "A pawn slip for $400 earlier that day.")],
        role: "Gas station clerk",
        exam: [.direct("What happened at your station at closing on {DATE}?", "\"A person in a gray cap raised a box cutter at me and demanded the cash. I handed over $410, and the person left.\""), .direct("What does your store camera show?", "\"A person in a cap raising a box cutter. It shows the whole robbery, but the face is partly covered by the cap.\""), .direct("What did deputies find?", "\"Hours later, they searched {D}'s truck and found $410 and a box cutter under the seat.\""), .direct("What time did the robbery happen and what were you doing?", "\"Close to 10:55 p.m., just as I was locking up. I was counting the drawer when someone stepped through the door in a gray cap and pulled out a box cutter.\""), .direct("What did the robber do with the box cutter?", "\"Held it up near my face with the blade out and told me to hand over the cash. I gave the drawer contents, $410, and the robber backed out.\""), .direct("What did you do afterward?", "\"I locked the door, called 911 at about 11, and waited for deputies. I could not stop shaking. I gave them the video and my description.\""), .cross("Could you identify {DL}?", "\"I could not identify a face with certainty. I remember the gray cap and the box cutter. I can't swear it was {DL}.\""), .cross("Did the robber say anything?", "\"Only to give up the cash. I didn't hear enough to recognize a voice. I was afraid.\""), .cross("Is $410 a common amount to be in a cash drawer?", "\"It's about what we have at closing. It's not a unique number. Lots of people carry that much cash.\""), .cross("How tall was the robber compared with you?", "\"About my height, a bit heavier. The cap was pulled down, and I looked at the blade more than the face, so I cannot be more exact.\""), .cross("Did you see which direction the robber went?", "\"Out the front door and left. I did not follow. I stayed behind the counter until the person was out of sight.\"")],
        defenseRole: "Pawn clerk",
        defenseExam: [.direct("Do you remember {DL} coming to your pawn shop?", "\"Yes. {D} brought in a tool and I wrote a pawn slip for about $400.\""), .direct("What kind of transaction was it?", "\"A routine pawn loan. We took the tool, gave cash, and recorded the slip. I do it many times a day.\""), .direct("How did {DL} act?", "\"Ordinary. {D.He} was polite and wasn't in a hurry. Nothing stood out about the visit.\""), .direct("How long have you worked at the pawn shop?", "\"Six years. I handle the counter, write every slip, and make sure each item gets a ticket number and a date.\""), .direct("What do you remember about the tool {D} brought in?", "\"A cordless power tool with a case. {D.He} asked for the highest loan I could give, and I offered about $400.\""), .direct("What is on a pawn slip?", "\"The customer's name, an ID number, a description of the item, the loan amount, and a date. We also have a camera over the counter.\""), .cross("When did {DL} come in?", "\"I don't recall exactly. It's all on the slip, but I don't remember the time off the top of my head.\""), .cross("Could it have been after the robbery?", "\"I can't rule that out from memory. I'd have to check the slip and the shop camera.\""), .cross("Do you see many people pawn tools?", "\"Constantly. I can't remember each one. I only recall {D.he} when I look at the slip.\""), .cross("Does the slip record the time of day?", "\"Only the date. The camera timestamp would show the time, but I did not pull it myself.\""), .cross("Do you remember what the defendant was wearing?", "\"I do not. I see so many people that I only remember faces when I look at the slip or the video.\"")],
        theory: ("{D} robbed a clerk.", "A pawn."),
        allocution: "\"I did not rob that station. I pawned a tool that afternoon to get cash for my truck payment, and the pawn shop has me on camera that night. I know it looks bad that I had a box cutter in my truck, but I use it for work. I feel for the clerk, but I wasn't the one.\"",
        truths: ("The pawn slip is dated after the robbery.", "The pawn shop's camera shows {DL} there at 9 p.m."),
        defendant: [.direct("Did you rob the gas station?", "\"No. I didn't. I was somewhere else. I had cash from a pawned tool, and that's what was in my truck.\""), .direct("Where did the $410 come from?", "\"I pawned a tool earlier that day for about $400. That, plus a little of my own, was the cash in my truck.\""), .direct("Why was there a box cutter under your seat?", "\"I use it for work. I keep one in the truck for opening boxes and cutting straps. It's not unusual.\""), .direct("What did you do the day of the robbery?", "\"I worked a job in the morning and ran errands. At some point that day I took a power tool to the pawn shop because I needed to turn it into cash.\""), .direct("Why did you need that money?", "\"Rent was due and my truck needed a repair. Pawning a tool was the fastest way I knew to cover both.\""), .direct("Where were you when deputies stopped you at 1 a.m.?", "\"Driving home from a friend's place. They pulled me over, asked to search, and I agreed because I had nothing to hide.\""), .cross("You were found with $410 hours after the robbery, weren't you?", "\"Yes. It's the same amount. It looks bad, I know. But it was my money from the pawn.\""), .cross("You can't say exactly when you pawned the tool, can you?", "\"It was earlier that day. I don't recall the time exactly. I have a slip.\""), .cross("You wear a gray cap, don't you?", "\"Lots of people have gray caps. I'm not denying I own one.\""), .cross("You were found with $410 and a box cutter. Isn't it likely that the robber and you are the same person?", "\"I know why it looks that way. But I did not rob anyone, and I can show where the money came from.\""), .cross("Your pawn slip shows roughly $400. How does that become $410 exactly?", "\"I had a few dollars of my own in my pocket. I did not count it to match anything.\"")],
        openings: ("At closing, a person in a gray cap raised a box cutter at a gas station clerk and took $410. Hours later, deputies found $410 and a box cutter under the seat of {D}'s truck. The State will show the video and the search.", "The defense will point you to a pawn slip for a tool, cash that came from it, and a common work tool in a work truck. The robber's face was never seen."),
        closings: ("A box cutter raised at the clerk, $410 taken, and the same $410 and a box cutter found in {D}'s truck hours later. That's no coincidence.", "The clerk could not identify a face. {D} had cash from a pawned tool and a work tool. The State cannot tie those items to this robbery."),
        timeline: [(0, "10:55 p.m.: the robbery."), (0, "11 p.m.: the clerk calls."), (0, "1 a.m.: {DL} is stopped."), (0, "1:20 a.m.: the search.")],
        identified: "A camera and a search.",
        aggravating: ["The offense involved a weapon"],
        mood: .wantsConviction,
        impact: "I quit that night and never went back. {D.He} held that blade up at me while I counted the drawer, and four hundred dollars is not worth what it did to me. I jump at every customer who comes in late now. I took a job in a daytime office, and I still check the door behind me.",
        doctrines: ["searchSeizure"],
        genders: ["D": .male])

    static let jewelrySmashGrab = SmallCases.make(
        key: "story.jewelrySmashGrab",
        category: .property,
        headlines: ["Window Smashed at Jewelry Store; Trays Grabbed in Seconds", "Hammer Left in Alley"],
        law: "burglary2",
        threshold: 7,
        spec: "Broke and entered a building, a jewelry store owned by {V}, with intent to commit larceny, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A jewelry store window was smashed at 4 a.m. on {DATE} and eleven trays were taken. A hammer left in an alley bore {D}'s prints. {DL} says {D.he} sold the hammer weeks earlier.",
        state: [E(.forensic, 3, "Fingerprints", "{D}'s prints on the hammer."), E(.video, 2, "Alley Camera", "Two figures run."), E(.document, 2, "Inventory", "$64,000 missing.")],
        defense: [E(.document, 1, "Sale Message", "A message offering the hammer for sale.")],
        role: "Jewelry store owner",
        exam: [.direct("What happened at your jewelry store at 4 a.m. on {DATE}?", "\"The window was smashed and eleven trays of jewelry were taken. The inventory shows $64,000 missing.\""), .direct("What was found in the alley?", "\"A hammer, left behind. Fingerprints on it matched {D}. It was in the alley behind the store.\""), .direct("What does the alley camera show?", "\"Two figures running. It's dark and the quality isn't great, but you can see them move away fast.\""), .direct("How did you find out about the break-in?", "\"The alarm company called at about 4 a.m. I drove over and found the front window shattered and glass across the display trays.\""), .direct("How did the break-in affect your business?", "\"We had to close for a day to replace the window, and the insurance deductible alone cost us thousands of dollars.\""), .direct("What did deputies do at the scene?", "\"They photographed the glass and the alley, collected the hammer, and dusted it for prints before anyone else touched it.\""), .cross("Can you identify the two figures?", "\"No. The images are poor. I can't tell who they are from the alley camera.\""), .cross("{DL} says {D.he} sold the hammer weeks earlier, doesn't {D.he}?", "\"I can't dispute that someone else might have owned the hammer when it was used.\""), .cross("Was the hammer found at the window itself?", "\"It was in the alley, a short distance away. I can't say who dropped it or when.\""), .cross("You did not see the break-in yourself, did you?", "\"That's right. I arrived after it was over, so everything I know is from the camera and the deputies.\""), .cross("Could a hammer like that be bought anywhere?", "\"Yes. It is a standard framing hammer sold at hardware stores. Many people own one, and I have no reason to think it is unusual.\"")],
        defenseRole: "Hardware clerk",
        defenseExam: [.direct("Does {DL} buy tools from your hardware store?", "\"Often. {D} comes in regularly. I've sold {DF} many hammers and other tools over time.\""), .direct("What kind of customer is {DL}?", "\"Reliable and polite. {D.He} comes in, buys what's needed, and goes. I've never had any trouble.\""), .direct("Have you seen {DL} sell tools?", "\"I've seen {DF} sell some. People trade tools around here, and it's a small town.\""), .direct("How long have you worked at the hardware store?", "\"Eight years. I run the register and stock the tool wall, so I see most of the hammers and hand tools we sell.\""), .direct("What kind of hammer is this one?", "\"A twenty-ounce framing hammer, a popular model. We sell a few dozen in a year, and many contractors own several.\""), .direct("Has {DL} ever traded in tools here?", "\"A few times. {D.He} brought in a set of wrenches once and traded them toward a new set.\""), .cross("Did you sell {DL} this particular hammer?", "\"Maybe. I sell a lot of hammers. I can't say it was this one.\""), .cross("You didn't see anything in the alley that night, did you?", "\"No. I only know hammers and customers, and I wasn't anywhere near the alley.\""), .cross("Can you say when {DL} bought it?", "\"No. I'd have to look at old records, and I haven't done that.\""), .cross("Do you keep records of who buys each hammer?", "\"Not by name unless they pay by card. Most hammer sales are cash, so I could not say who bought this one.\""), .cross("Did the defendant ever tell you about selling this hammer?", "\"No. I never heard about this specific sale, only that {D.he} swaps tools sometimes.\"")],
        theory: ("{D} smashed a window and grabbed trays.", "A sold hammer."),
        allocution: "\"That hammer was mine once, and I sold it weeks before the break-in. Of course my prints are on it, since I owned it and used it for years. I put up a notice offering it for sale, and anyone could have bought it. I'm sorry for the owner's loss, but I did not smash that window.\"",
        truths: ("{DL}'s prints were on the head and handle.", "A buyer's message shows the hammer changed hands days earlier."),
        defendant: [.direct("Is that your hammer?", "\"It was mine. I sold it a few weeks before the break-in. I'd put up a message offering it for sale.\""), .direct("Why were your fingerprints on it?", "\"Because I owned and used it. My prints would be on it, from the time I had it. That doesn't mean I used it on a window.\""), .direct("Where were you at 4 a.m.?", "\"Home asleep. I don't have anyone who can say so. But I wasn't at that store, and I didn't smash anything.\""), .direct("When did you list the hammer for sale?", "\"A few weeks before the break-in, after I switched to a different set of tools. I posted it online with a price and a photo.\""), .direct("How did the sale go?", "\"A buyer messaged me and we met in a parking lot. I handed over the hammer, took cash, and did not ask for a name.\""), .direct("How did you find out about the break-in?", "\"Deputies came to my door and asked about the hammer. I told them I had sold it and showed them the message.\""), .cross("Your prints are on a hammer found near a smashed window, aren't they?", "\"Yes. I explained why. I don't know who used it, only that it wasn't me.\""), .cross("You can't name who you sold it to, can you?", "\"I have the message, but I don't remember a name. It was a quick sale. I know that's thin.\""), .cross("Eleven trays of jewelry is a lot, isn't it?", "\"Yes. I know nothing about that. I've never been in a jewelry heist in my life.\""), .cross("You cannot name the buyer and you have no receipt. Isn't that convenient?", "\"It is how I sell things. I have sold tools to strangers for years. I did not know I would ever need proof.\""), .cross("The buyer's message shows the hammer changed hands weeks before the break-in, doesn't it?", "\"Yes. That is why I kept the message. I sold it weeks ago, and I have no idea who used it at 4 a.m.\"")],
        openings: ("At 4 a.m. a jewelry store window was smashed and eleven trays worth $64,000 were taken. A hammer left in the alley bears {D}'s fingerprints. The State will show the prints and the inventory.", "The defense will present a hammer {D} says was sold weeks earlier, an alley camera that cannot identify anyone, and a print that does not say when it was left."),
        closings: ("Eleven trays gone, a hammer in the alley, and {D}'s fingerprints on it. {D.He} owned that hammer, and it was used in a smash-and-grab.", "A print on a hammer cannot tell you when it was handled. {D} says it was sold, and the camera shows only two figures. The State has not placed {D.him} at that window."),
        timeline: [(-14, "The hammer is listed."), (0, "4 a.m.: the smash."), (0, "4:01 a.m.: the run."), (0, "8 a.m.: the owner counts.")],
        identified: "A hammer print.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "Thirty years of stock went out of that window in one night. My father started that store, and I stood in it every day since I was a kid. Some of those trays were wedding rings people had paid on for months. I don't know how I will face the families who trusted me.",
        doctrines: ["burdenOfProof"])

    static let dayCareNightFire = SmallCases.make(
        key: "story.dayCareNightFire",
        category: .violent,
        headlines: ["Day Care Burns Overnight; Ex-Employee Charged", "Accelerant Found at Back Door"],
        law: "arson1",
        threshold: 8,
        spec: "Willfully and maliciously burned the dwelling of {V}, a day care operator, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A day care building burned overnight on {DATE}. No children were inside. Fire investigators found accelerant at the back door. {D}, a fired employee, was seen nearby. {DL} says {D.he} was walking home.",
        state: [E(.forensic, 3, "Fire Report", "Accelerant at the back door."), E(.video, 2, "Gas Station Camera", "{D} buys a gas can at midnight."), E(.statement, 2, "Neighbor", "Saw {D} nearby.")],
        defense: [E(.statement, 1, "Walk", "{DL} says {D.he} was walking home.")],
        role: "Fire investigator",
        exam: [.direct("What did you find at the day care on {DATE}?", "\"The building burned overnight. No children were inside. I found accelerant at the back door, and that's where the fire began.\""), .direct("What else did your investigation show?", "\"A gas station camera shows {D} buying a gas can at midnight. {DL} was a fired employee of the day care.\""), .direct("Who saw {DL} near the day care?", "\"A neighbor saw {DL} nearby that night. That neighbor gave us a statement that the person was close to the building.\""), .direct("Where did the fire start and how did you determine that?", "\"At the back door of the building. Burn patterns pointed outward from that spot, and the lowest, deepest charring was along the threshold.\""), .direct("What was recovered from the back door area?", "\"Samples of burned debris that tested positive for an ignitable liquid. We found no sign of an electrical or kitchen cause.\""), .direct("What time did the fire start and how was it reported?", "\"A passing motorist reported flames at about 1:30 a.m., and crews arrived by 2. The building was a total loss, but no one was inside.\""), .cross("Did anyone see {DL} at the back door?", "\"No. I have no witness to that. The neighbor saw {DL} nearby, not at the door.\""), .cross("{DL} says {D.he} was walking home, doesn't {D.he}?", "\"That's possible. But buying a gas can at midnight and being nearby is a pattern I couldn't ignore.\""), .cross("Was the accelerant the same as what was in the can?", "\"I can't say. I identified accelerant at the scene, but I didn't link it to a specific can.\""), .cross("Can the lab say the liquid was gasoline from a particular can?", "\"No. It identified an ignitable liquid. It did not tie that liquid to a specific container or purchase.\""), .cross("Was there any camera at the day care itself?", "\"No. The building had no working exterior camera, so nothing shows who approached the door.\"")],
        defenseRole: "Gas station clerk",
        defenseExam: [.direct("What did {DL} buy at your station that night?", "\"A gas can and some gas. {D} came in around midnight, paid, and left.\""), .direct("How did {DL} seem?", "\"Calm and ordinary. {D.He} wasn't in a hurry, and didn't act strange. It was a normal transaction.\""), .direct("Has {DL} been in before?", "\"Yes, a few times. I recognize {DF}. {DF} is a regular and has always been polite.\""), .direct("How long have you worked the overnight register?", "\"Three years, usually from ten to six. I know most of the late customers because the same people come in again and again.\""), .direct("What did {D} buy that night, and how did the sale go?", "\"A red plastic gas can and a few gallons of fuel, paid with a card. It was a short, ordinary sale at about midnight.\""), .direct("Did the defendant say anything about why the gas was needed?", "\"Something about the mower being low. I do not recall the exact words. It was routine small talk.\""), .cross("Did {DL} fill the can?", "\"I don't know. I was inside. I didn't watch what {D.he} did at the pump.\""), .cross("Did you see where {DL} went afterward?", "\"No. {D.He} left, and I went back to work. I didn't see anything after that.\""), .cross("What time exactly did {DL} come in?", "\"Around midnight. I don't have the exact minute. The camera would show it better than I can.\""), .cross("Did the defendant leave toward the day care or the other way?", "\"I did not watch. The camera over the door would show the direction, but I only watched the register.\""), .cross("Do you know whether the gas was used for anything other than a mower?", "\"No. I only saw the sale. What happened after that is outside what I know.\"")],
        theory: ("{D} burned a day care.", "A walk."),
        allocution: "\"I worked at that day care, and it makes me sick to think of it burning. I was walking home that night the way I always did, and I did not set that fire. I love those children, and I would never put them or their families through this. I understand people are angry, and I hope the court will see the truth.\"",
        truths: ("{DL} bought a gas can at midnight.", "The can was in {DL}'s garage with mower oil residue."),
        defendant: [.direct("Did you set the day care on fire?", "\"No. I would never do that. Children go there every day, and I worked there. It makes me sick.\""), .direct("Why were you near the day care at night?", "\"I was walking home. It's on my way. I'd been out late, and I walked past it like I always do.\""), .direct("Why did you buy a gas can at midnight?", "\"For my mower. I'd run out of gas the day before and needed to get the yard done. I bought the can and gas at the station.\""), .direct("Why did you leave the day care job?", "\"I was let go after a disagreement with the director over my schedule. I was upset, but I found another night job and moved on.\""), .direct("Where did you walk that night?", "\"I came from a friend's apartment toward home. That route runs past the day care, and I passed it before midnight.\""), .direct("What did you do with the gas can after buying it?", "\"I carried it home, set it in the garage, and went to bed. I used it on the mower the next afternoon.\""), .cross("You were fired from the day care, weren't you?", "\"Yes. I was angry about it. But I didn't burn the building. I wouldn't hurt anyone's livelihood.\""), .cross("You bought a gas can at midnight, didn't you?", "\"Yes. It was late. That's when I was out. I didn't think about how it looked.\""), .cross("You were near the building when it burned, weren't you?", "\"I walked past earlier that night. I wasn't there when the fire started. I was at home.\""), .cross("You bought gasoline at midnight and a fire started at the day care ninety minutes later. Do you see why that troubles people?", "\"I do. It looks bad, and I wish I had waited until morning. But I was not anywhere near the building when it burned.\""), .cross("Nobody can say you were home when the fire started, can they?", "\"No. I live alone. I was asleep, and I know that is not much to offer the jury.\"")],
        openings: ("A day care burned overnight with accelerant at the back door. {D}, a fired employee, was seen nearby, and a gas station camera shows {DL} buying a gas can at midnight. The State will present the fire investigator and the neighbor.", "Jurors will also see someone walking home along a familiar route, a gas can bought for a mower, and no witness who saw anyone at that back door."),
        closings: ("A fired employee, a gas can bought at midnight, accelerant at the back door, and {D} seen nearby. A fire investigator can tell you how it started, and the rest points to {D.him}.", "Walking home and buying a gas can are not arson. No one saw {D} at the door, and the State cannot tie that can to the fire."),
        timeline: [(-10, "{DL} is fired."), (0, "12:05 a.m.: the can is bought."), (0, "1:30 a.m.: the fire."), (0, "2 a.m.: crews arrive.")],
        identified: "Accelerant and a purchase.",
        aggravating: ["The offense involved a weapon"],
        mood: .wantsConviction,
        impact: "Twenty families lost care the morning that building burned. I opened that center twelve years ago, and I had a waiting list of parents who had nowhere else to go. Some of them lost their jobs when they could not find a place for their children. I still drive past the blackened walls every morning.",
        doctrines: ["burdenOfProof"])

    static let nurseSalineSwap = SmallCases.make(
        key: "story.nurseSalineSwap",
        category: .whiteCollar,
        headlines: ["Nurse Replaced Patients' Opioids With Saline, Records Show", "Pain Reports Rise on One Floor"],
        law: "prescriptionFraud",
        threshold: 7,
        spec: "Obtained controlled substances by fraud and deception from {V}, a hospital, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Pain complaints rose on a hospital floor over two months. {D}, a night nurse, withdrew more opioids than any other nurse. Vials were found refilled with saline. {DL} says the dispensing machine was faulty.",
        state: [E(.digital, 3, "Dispensing Log", "{D} withdrew double the floor average."), E(.forensic, 3, "Vial Testing", "Saline in six vials."), E(.document, 2, "Pain Reports", "Complaints rose on {D}'s shifts.")],
        defense: [E(.statement, 1, "Machine", "{DL} says the machine was faulty.")],
        role: "Hospital pharmacist",
        exam: [.direct("What did you notice about the opioid withdrawals on that floor?", "\"Over two months, {D}, a night nurse, withdrew more opioids than any other nurse, roughly double the floor average.\""), .direct("What did testing show about the vials?", "\"Six vials were found refilled with saline. The labels said opioid, but the contents tested as plain saline.\""), .direct("What happened with the patients on {D}'s shifts?", "\"Pain complaints rose on {DL}'s shifts. The pain reports from the floor line up with the nights {DL} worked.\""), .direct("How did the audit begin?", "\"Pain complaints on that floor started to climb, so we compared dispensing logs by nurse and shift. {D.his} numbers stood out as about double the average.\""), .direct("How were the six vials identified?", "\"Nurses flagged vials that looked right but had broken seals. We tested them, and each contained saline rather than the labeled opioid.\""), .direct("When was the defendant suspended?", "\"In week nine, after the audit report and the testing came back. The hospital placed {D.him} on leave pending review.\""), .cross("The floor was very busy on those nights, wasn't it?", "\"Yes, nights can be hectic. But a busy floor does not explain vials refilled with saline.\""), .cross("The dispensing machine had a fault, didn't it?", "\"There was a ticket about the machine. I will have to say it may have had issues, but I cannot say it explains the double.\""), .cross("Did anyone see the defendant swap a vial?", "\"No. Nobody saw {DL} swap anything. We have logs and test results.\""), .cross("Did the hospital review other nurses on the floor who had high numbers?", "\"Yes, we reviewed several. {D.He} was the highest by a wide margin, but others had elevated numbers on busy shifts.\""), .cross("When was the machine last serviced before the audit?", "\"There was a service ticket about a month before the swaps began. I do not have the repair details in my head.\"")],
        defenseRole: "Charge nurse",
        defenseExam: [.direct("Did the dispensing machine have problems?", "\"Yes. It glitched at times, and I had to call for service a few times that spring.\""), .direct("On whose shifts did the glitches happen?", "\"Mostly on {D}'s shifts. I know that sounds bad, but it was the night shift when the machine seemed most unreliable.\""), .direct("How did {D} handle patients?", "\"{DF} was careful and attentive. I never saw {DF} neglect a patient or cut a corner.\""), .direct("How long have you been charge nurse on that floor?", "\"Seven years. I handle assignments, review the machine logs, and sign off on supply orders.\""), .direct("How did you handle the machine tickets?", "\"Whenever a nurse reported an issue, I put in a service ticket. I logged several during the spring that involved the night shift.\""), .direct("What did you see of the defendant's practice at the bedside?", "\"Careful. {D.He} double-checked orders, charted promptly, and never complained about the workload.\""), .cross("When was the machine's ticket opened?", "\"It was before the swaps began, as I recall. That might be a problem for the defense.\""), .cross("Did other nurses report glitches?", "\"Not many. Mostly it was {DF} who told me about them.\""), .cross("Did you personally watch the defendant dispense each dose?", "\"No. I did not watch every dose. I was at the station most nights.\""), .cross("Did you ever test the machine yourself after a report?", "\"Once, and it worked fine for me. That does not mean it never failed for someone else.\""), .cross("Why were most of the tickets about the defendant's shifts?", "\"Because {D.he} worked nights and was the one who spoke up. I did not hear many other nurses report problems.\"")],
        theory: ("{D} diverted opioids.", "A faulty machine."),
        allocution: "\"I've been a nurse for a long time, and I have never wanted any patient to suffer. I did not swap anything, and I believe that machine was faulty and that the withdrawals were misread. I worked a busy floor, and my patients needed their medicine. I'm sorry that anyone was in pain, and I stand by my work.\"",
        truths: ("{DL} had a prior counseling referral.", "The machine's ticket predates the swaps."),
        defendant: [.direct("Did you swap the opioids for saline?", "\"No. I did not swap anything. I would never put a patient in pain on purpose.\""), .direct("Why did you withdraw so much?", "\"My patients needed it. The floor was busy, and I had several patients with serious pain.\""), .direct("What about the machine?", "\"It glitched and sometimes gave me extra or wrong amounts. I reported it, and I did not control it.\""), .direct("What does a night shift look like on that floor?", "\"Twelve hours, often with a dozen patients on pain management. I hand out scheduled doses and respond to call lights all night.\""), .direct("What problems did you notice with the dispensing machine?", "\"It would sometimes hang, give an error, or dispense the wrong count. I called for service and wrote it up whenever it happened.\""), .direct("How did you react when you heard vials had saline?", "\"I was horrified. I asked to cooperate in any way, handed over my records, and told them about the machine problems.\""), .cross("You withdrew double the floor average, didn't you?", "\"I had a heavy patient load. The numbers look high, but they track the patients.\""), .cross("Six vials had saline in them. Who else handled them?", "\"I do not know. I did not refill any vials.\""), .cross("You had been referred to counseling before, hadn't you?", "\"Yes, years ago, for stress. It had nothing to do with this.\""), .cross("The complaints rose on your shifts. How does a faulty machine explain that?", "\"I cannot say, but patients on my nights were the ones with the heaviest pain, and the machine was what I used every night.\""), .cross("How long ago was the counseling?", "\"Six or seven years. It was a short course through my old job, and it ended long before any of this.\"")],
        openings: ("Over two months, pain complaints rose on a hospital floor while {D}, a night nurse, withdrew double the average amount of opioids. Six vials were later found refilled with saline.", "By the end of this trial, the proof will show that the dispensing machine was faulty, that {D} had a heavy patient load, and that nobody saw {DL} swap a single vial."),
        closings: ("Double the withdrawals, six vials of saline, and pain complaints that rose on {D}'s shifts. Put those facts side by side, and they point to one night nurse and no one else.", "A faulty machine, a heavy floor, and no witness to any swap. The State has shown numbers on a log, but it has not shown that {D} ever took a single dose."),
        timeline: [(-60, "Complaints begin."), (0, "Week 8: the audit."), (0, "Week 8: vials tested."), (0, "Week 9: {DL} is suspended.")],
        identified: "Dispensing logs.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .divided,
        impact: "I was in pain for days after my surgery, and the nurse kept telling me the medicine was on its way. I couldn't sleep or get up to walk, and my family thought something was terribly wrong. When I learned that what I was given might have been salt water, I felt betrayed. I still have trouble trusting anyone in a hospital.",
        doctrines: ["burdenOfProof"])

    static let motelMethRoom = SmallCases.make(
        key: "story.motelMethRoom",
        category: .drugs,
        headlines: ["Motel Room Used as Methamphetamine Lab, Deputies Say", "Chemical Smell Draws Complaints"],
        law: "maintainingDwelling",
        threshold: 8,
        spec: "Knowingly kept and maintained a motel room used for keeping and selling controlled substances, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Guests complained of chemical smells at a motel on {DATE}. Deputies found lab equipment and methamphetamine in a room rented by {D} for three weeks. {DL} says friends used the room while {D.he} was away.",
        state: [E(.physical, 3, "Lab Equipment", "Glassware and precursors.", .search), E(.document, 3, "Registration", "Room rented by {D} for 21 days."), E(.forensic, 2, "Lab Report", "Methamphetamine residue.")],
        defense: [E(.statement, 1, "Friends", "{DL} says friends used the room.")],
        role: "Deputy",
        exam: [.direct("Why were you called to the motel?", "\"Guests complained of chemical smells. When we arrived, the smell was strong near one room, and we entered with the manager.\""), .direct("What did you find inside the room?", "\"Glassware and precursor chemicals, set up like a lab. The lab report found methamphetamine residue on the equipment.\""), .direct("Who rented the room?", "\"{D} rented it for twenty-one days. The registration shows {D.his} name for the whole three weeks.\""), .direct("What was the scene like when you opened the door?", "\"A strong chemical smell hit us at the threshold. We saw glassware on the counter, tubing, bottles of solvents, and open containers near the bathroom.\""), .direct("What exactly was collected as evidence?", "\"Glassware, containers, and residue samples. The lab found methamphetamine residue, and the room was taken out of service for cleanup.\""), .direct("Did anyone report seeing people come and go from that room?", "\"The manager said a few visitors came and went at odd hours, but could not describe any of them or say on which days.\""), .cross("{D} says friends used the room while {D.he} was away, doesn't {D.he}?", "\"Yes. {DL} said that, but I did not find anyone who could say who used it and when.\""), .cross("Were other fingerprints found on the glassware?", "\"Yes. Other prints were found on it. Not all were {DL}'s.\""), .cross("Was the defendant in the room when you arrived?", "\"No. {D.He} was not there. The room was empty when we entered.\""), .cross("How many people had keys to that room?", "\"The desk issues two keys per rental. I do not know whether others had copies or whether {D.he} gave one out.\""), .cross("Did you find any of the defendant's personal belongings in the room?", "\"A bag with some clothes and a phone charger. Nothing that told me how often {DL} slept there.\"")],
        defenseRole: "Housekeeper",
        defenseExam: [.direct("Who did you see enter the room?", "\"Several people. I saw different visitors come and go during the three weeks.\""), .direct("Was {D} one of them?", "\"Sometimes. I saw {D} there on some days, but not every day. Mostly it was other visitors.\""), .direct("What did you notice about the room?", "\"A strong chemical smell that got worse. I reported it to the manager.\""), .direct("How long have you been cleaning rooms at the motel?", "\"Four years. I clean about eighteen rooms a shift and know when a guest has been staying or when visitors keep coming and going.\""), .direct("Did anything come of your report?", "\"Not that I saw. The smell stayed, and no one came to check the room while I lived there.\""), .direct("How often did you see the defendant there?", "\"Occasionally, a few days a week. Other times the room seemed to be occupied by people I did not recognize.\""), .cross("Did you know any of the visitors?", "\"No. I did not know who they were. I only saw them come and go.\""), .cross("Did you see the defendant bring anything into the room?", "\"I do not recall specifically. I cleaned the room, but I did not watch.\""), .cross("How often was the defendant there?", "\"I would say a few days a week. It was not constant.\""), .cross("Did you go into the room to clean it?", "\"I was told to skip it after a guest complained about the smell. I only went in the doorway, so I never saw the full room.\""), .cross("Can you describe any of the visitors?", "\"Not well. I saw a few people in jackets and caps passing by, but I could not pick them out.\"")],
        theory: ("{D} kept a lab.", "Friends used it."),
        allocution: "\"I rented that motel room, and I am responsible for who I let stay there. I let friends use it while I was away and never asked what they were doing, which was foolish of me. That lab was not mine, and I did not know about it. I'm sorry for the guests who were frightened by the smell.\"",
        truths: ("{DL}'s ID was on three receipts for precursors.", "Other prints were on the glassware."),
        defendant: [.direct("Was the lab yours?", "\"No. I did not set up a lab. I rented the room, but it was not my equipment.\""), .direct("Who used the room?", "\"Friends. I let them stay while I was away, and I did not ask what they were doing.\""), .direct("What about the receipts with your ID?", "\"They were errands. I was asked to buy a few things, and I did not know what they were for.\""), .direct("Why did you rent the room for three weeks?", "\"I was between places and needed somewhere to stay while I worked a temporary job. A weekly rate was cheaper than paying night by night.\""), .direct("Who stayed in the room while you were away?", "\"A couple of friends who said they needed a place for a few nights. I handed over a key and did not check on them.\""), .direct("How did you react when you learned what was found?", "\"I was shocked. I told the deputies I had rented the room and let others use it, and I did not try to hide that.\""), .cross("Your ID is on three receipts for precursor chemicals, isn't it?", "\"Yes. I bought some things for friends. I did not know what they would do with them.\""), .cross("You cannot name the friends who used the room, can you?", "\"I can't name the friends who used the room, only by nicknames.\""), .cross("You rented the room for twenty-one days. Why so long?", "\"I needed a place to stay for a while. I did not think about what else would happen there.\""), .cross("Did you ask the friends what the chemicals were for?", "\"No. I didn't ask, and they didn't say. I bought what they asked for and handed it over.\""), .cross("If you let friends use your room, why can you not name them?", "\"I only knew them by nicknames. That is embarrassing to admit, and I understand how it sounds.\"")],
        openings: ("Motel guests complained of chemical smells, and deputies found lab equipment and methamphetamine residue in a room that {D} had rented for twenty-one days. Receipts with {D.his} ID show precursor purchases.", "The defense will present evidence that {D} was often away, that friends used the room, and that other people's fingerprints are on the glassware."),
        closings: ("A room rented by {D} for three weeks, a drug lab inside, and {D.his} ID on receipts for the chemicals. The pieces fit one story.", "Other fingerprints on the glassware, many visitors to the room, and a renter who was often away. The State has not proved {D} ran this lab."),
        timeline: [(-21, "{DL} rents the room."), (0, "Noon: complaints."), (0, "1 p.m.: deputies enter."), (0, "2 p.m.: the lab is found.")],
        identified: "A registration.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure"])

    static let pillMillClinic = SmallCases.make(
        key: "story.pillMillClinic",
        category: .whiteCollar,
        headlines: ["Doctor Wrote Hundreds of Opioid Prescriptions After Brief Visits", "Patients Lined Up Before Dawn"],
        law: "prescriptionFraud",
        threshold: 8,
        spec: "Issued prescriptions for controlled substances without legitimate medical purpose, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A clinic doctor, {D}, wrote 900 opioid prescriptions in six months to patients seen for under five minutes, often for cash. Undercover patients were prescribed without exams. {DL} says patients had real pain.",
        state: [E(.digital, 3, "Prescription Database", "900 scripts in six months."), E(.video, 3, "Undercover Recording", "No exam; prescription handed over."), E(.document, 2, "Cash Ledger", "$100 per visit.")],
        defense: [E(.document, 1, "Charts", "Charts listing back pain.")],
        role: "Medical board investigator",
        exam: [.direct("What did the prescription database show?", "\"{D}, a clinic doctor, wrote 900 opioid prescriptions in six months. That is far more than a typical practice.\""), .direct("What did your undercover recording show?", "\"An undercover patient was seen for under five minutes, with no exam at all, and was handed a prescription.\""), .direct("How did patients pay?", "\"In cash, $100 per visit. The cash ledger shows it, and the clinic did not bill insurance.\""), .direct("How did the investigation start?", "\"The medical board received complaints from a pharmacist and a family member, and our database review showed 900 opioid prescriptions from one clinic in six months.\""), .direct("What did your review of patient charts find?", "\"Many charts listed back pain with almost identical wording and no recorded physical exam. Few charts showed follow-up plans or non-opioid options.\""), .direct("How long did the undercover visits last?", "\"Under five minutes each, and the defendant never took a history or looked at an old record.\""), .cross("Some patients really did have pain, didn't they?", "\"Some probably did. I am not saying every patient was faking, and several had imaging that showed injuries.\""), .cross("A busy practice can write many prescriptions, can't it?", "\"It can. But 900 in six months with visits under five minutes is far outside normal.\""), .cross("Why would a clinic take cash?", "\"Some do for billing reasons. But combined with the rest, it concerned me.\""), .cross("Did any charts include imaging reports?", "\"Several did. Some showed documented injuries. I do not dispute that real patients were in the mix.\""), .cross("Is cash pay itself against the rules?", "\"No. Cash practices are lawful. The concern here is cash combined with the volume, the speed, and the lack of exams.\"")],
        defenseRole: "Clinic receptionist",
        defenseExam: [.direct("Were patients examined at the clinic?", "\"Yes, there were quick checks. The doctor looked at patients and asked about their pain before writing anything.\""), .direct("Was every patient examined?", "\"No, not every one. Some patients only got a short conversation, especially repeat patients who came in often.\""), .direct("What was the pace at the clinic?", "\"Very busy. The waiting room was full all day, and the doctor moved quickly from one patient to the next.\""), .direct("What is your role at the clinic?", "\"I answer phones, check people in, take payments, and pull charts. I have been at the front desk since the clinic opened.\""), .direct("What did the typical day look like?", "\"A full waiting room from the moment we opened. The doctor moved from room to room, and we booked back to back.\""), .direct("Did you hear the doctor talk with patients?", "\"Often, through the thin wall. The doctor asked where it hurt, how long, and what they took before, and then wrote the script.\""), .cross("Did you personally see a patient get a prescription without any exam?", "\"I may have. I did not watch every single visit, because I was at the front desk most of the time.\""), .cross("Did the clinic accept insurance at all?", "\"No, it was cash only. I handled the payments myself, and I took cash at the window for each visit.\""), .cross("How long were most visits?", "\"Often just a few minutes. Some were a little longer, but a lot of them were short and quick.\""), .cross("Did you ever see the doctor perform a physical exam?", "\"Sometimes, a quick check of the back or shoulder. I cannot say it happened with every patient.\""), .cross("Did the doctor ever turn a patient away?", "\"A few times. I recall two or three patients who left without a prescription. It was not common.\"")],
        theory: ("{D} sold prescriptions.", "Real patients."),
        allocution: "\"I went into medicine to help people in pain, and I believed that those patients were hurting. I know I saw them for too short a time, and I accept that I should have examined them more carefully. The cash only policy came from the trouble paying the clinic's bills. I'd ask the court to see the good I tried to do.\"",
        truths: ("Patients paid cash only.", "Several patients had imaging confirming injuries."),
        defendant: [.direct("Did you examine your patients?", "\"Briefly. I checked what I could in the time I had. I believed they were in real pain.\""), .direct("Why cash only?", "\"Billing delays with insurers made it hard to keep the doors open. Cash kept things moving.\""), .direct("Did patients really have pain?", "\"Yes. Many had injuries, and several had imaging that confirmed them.\""), .direct("How did you set up the clinic?", "\"I opened it after leaving a hospital group, and I saw patients who had been turned away elsewhere. Insurance delays made billing impossible, so I went cash only.\""), .direct("Did imaging confirm any of the injuries?", "\"Yes, several. X-rays and MRIs on file showed real injuries consistent with what the patients described.\""), .direct("What did you do to check that patients were genuine?", "\"I reviewed their records when they had them and asked about the injury and pain levels. I probably did not do enough follow-up.\""), .cross("900 scripts in six months, with visits under five minutes. How is that medicine?", "\"The clinic was busy. I did not have time for long exams. I now see it was too fast.\""), .cross("$100 per visit in cash. Isn't that a pill mill?", "\"No. I charged for my time. I did not run a mill.\""), .cross("The undercover patient got a script with no exam. Why?", "\"I was rushed. I should have examined that person. I regret it deeply.\""), .cross("You saw patients for under five minutes and wrote 900 prescriptions. Is that careful medicine?", "\"In hindsight, no. The clinic was overwhelmed and I was moving too fast. I did not meet the standard That is on me.\""), .cross("You were the only doctor at the clinic, and nobody reviewed your charts, did they?", "\"That is right. I was the only physician, and no one reviewed my charts. I see now that more oversight would have caught this.\"")],
        openings: ("A clinic doctor, {D}, wrote 900 opioid prescriptions in six months for patients seen for under five minutes, mostly paying $100 in cash. An undercover recording shows a prescription handed over without an exam.", "The defense witnesses will explain that many patients had real pain confirmed by imaging, and that {D} ran a busy practice, not a mill."),
        closings: ("Nine hundred prescriptions, visits under five minutes, and cash at the door. The recording shows an undercover patient receiving opioids without any exam.", "A busy practice with real patients and real injuries. The State must prove {D} prescribed outside the course of professional practice, and a rushed doctor is not a drug dealer."),
        timeline: [(-180, "The clinic opens."), (0, "Month 4: the audit."), (0, "Month 6: the sting."), (0, "Month 7: {DL} is charged.")],
        identified: "A database and a recording.",
        aggravating: ["The defendant took advantage of a position of trust or confidence", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let cockfightBarnRaid = SmallCases.make(
        key: "story.cockfightBarnRaid",
        category: .violent,
        headlines: ["Deputies Raid Barn Cockfight, Find 40 Birds and Blood-Stained Pit", "Spectators Scatter"],
        law: "animalCruelty",
        threshold: 7,
        spec: "Intentionally promoted and conducted animal fighting involving roosters, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Deputies raided a barn on {DATE} during a cockfight and found 40 birds, spurs, and a bloodied pit. {D}, who owns the property, was the only person who did not run. {DL} says {D.he} was renting the barn out.",
        state: [E(.physical, 3, "Pit and Spurs", "Blood-stained pit; gaffs.", .search), E(.video, 2, "Raid Camera", "{D} standing at the gate."), E(.document, 3, "Deed", "{D} owns the barn.")],
        defense: [E(.document, 1, "Rental Note", "A handwritten rental note.")],
        role: "Deputy",
        exam: [.direct("What did you find when deputies raided the barn on {DATE}?", "\"A cockfight in progress. We found 40 birds, spurs, and a bloodied pit. Everyone ran except one person at the gate.\""), .direct("Who was at the gate?", "\"{D}, who owns the property. The deed shows {DL} owns the barn. {D.He} was the only one who didn't run.\""), .direct("What did you recover?", "\"A blood-stained pit and gaffs, which are the blades attached to the birds. The raid camera also shows {DL} at the gate.\""), .direct("How did you plan the raid?", "\"We had a tip about cars on a farm road on weekends. We staged two units out of sight and moved in at about 9:30 p.m. once a hundred or so people were inside.\""), .direct("What did you see as deputies entered the barn?", "\"A ring built from plywood, a crowd along the walls, and handlers holding birds with metal gaffs strapped on. People bolted for the back doors and the fields.\""), .direct("What did you do with the birds?", "\"We seized forty birds, many injured, and had them examined by a veterinarian. Several had to be euthanized. We also photographed the pit and the gaffs.\""), .cross("{DL} says {D.he} was renting the barn out, doesn't {D.he}?", "\"There's a handwritten rental note. I haven't been able to identify who rented it.\""), .cross("Did you see {DL} handle any birds?", "\"No. {DL} was at the gate. I didn't see {DL} touching a bird or a spur.\""), .cross("Why do you think {DL} stayed?", "\"I can't say. Some people stay because they have nothing to hide. Others stay because they're in charge.\""), .cross("Did you find any money or betting slips on {D}?", "\"I do not recall seeing a betting slip on {DL}. A few people dropped cash as they ran, but I cannot say any of it was {DL}'s.\""), .cross("Did you speak with the defendant that night?", "\"Briefly. {D.He} said the barn had been rented for a party and gave the first name of a renter. {D.He} was cooperative and did not argue.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Do you live near {DL}'s barn?", "\"Yes, down the road. I can see the barn from my house. I'm aware of the property.\""), .direct("What did you see that night?", "\"A lot of cars, more than usual, pulling in along the road. It was a busy night.\""), .direct("Did you see strangers?", "\"Many. People I didn't know. I figured it was a party or an event.\""), .direct("What did you hear that night?", "\"Engines and car doors for hours, and later a lot of shouting and sirens coming up the road.\""), .direct("How would you describe the barn's use before that night?", "\"Mostly hay and an old tractor. Occasionally a few trucks would come for a cookout or a family event.\""), .direct("Did you ever call anyone about the traffic?", "\"No. It was only that one night, and I figured it was a party that would end.\""), .cross("Was {DL} there that night?", "\"At the gate, yes. I saw {D} standing there when the deputies came.\""), .cross("Did you see what was in the barn?", "\"No. I was in my yard. I only know what I could see from the road.\""), .cross("Did {DL} tell you about the rental?", "\"No. We aren't close. {DL} didn't tell me about the rental.\""), .cross("You never saw the rental note, did you?", "\"No. I only know what I heard afterward about a rental.\""), .cross("Did you see the defendant take money from anyone?", "\"No. I did not see any exchange at the gate, but I was too far away to see that kind of detail.\"")],
        theory: ("{D} ran a cockfight.", "A landlord."),
        allocution: "\"I own that barn, and I take responsibility for what happens on my land. I rented it for a gathering to someone I only knew by a first name, and I never asked what the event was. I did not know it was a cockfight, and I'd never have allowed it. I'm sorry for those birds and for being so careless.\"",
        truths: ("{DL} had cash at the gate.", "A man named in the note paid {DL} by check."),
        defendant: [.direct("Why were deputies at your barn?", "\"I had rented the barn to someone for a gathering. I didn't know it was for cockfighting. I thought it was a private event.\""), .direct("Who did you rent to?", "\"A person I knew by a first name. There's a rental note. I didn't ask many questions.\""), .direct("Why were you at the gate?", "\"I came to check on my property when cars started showing up. I stood at the gate. I didn't run because I had nothing to hide.\""), .direct("How long have you owned the barn?", "\"Nine years. I inherited the land and used the barn for hay and storage. In recent years I have rented it out for events to make a little extra.\""), .direct("How did the rental come about?", "\"Someone I knew by a first name asked to use the barn on a Saturday for a gathering. We agreed on a price and the person wrote a short note.\""), .direct("What did you say to the deputies when they arrived?", "\"I told them I owned the barn and had rented it for a gathering, and I gave them the renter's first name and showed them the note.\""), .cross("You own the barn, don't you?", "\"Yes. I know I'm responsible for what's on my property. But I didn't know.\""), .cross("There were 40 birds in your barn, weren't there?", "\"So the deputies say. I didn't see them. I never went inside.\""), .cross("You can't name the renter, can you?", "\"I have a first name and a note. I know it's not much.\""), .cross("You did not ask what the gathering was for. Is that how you rent a barn?", "\"I know how it sounds. I wanted the money and I did not push for details. That was careless.\""), .cross("Why didn't you run when everyone else did?", "\"Because I had nothing to run from. I owned the land, and I thought I should stay and explain.\"")],
        openings: ("Deputies raided a barn during a cockfight and found 40 birds, gaffs, and a bloodied pit. {D}, who owns the property, was the only person who did not run. The State will show the pit, the deed, and the raid video.", "Jurors will also see a property owner who rented the barn, never entered it, and stood at the gate because {D.he} had nothing to hide. Owning a barn is not running a cockfight."),
        closings: ("A barn, a bloody pit, and forty birds on land {D} owns. {D.He} stood at the gate, in charge of what happened on the property.", "{D} rented out a barn and did not know what was planned. The only person who stayed was the one with nothing to hide. The State has not proved knowledge."),
        timeline: [(-7, "The rental."), (0, "9 p.m.: the fight."), (0, "9:30 p.m.: deputies raid."), (0, "10 p.m.: birds seized.")],
        identified: "A deed.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let carChokeBar = SmallCases.make(
        key: "story.carChokeBar",
        category: .violent,
        headlines: ["Man Chokes Partner Unconscious in Parked Car After Leaving Bar", "Passerby Hears Horn"],
        law: "strangulation",
        threshold: 7,
        spec: "Assaulted {V} by strangling, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was found with red marks on {V.his} neck after a passerby heard a car horn on {DATE}. {D} had left a bar with {V}. {DL} says {V} fell against a door.",
        state: [E(.forensic, 3, "Medical Report", "Petechiae and neck marks."), E(.statement, 3, "Passerby", "Heard the horn and saw {D} over {V}."), E(.video, 2, "Bar Camera", "{D} and {V} leave arguing.")],
        defense: [E(.statement, 1, "Fall", "{DL} says {V} fell.")],
        role: "Passerby",
        exam: [.direct("What did you hear on {DATE}?", "\"A car horn blaring over and over. I walked toward it and saw {D} over {V} in the car.\""), .direct("What did you see?", "\"{D.He} was over {V}, who was in the car. {V} had red marks on the neck. I called for help.\""), .direct("What did the medical report show?", "\"Petechiae and neck marks on {V}. They fit a neck injury and show that {V} was restrained at the throat.\""), .direct("Where were you when you heard the horn, and how long did it go on?", "\"I was walking home along the street beside the lot around 11:20. The horn was a long steady blare, then another blare, and it kept up for a minute or more.\""), .direct("What did you do when you reached the car?", "\"I saw a figure leaning into the driver's side and called out. When nobody answered I dialed 911 and stayed back at a distance until deputies came.\""), .direct("How did {V} look when deputies arrived?", "\"Shaken and gasping, with red marks on the neck and bloodshot eyes. {V.He} could not speak at first, and a deputy waited for medics.\""), .cross("Did you see {DL}'s hands on {V}'s neck?", "\"I saw {DL} over {V}. I couldn't see exactly where {DL}'s hands were. It was dark.\""), .cross("{DL} says {V} fell against a door, doesn't {D.he}?", "\"I didn't see a fall. I can only tell you what I saw when I got there.\""), .cross("How long were you watching?", "\"Only a few moments. I rushed over after the horn. I can't tell you what happened before.\""), .cross("Where was the streetlight in relation to the car?", "\"About twenty feet up the block, so the car was in partial shadow. I saw shapes more than faces.\""), .cross("Did you see {V} fall against the door?", "\"No. I did not see any fall at all. I came on the scene after the horn and have no view of what came before.\"")],
        defenseRole: "Bartender",
        defenseExam: [.direct("Did you see {DL} and {V} at the bar?", "\"Yes. They were there for a while, and then they left together.\""), .direct("Was {DL} violent?", "\"No. I've never seen {D} be violent. {D.He} gets loud sometimes, but that's all.\""), .direct("How long have you tended bar there?", "\"Five years. I know the regulars and which ones tend to get loud when they have been drinking.\""), .direct("What was the mood between {D} and {V} when they sat down?", "\"Tense. They had a few words about money. By the second round they were arguing in whispers, then not whispers.\""), .direct("How did they leave?", "\"Together, arguing. {V} stormed out first, and {DF} followed with {V.his} jacket. I did not see any pushing or grabbing inside.\""), .direct("What did the defendant do after the two of them left your bar that night?", "\"I saw them go out together, still arguing. I did not see where they went after the door closed, and I went back to the register.\""), .cross("Did you hear what they argued about?", "\"No. I only heard raised voices. I couldn't make out the words.\""), .cross("Did you see them after they left?", "\"No. I stayed at the bar. I didn't see what happened outside.\""), .cross("How much had {DL} had to drink?", "\"A few. I'm not sure exactly. I know {D.he} wasn't falling-down drunk.\""), .cross("Did you watch them all the way to the car?", "\"No. I stayed behind the bar, so I only saw them through the window as far as the sidewalk.\""), .cross("Has the defendant ever been thrown out of your bar?", "\"Once for shouting, a couple of years ago. Nothing physical, and {D.he} apologized the next day.\"")],
        theory: ("{D} choked {V}.", "A fall."),
        allocution: "\"We argued leaving the bar that night, and I'm sorry that it ended the way it did. I never choked anyone, and I leaned over only to help {V} up when the door swung. I understand {V} is upset and was marked, and I regret my part in the evening. I would never lay hands on anyone that way.\"",
        truths: ("{DL} had a prior dvpo.", "A door handle bruise matched {V}'s back."),
        defendant: [.direct("What happened in the car?", "\"We had an argument leaving the bar. {V} got upset and fell against the door. I was trying to help {V} up.\""), .direct("Did you touch {V}'s neck?", "\"I may have been close. I leaned over to help. I never choked {V}. I'd never do that.\""), .direct("Why was the horn going?", "\"{V} fell against the horn, or hit it. I don't know. I was trying to get {V} sitting up.\""), .direct("How did the night begin?", "\"We had dinner and a few drinks at the bar, and the conversation turned to an old argument. We both got loud and decided to leave.\""), .direct("What did you do after the passerby came up to the car?", "\"I got out and told the passerby that {V} had fallen against the door. I was shaking, and I stayed with {V.him} until help arrived.\""), .direct("What do you remember about the moment {V} went against the door?", "\"{V} tried to get out and lost balance, and {V.his} back hit the door frame and the horn. I leaned over to catch {V.him}.\""), .cross("{V} has red marks on the neck, doesn't {V.he}?", "\"I understand so. I don't know how. It could have been from the fall.\""), .cross("You and {V} were arguing, weren't you?", "\"Yes. It was loud. It wasn't physical until {V} fell.\""), .cross("The passerby saw you over {V}, didn't the passerby?", "\"Yes. I was leaning over. I was trying to help, not hurt.\""), .cross("The marks on {V}'s neck are what a person gets from being choked. How did they get there?", "\"I do not know. I did not put my hands around {V.his} neck. I reached to catch {V.him}, and maybe I grabbed at the collar.\""), .cross("Isn't there a history of conflict between you and {V} that the jury should know about?", "\"We had fights before, and I will not pretend we did not. That does not mean I put my hands on {V.him} that night.\"")],
        openings: ("A passerby heard a car horn and found {D} over {V} in the car, with red marks on {V}'s neck. The medical report shows petechiae and neck marks, and the bar camera shows them leaving arguing. The State will present the passerby and the report.", "The defense evidence includes an argument that never turned violent at the bar, a fall against a door, and no witness who saw {D} choke anyone."),
        closings: ("A blaring horn, {D} over {V}, red marks and petechiae on the neck. Those are signs of strangulation, and {DL} was the only other person there.", "An argument, a fall, and a horn. No one saw {D}'s hands on {V}'s neck. The State has not proved a choking."),
        timeline: [(0, "11 p.m.: they leave the bar."), (0, "11:20 p.m.: the horn."), (0, "11:25 p.m.: the passerby calls."), (0, "Midnight: {DL} is arrested.")],
        identified: "A passerby.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "I couldn't speak for days after that night, and I was too embarrassed to tell my mother why. The marks on my neck were still there when I went back to work, and I wore a scarf in the summer. I replay the sound of that car door over and over. I just want to feel safe again.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let gpsTrackerEx = SmallCases.make(
        key: "story.gpsTrackerEx",
        category: .violent,
        headlines: ["Man Hid GPS Tracker on Ex's Car and Showed Up Wherever She Went", "Device Found Behind Bumper"],
        law: "stalking",
        threshold: 7,
        spec: "Willfully harassed {V} on more than one occasion without legitimate purpose, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} found a GPS tracker behind {V.his} bumper on {DATE} after {D}, an ex-partner, appeared at {V.his} gym, dentist, and a friend's home. The tracker was linked to {DL}'s account. {DL} says {D.he} was only worried.",
        state: [E(.digital, 3, "Tracker Account", "The account holder is {D}."), E(.physical, 3, "Tracker", "Found behind the bumper.", .search), E(.statement, 2, "Friend", "{D} showed up uninvited.")],
        defense: [E(.statement, 1, "Worry", "{DL} says {D.he} was worried.")],
        role: "Gym manager",
        exam: [.direct("How do you know {V}?", "\"{V} comes to my gym. {V} told me about the tracker and the ex-partner who kept showing up. {D} came to my gym too.\""), .direct("What happened at your gym?", "\"{DL} appeared uninvited. {DL} had also shown up at {V}'s dentist and a friend's home. It seemed like {DL} always knew where {V} was.\""), .direct("What was found on {V}'s car?", "\"A GPS tracker behind the bumper. The account that tracker is linked to is {DL}'s.\""), .direct("How long had {V} been coming to your gym?", "\"About three years. {V} has a regular schedule, usually six in the morning, and I know the staff look out for the early crowd.\""), .direct("Tell the jury about {D}'s visit to the gym.", "\"{DL} walked in during the week after the breakup and asked the front desk where {V} was. We said {V} was not available, and {DL} waited near the entrance.\""), .direct("How did {V} react when {V.he} saw the defendant?", "\"{V} froze at the door, turned around, and asked me to walk {V.him} to the car. {V} looked frightened and did not want to be alone.\""), .cross("Did you see {DL} install the tracker?", "\"No. I only know what {V} told me and what the deputies found. I never saw anyone touch the car.\""), .cross("{DL} says {D.he} was only worried, doesn't {D.he}?", "\"I can't speak to what's in {D.his} heart. I only know how it looked to us.\""), .cross("Did {DL} threaten {V} at the gym?", "\"No threat that I heard. {DL} was polite, but it was clear {V} didn't want {DL} there.\""), .cross("Were you present for the dentist or the friend's home visits?", "\"No. I only know about those from {V} afterward. At the gym I saw {DL} once with my own eyes.\""), .cross("Did the defendant ever try to enter the gym floor?", "\"No. {D.He} stayed in the lobby, spoke politely to the front desk, and left when asked.\"")],
        defenseRole: "Pet store clerk",
        defenseExam: [.direct("Does {DL} shop at your store?", "\"Yes. {D} came in a few times. I remember {D.he} because of buying pet supplies.\""), .direct("What did {DL} buy?", "\"A pet tag once. A tag for a collar, with a tracker feature. It's a common item.\""), .direct("Did {DL} buy anything else?", "\"Not that I recall. I don't keep a list of what each customer buys.\""), .direct("How long have you worked at the pet store?", "\"About two years. I run the register on weekends and help customers pick tags, leashes, and trackers for their pets.\""), .direct("What do you remember of {D}'s purchase?", "\"{D.He} came in and looked at the small trackers by the collars. {D.He} bought one and paid with a card, and the sale was brief.\""), .direct("How are those trackers marketed?", "\"As pet tags that attach to a collar and sync to an app on a phone. They have a magnet or clip, so people sometimes find other uses.\""), .cross("Did {DL} buy a GPS tracker?", "\"Maybe. We sell several types. I can't say what exactly {DF} bought.\""), .cross("Could the tag have been used on a car?", "\"Some of them can be. I wouldn't use one that way, but I've seen people do it.\""), .cross("Do you know what {DL} planned to do with it?", "\"No. I only sold it. I never asked.\""), .cross("Did the defendant say what the tracker was for?", "\"I do not recall. If {D.he} said anything, it was small talk about a pet.\""), .cross("Do you know whether the defendant has any pets?", "\"I do not. We did not talk about it. I have no way of knowing whether a pet was involved.\"")],
        theory: ("{D} tracked an ex.", "Worry."),
        allocution: "\"I bought a tracker, but I never meant to follow {V} anywhere. We had a hard breakup, and I wanted to know {V} was okay, and I showed up in places out of worry. I can see how that looked, and I'm truly sorry for the fear it caused. I will keep my distance from now on.\"",
        truths: ("{DL} had been told to stop in writing.", "The tracker was bought as a pet tag."),
        defendant: [.direct("Why did you show up at {V}'s gym?", "\"I was worried about {V}. We'd had a hard breakup, and I wanted to make sure {V} was okay.\""), .direct("Did you put a tracker on the car?", "\"I bought a tracker, yes, but I meant it for something else. I never meant to follow {V} around.\""), .direct("Why were you at the dentist and the friend's home?", "\"I wanted to talk to {V}. I wasn't thinking about how it looked. I thought {V} would want to hear from me.\""), .direct("How did your relationship with {V} end?", "\"We were together a few years and it fell apart over a long argument about money and trust. It ended abruptly, and I did not take it well.\""), .direct("What did you do after you learned {V} had found the tracker?", "\"I stopped going to those places and sent {V} a message, which I know only made things worse. Then deputies contacted me.\""), .direct("Where did the tracker come from?", "\"I bought a small tracking device through my online account. I told myself it was for a different use and never explained that to anyone.\""), .cross("The tracker is linked to your account, isn't it?", "\"Yes. That's my account. I'm not going to deny that.\""), .cross("You were told to leave {V} alone, weren't you?", "\"I was told, yes. I didn't listen. I thought I was helping.\""), .cross("You showed up at three places, didn't you?", "\"Yes. It looks bad. I realize now it scared {V}.\""), .cross("You were told in writing to stop contacting {V}. Why didn't you?", "\"I thought I was acting out of concern. That was a poor excuse, and I understand now it only frightened {V.him}.\""), .cross("Concern does not require hiding a tracker behind someone's bumper. Do you agree?", "\"I agree. If I had really only been worried, I would have called a friend or a family member instead.\"")],
        openings: ("{V} found a GPS tracker behind the bumper after {D}, an ex-partner, kept appearing at {V}'s gym, dentist, and a friend's home. The tracker was linked to {DL}'s account. The State will show the account and the tracker.", "The defense will point you to someone who was worried and clumsy, not threatening. A pet tag bought at a store is not proof of stalking."),
        closings: ("A tracker behind the bumper linked to {D}'s own account, and {DL} showing up at the gym, the dentist, and a friend's home. That is stalking.", "{D} was worried, not menacing, and never threatened anyone. A pet tag bought at a store is no proof. The State has not proved {DL} meant to put {V} in fear."),
        timeline: [(-30, "{V} ends the relationship."), (0, "Week 1: gym."), (0, "Week 2: dentist."), (0, "Week 3: the tracker is found.")],
        identified: "A tracker account.",
        mood: .wantsConviction,
        impact: "I looked over my shoulder everywhere I went, at the gym, at the dentist, and even at my friend's house. When I found the tracker behind my bumper, I could not stop shaking. I changed my routine, my route, and my locks. I don't feel safe in my own car anymore.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let fakeProfileCampaign = SmallCases.make(
        key: "story.fakeProfileCampaign",
        category: .cyber,
        headlines: ["Woman Made Fake Profiles to Harass Ex's New Partner", "Messages Traced to Her Home Network"],
        law: "cyberstalking",
        threshold: 7,
        spec: "Used electronic communications repeatedly to harass {V}, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} received hundreds of messages from fake profiles over two months. The accounts traced to {D}'s home network, an ex-partner. {DL} says a roommate had access.",
        state: [E(.digital, 3, "Network Trace", "Accounts logged in from {D}'s router."), E(.digital, 3, "Messages", "One hundred forty messages."), E(.document, 2, "Platform Reply", "Same device ID on three accounts.")],
        defense: [E(.statement, 1, "Roommate", "{DL} says a roommate had access.")],
        role: "Cyber investigator",
        exam: [.direct("What did you find in your investigation?", "\"{V} received hundreds of messages from fake profiles over two months. The accounts logged in from {D}'s router, and one hundred forty messages are in evidence.\""), .direct("What did the platform tell you?", "\"The same device ID was used on three of the accounts. That ties them together as coming from one source.\""), .direct("Who is {DL} to {V}?", "\"An ex-partner. That's the relationship. The messages came after the breakup.\""), .direct("How did you trace the accounts?", "\"I sent preservation requests to the platform and the internet provider. Login records for the fake profiles pointed to one router address that belongs to {D.his} apartment.\""), .direct("What did the messages say and how often did they come?", "\"One hundred forty messages over two months, some daily, mixing insults, personal details about {V}, and demands to end a relationship.\""), .direct("What did the device ID show?", "\"The platform linked three accounts to one device ID, meaning the same phone or computer was used to create or log into all three.\""), .cross("{DL} says a roommate had access, doesn't {D.he}?", "\"A former roommate may have used the network. The router doesn't tell me who was on the device.\""), .cross("Did you examine {DL}'s devices?", "\"I'd have to check what I looked at. I can say the logins came from the router, not that I found them on a specific device.\""), .cross("Did you see any message sent in {DL}'s own name?", "\"No. All were from fake profiles. I can't point to one that says {D.his} name.\""), .cross("Did you find the device ID on any device owned by {D}?", "\"I could match the ID to a phone that was connected to the home network, and that phone matched one that {D.he} used. A person living there could also have used it.\""), .cross("Were any of the logins from outside the defendant's home?", "\"A few came through a public network, but the majority came from the home router. I cannot say who held the device at any given moment.\"")],
        defenseRole: "Former roommate",
        defenseExam: [.direct("Did you live with {DL}?", "\"Yes, for a while. We shared the apartment and the Wi-Fi.\""), .direct("Did you use the network?", "\"Rarely. I used it for ordinary things like streaming. I didn't do anything like this.\""), .direct("When did you move out?", "\"Before the messages started. I'd already moved out.\""), .direct("How did you and {D} split the internet bill?", "\"{DF} held the account and I sent my half each month by transfer. When I moved out I stopped paying and never touched the account.\""), .direct("Did you take anything that gave you access to the network?", "\"Not on purpose. I might still have had the Wi-Fi password in my phone, but I never logged back in after leaving.\""), .direct("What was your relationship with the defendant?", "\"Cordial. We lived together without any big conflict, and we still say hello when we run into each other.\""), .cross("Did you still know the Wi-Fi password after moving?", "\"I might have. I'd have to think. I never used it after I left.\""), .cross("Did you have access to {DL}'s router?", "\"I could log in when I lived there. After I moved, I didn't try.\""), .cross("Do you know who sent the messages?", "\"No. I never heard about it until deputies called me.\""), .cross("Do you know {V} or {V}'s partner?", "\"No. I only heard about them from {D} while we were roommates. I had no reason to contact them.\""), .cross("Did deputies find anything on your devices?", "\"They asked to look at my phone and I handed it over. As far as I know, nothing connected me to those accounts.\"")],
        theory: ("{D} harassed an ex's partner.", "A roommate."),
        allocution: "\"I never created those fake profiles or sent a single message to {V}. We broke up, I moved on, and I have no wish to contact {V} again. A roommate lived with me then and knew my Wi-Fi password, and I think the court should look at that. I'm sorry for what {V.he} has been through, but it was not me.\"",
        truths: ("{DL}'s phone shared the device ID.", "The roommate still had the Wi-Fi password after moving out."),
        defendant: [.direct("Did you send those messages?", "\"No. I never created fake profiles or sent messages to {V}. I'd never do that. We broke up and I moved on.\""), .direct("Who else could use your router?", "\"My former roommate lived with me then. The roommate knew the Wi-Fi password and used the network.\""), .direct("Do you have any idea who did this?", "\"I have suspicions, but nothing I can prove. I only know it wasn't me.\""), .direct("What was the breakup with {V}'s partner like?", "\"It was painful and ended with bad feelings on both sides. I stopped contacting everyone connected to the relationship and tried to move on.\""), .direct("How did you learn about the messages?", "\"Deputies came to my door with a warrant and told me about them. I was stunned and handed over my phone and my computer.\""), .direct("What can you tell the jury about your roommate?", "\"We shared the apartment for a year. After the roommate moved out, nobody changed the Wi-Fi password, and I never asked for the keys back either.\""), .cross("The accounts logged in from your router, didn't they?", "\"That's what I'm told. I don't know how that happened.\""), .cross("You're the ex-partner, aren't you?", "\"Yes. I know that makes me the obvious person. But it wasn't me.\""), .cross("One hundred forty messages is a lot, isn't it?", "\"Yes. It's a horrible thing to do to someone. That's why I want it figured out.\""), .cross("The device ID matches a phone you used. How do you explain that?", "\"I do not know. I lent my phone to people sometimes. I did not create those accounts or send those messages.\""), .cross("You say your roommate had your Wi-Fi password. Did you see the roommate do anything like this?", "\"No. I never saw anything. I am telling you who had access, not accusing anyone of a specific act.\"")],
        openings: ("{V} received hundreds of messages from fake profiles over two months. The accounts logged in from {D}'s home router, and {DL} is {V}'s ex-partner. The State will show the network trace and the messages.", "The defense will present a router that others knew, a roommate who once had access, and no message tied to a named person. A network is not a person."),
        closings: ("Two months of hundreds of messages from fake profiles, all logging in from {D}'s router, and one device ID across three accounts. The source is {D.his} home.", "A router is a shared door. {D} lived with a roommate who knew the password. The State has not proved who typed those messages."),
        timeline: [(-60, "The messages begin."), (0, "Month 2: the trace."), (0, "Month 2: warrant."), (1, "{DL} is charged.")],
        identified: "A device ID.",
        mood: .wantsConviction,
        impact: "I stopped answering my phone because I couldn't tell which message would be the next cruel one. Hundreds came in two months, from names I didn't know, and some knew where I'd been. I stopped going out with friends and deleted my accounts. I've lost two months of my life to them.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let doorbellHackFamilies = SmallCases.make(
        key: "story.doorbellHackFamilies",
        category: .cyber,
        headlines: ["Man Hacked Home Doorbell Cameras and Watched Families", "Accounts Sold on Chat Forum"],
        law: "accessingComputers",
        threshold: 7,
        spec: "Accessed computers of {V} without authority, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} learned strangers were watching {V.his} indoor camera on {DATE}. The login came from {D}'s address. Forum posts offered camera accounts for sale. {DL} says {D.he} only tested password lists.",
        state: [E(.digital, 3, "Login Log", "Logins from {D}'s address."), E(.digital, 3, "Forum Posts", "Accounts offered for sale."), E(.document, 2, "Warrant Return", "A list of 200 accounts.")],
        defense: [E(.statement, 1, "Testing", "{DL} says {D.he} only tested lists.")],
        role: "Cyber investigator",
        exam: [.direct("What did your investigation find about {V}'s indoor camera?", "\"Strangers had been watching it. The login came from {D}'s address. Forum posts also offered camera accounts for sale.\""), .direct("What did the warrant return show?", "\"A list of 200 accounts. That list was in evidence from {D.his} devices after we executed the warrant.\""), .direct("How do the login logs tie to {DL}?", "\"The logs show repeated logins from {DL}'s address to {V}'s camera. The IP address is registered to {DL}.\""), .direct("What did {V} report to you?", "\"{V} said a stranger's voice came through the indoor camera and spoke about what was in the room. The camera app listed an unknown login from another location.\""), .direct("How did you tie the login to {D}'s address?", "\"The login log lists an internet address, and the provider confirmed it belongs to the home internet account in {D.his} name.\""), .direct("What did you find on forums?", "\"Posts offering access to camera accounts, with screenshots of login pages and a price per account. The account handle was not {D.his} real name.\""), .cross("{DL} says {D.he} only tested password lists, doesn't {D.he}?", "\"Testing lists is a thing some security hobbyists do. But accessing someone's account is the problem.\""), .cross("Did you find footage from {V}'s camera on {DL}'s computer?", "\"No. I didn't find any footage of any victim on {DL}'s computer. I have logins and a list.\""), .cross("Can you tell whether {DL} personally posted on the forum?", "\"I can say posts offered accounts. I can't point to a specific post and say {D.he} wrote it with certainty.\""), .cross("Did {V}'s account appear on the list found in the defendant's devices?", "\"The list contained 200 accounts, and I confirmed that {V}'s was among the ones tested, but I cannot say who typed it.\""), .cross("Did you find evidence that the defendant watched any camera footage?", "\"No. I found no recordings of any victim's camera on {DL}'s devices. I only have login history and the list.\"")],
        defenseRole: "Roommate",
        defenseExam: [.direct("What do you know about {DL}'s computer work?", "\"{D} tests security. {D.He} talks about passwords and weak points. It's {D.his} hobby.\""), .direct("Did {DL} talk about selling accounts?", "\"Not to me. I never heard that. I only heard about testing.\""), .direct("Do you share the home network?", "\"Yes. I live there. I'm aware of what {D.he} does online.\""), .direct("How long have you lived with {D}?", "\"Two years. We split rent and utilities, and I am home most evenings. I see what {D.he} is doing on the computer when I pass through.\""), .direct("What does the defendant do on the computer at night?", "\"Mostly scripts and tests that run in a terminal window. {D.He} often explains it to me, and it looks like a hobby.\""), .direct("Did you ever see the defendant watching video feeds?", "\"No. I never saw any feeds of people in their homes, and I would have been uncomfortable if I had.\""), .cross("Was {DL} paid for any of it?", "\"I don't know. I never saw money. I can't say either way.\""), .cross("Did you see {DL} use accounts that weren't {D.his}?", "\"I saw {DF} running lists. I didn't look at what was on the screen.\""), .cross("Do you do any of the testing yourself?", "\"No. I stay out of it. I use the network for ordinary things.\""), .cross("Do you understand what the defendant was actually doing?", "\"Only in general. I understand it as testing logins. I do not know the details of each session.\""), .cross("Were you home every night when the defendant was running tests?", "\"No. I work some evenings. I can only speak to what I saw on the nights I was there.\"")],
        theory: ("{D} hacked cameras.", "A tester."),
        allocution: "\"I run password lists as a hobby and sometimes for work, to show how weak accounts can be. I never sold access to anyone, and I never posted any account for sale. I know people were frightened to find strangers watching their homes, and I'm sorry for that. I should have been much more careful about how I did my testing.\"",
        truths: ("{DL} sold five accounts.", "No footage of any victim was found on {DL}'s computer."),
        defendant: [.direct("What do you do online?", "\"I test security. I run lists of passwords to see how weak accounts are. It's a hobby and sometimes part of my work.\""), .direct("Did you sell any accounts?", "\"No. I never sold any. I never posted anything for sale. I'd never invade anyone's privacy.\""), .direct("Did you watch {V}'s camera?", "\"I may have tested the login. I never watched the video. I wouldn't do that to anyone.\""), .direct("What do you do with password lists?", "\"I use free lists from public breaches to see how many accounts still use the same weak password. It is something I like to test.\""), .direct("Why did you run those lists against strangers' accounts?", "\"I did it to see how many cameras were exposed. I never thought of it as spying. I was curious and I did not think about the people behind the accounts.\""), .direct("How did you react when the deputies arrived?", "\"I handed over my computer, answered questions, and showed them my test setup. I did not hide anything.\""), .cross("You had a list of 200 accounts, didn't you?", "\"Yes. It's a test list. I didn't use them to harm anyone.\""), .cross("The logins came from your home, didn't they?", "\"Yes. That's my network. I run my tests from home.\""), .cross("You tried passwords on strangers' accounts, didn't you?", "\"Yes. I know that's not permitted. I thought it was harmless. I was wrong.\""), .cross("You logged into {V}'s camera. What did you see?", "\"I do not recall seeing anything on it. I confirmed the login worked and moved on to the next one.\""), .cross("Did you ever tell the account owners?", "\"No. I never told them, and I know I should have stopped before it went that far.\"")],
        openings: ("{V} learned strangers were watching {V}'s indoor camera, and the logins came from {D}'s address. A forum offered camera accounts for sale, and a warrant return found a list of 200 accounts. The State will show the logs and the list.", "Jurors will also see a security hobbyist who tested password lists, who never sold any account and never watched any footage. Testing is not spying."),
        closings: ("Logins from {D}'s address, accounts for sale on a forum, and a list of 200 accounts on {D.his} devices. {D.He} was inside {V}'s home camera.", "{D} tested lists and sold nothing. No footage was found on {D.his} computer. The State has not proved {DL} watched anyone or offered an account."),
        timeline: [(-30, "The logins."), (0, "Month 1: the report."), (0, "Month 1: the trace."), (1, "{DL} is arrested.")],
        identified: "Login logs.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I felt watched in my own home after I learned strangers could see inside through my camera. I thought about every private moment in my living room and what might have been seen. I unplugged everything and haven't put a camera up since. My kids still ask me whether anyone is looking.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let schoolRansomLock = SmallCases.make(
        key: "story.schoolRansomLock",
        category: .cyber,
        headlines: ["School District Computers Locked by Ransomware", "Ransom Demanded in Cryptocurrency"],
        law: "damagingComputers",
        threshold: 8,
        spec: "Willfully caused damage to computers of {V}, a school district, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A school district's records were locked on {DATE} with a $40,000 ransom note. The attack came through credentials of {D}, a district IT contractor, who sold them. {DL} says the credentials were stolen.",
        state: [E(.digital, 3, "Access Log", "Contractor credentials used at 3 a.m."), E(.digital, 3, "Wallet Trace", "Funds traced to a wallet tied to {D}."), E(.document, 2, "Ransom Note", "A $40,000 demand.")],
        defense: [E(.statement, 1, "Stolen", "{DL} says the credentials were stolen.")],
        role: "District technology director",
        exam: [.direct("What happened to the district's records?", "\"They were locked at 3 a.m. on {DATE}, and a note demanded $40,000 in ransom. We could not open student or payroll files.\""), .direct("How did the attacker get in?", "\"Through the credentials of {D}, a district IT contractor. The access log shows those credentials used at 3 a.m.\""), .direct("What did the wallet trace show?", "\"The funds traced to a cryptocurrency wallet tied to {D.him}. The wallet received a payment related to the credentials.\""), .direct("Who reported the lockout first?", "\"The principal at the high school, a few minutes before eight. The office staff had already tried twice to open the files.\""), .direct("What did the access log show about 3 a.m.?", "\"A login with the contractor credentials from an outside address at about 3 a.m., followed by a burst of file encryption lasting about forty minutes.\""), .direct("What was the effect on the schools?", "\"Attendance records, grades, and bus schedules were unavailable for four days. Staff worked from paper and the district paid for outside recovery help.\""), .cross("The credentials could have been stolen, couldn't they?", "\"Yes. Credentials can be stolen, and I cannot rule that out.\""), .cross("Were the credentials reset after {D} left?", "\"They had been reset a month earlier. {D.He} had new ones, so the old ones should not have worked.\""), .cross("Do you have any proof the defendant typed a command that night?", "\"No. I have a log and a wallet trace. I do not have a video of {DL}.\""), .cross("Did you pay the ransom?", "\"No. We restored from backups and rebuilt several servers. The district chose not to pay and reported the attack to deputies.\""), .cross("Can you tell which person was behind the login at 3 a.m.?", "\"No. I can tell which credentials were used and from what address. The address was not {D.his} home.\"")],
        defenseRole: "District IT clerk",
        defenseExam: [.direct("Did the district reset its credentials?", "\"Yes. We reset them about a month before the attack, as part of the normal rotation we do for all contractors.\""), .direct("Did {D} receive new credentials after that?", "\"Yes, {D} received new ones after the reset. I handled that myself, and I remember giving them to {D.him}.\""), .direct("Were the old credentials supposed to be inactive?", "\"They should have been, yes. I do not know why they worked on the night of the attack.\""), .direct("How long have you worked in the district's IT office?", "\"Six years. I help with accounts and tickets, and I sit in on the credential rotation each semester.\""), .direct("What is supposed to happen to old credentials after a reset?", "\"They are disabled in the system and logged as retired. In practice, a few have lingered when two systems were not synced.\""), .direct("Did you see anyone suspicious around the network before the attack?", "\"There were a few failed login attempts from odd addresses in the weeks before, which we flagged and ignored. Nothing pointed to a person.\""), .cross("Who else had access to the old credentials?", "\"Several people at the district had them, including other contractors and a few staff who shared logins.\""), .cross("Did you ever see the defendant sell any credentials?", "\"No. I do not know anything about a sale, and I never saw anything like that happen.\""), .cross("Is it common for credentials to be stolen?", "\"Yes, it happens often these days. But I cannot say for certain that it happened here.\""), .cross("Did the defendant have any reason to harm the district?", "\"I am not aware of one. {D.He} left on good terms, and I never heard a complaint.\""), .cross("Have you reviewed the wallet trace?", "\"No. I only heard about it. I cannot tell you whether the wallet is tied to {DF} or someone else.\"")],
        theory: ("{D} locked school records.", "Stolen credentials."),
        allocution: "\"I did not attack the district, and I never locked a file or asked for any money. My credentials were stolen from me, and I did not create or own the wallet in the trace. I worked for those schools for years and I care what happens to them. I'm sorry for what the students and teachers went through, and I hope the truth comes out.\"",
        truths: ("The wallet received a payment from the forum.", "The credentials had been reset a month earlier."),
        defendant: [.direct("Did you attack the district?", "\"No. I did not attack anyone. I did not lock any files or demand any money.\""), .direct("Whose wallet is the one in the trace?", "\"Not mine. I do not own that wallet, and I never created it.\""), .direct("How could it be linked to you?", "\"Someone spoofed the link. Information about me can be copied and used.\""), .direct("What was your role at the district?", "\"I was a contractor who handled network upgrades and help-desk escalations. I had a login with elevated access for those tasks.\""), .direct("What happened with your login a month before the attack?", "\"The district reset the credentials and issued me new ones. I stopped using the old password after that.\""), .direct("How did you feel when you heard about the attack?", "\"I was shocked and worried about the schools. I called the technology director to offer help and to say my access had been changed.\""), .cross("The access log uses your credentials at 3 a.m., doesn't it?", "\"It uses credentials like mine. They were old ones, and I had received new ones.\""), .cross("A payment went to the wallet from a forum, didn't it?", "\"I do not know about that. I never used any forum for that purpose.\""), .cross("You are an IT contractor. You know how to do this, don't you?", "\"I know how it works. That does not mean I did it.\""), .cross("The wallet that got payment is tied to you. How do you explain that?", "\"I do not recognize the wallet, and I never set one up. If it is tied to me, someone used my details without my knowledge.\""), .cross("If your old login was dead, why did it work at 3 a.m.?", "\"I do not know. That is a question for the district and the people who manage accounts.\"")],
        openings: ("A school district's records were locked at 3 a.m. with a $40,000 ransom note. The attack came in on the credentials of {D}, a district IT contractor, and funds traced to a wallet tied to {D.him}.", "By the end of this trial, the proof will show that {D} had new credentials, that the old ones could be stolen, and that the wallet link may have been spoofed."),
        closings: ("Contractor credentials at 3 a.m., a ransom note, and a wallet that traces to {D}. An IT contractor knows exactly how this is done.", "Reset credentials, a possibly spoofed link, and no one who saw {D} touch a keyboard. The State has not proved who launched the attack."),
        timeline: [(-30, "Credentials reset."), (0, "3 a.m.: the attack."), (0, "8 a.m.: staff locked out."), (1, "The trace.")],
        identified: "Logs and a wallet.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        impact: "Grades were lost for weeks, and teachers had to rebuild attendance by hand. We could not reach student records, bus rosters, or even lunch accounts for days. The district spent money we didn't have, and some seniors worried about their transcripts for college. It was a hard stretch for children who had done nothing.",
        doctrines: ["burdenOfProof"])

    static let bankFileSale = SmallCases.make(
        key: "story.bankFileSale",
        category: .cyber,
        headlines: ["Bank Employee Sold Customer Files to Scammers", "Accounts Drained After Data Leak"],
        law: "identityTheft",
        threshold: 8,
        spec: "Knowingly obtained and sold identifying information of {V}, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Scammers drained 60 customers' accounts after a bank employee, {D}, sold files. Chat messages showed {DL} sending files for pay. {DL} says the files were requested for work.",
        state: [E(.digital, 3, "Chat Messages", "{D} sends customer files."), E(.digital, 3, "Access Log", "{D} exported 60 files."), E(.document, 2, "Payment Record", "Crypto payments to {D}.")],
        defense: [E(.statement, 1, "Work", "{DL} says the exports were for work.")],
        role: "Bank security officer",
        exam: [.direct("What happened to the bank's customers?", "\"Scammers drained 60 customer accounts. We traced the exposure to files exported from inside the bank.\""), .direct("What do the chat messages show?", "\"It shows {D} sending customer files to someone, for pay. The messages are in evidence.\""), .direct("What does the access log show?", "\"{D.He} exported 60 files. The payment record shows crypto payments to {D.him}.\""), .direct("How did the bank first learn of a problem?", "\"Customers began reporting wire transfers they never made. We compared the affected names and found that all sixty had been included in a single bulk export.\""), .direct("What did the access log say about the export?", "\"{DL}'s account exported 60 customer files in one session, outside normal hours, and then copied them to a removable location.\""), .direct("What did the chat show about payment?", "\"{D.He} sent the files in batches and was paid in cryptocurrency afterward. The messages mention the amount and the next batch.\""), .cross("{DL} says the exports were for work, doesn't {D.he}?", "\"Some exports are normal in this job. Sixty customer files outside normal process is not.\""), .cross("Did anyone ask {DL} to do those exports?", "\"I haven't found a request. It's possible a supervisor asked. I haven't seen one.\""), .cross("Can you tell who was on the other end of the chat?", "\"No. The other party used an alias. I can't identify who it was.\""), .cross("Did the chat messages include {D}'s real name?", "\"No. The chat alias was a handle. We linked it to {D.him} through the device and the payments, not a name.\""), .cross("Are there legitimate reasons to export that many files?", "\"Occasionally, for a regulatory review, but that requires a ticket and a supervisor's sign-off, and I found neither.\"")],
        defenseRole: "Branch manager",
        defenseExam: [.direct("Do employees export customer files?", "\"Sometimes. It happens for audits and reviews. It's part of the job in some roles.\""), .direct("How many files is usual?", "\"A handful. A few at a time, with a reason. It's not common to export in bulk.\""), .direct("Did {DL} work under you?", "\"Yes. {D} was a good employee for years. I've never had a complaint.\""), .direct("How long have you managed the branch?", "\"Twelve years. I supervise operations staff, review exception reports, and sign off on special data requests.\""), .direct("What process does a request for a bulk export follow?", "\"A written ticket, a business reason, and my approval. Anything over a handful of files goes through a second reviewer.\""), .direct("What was {D}'s record before this?", "\"Solid. {D.He} was punctual, careful, and had no complaints on file. The news came as a shock to me.\""), .cross("Is exporting 60 files normal?", "\"No. That's not normal. I'd have asked why.\""), .cross("Did you authorize it?", "\"No. I didn't authorize any export of that size. I don't know who might have.\""), .cross("Did {DL} tell you about the exports?", "\"No. I wasn't told. I learned about it later.\""), .cross("Did you review the defendant's exports at any time before the audit?", "\"Not in detail. Our monthly review looked at counts, and the large export slipped by in the totals.\""), .cross("Was any ticket opened for the sixty files?", "\"No. I checked and found nothing. I did not approve that export.\"")],
        theory: ("{D} sold customer data.", "Work exports."),
        allocution: "\"I pulled those files because I was asked to for work, and I believed it was an internal request. I never sold customer information, and I would never give it to scammers. I'm sorry that the customers lost money, and I'm sorry I did not question the request. I should have asked more questions before I sent anything.\"",
        truths: ("{DL} had no assigned ticket.", "The chat alias uses a different time zone than {DL}'s."),
        defendant: [.direct("Why did you export 60 files?", "\"Someone asked me to pull them for work. I thought it was an internal request. I didn't think I was doing anything wrong.\""), .direct("Did you sell customer files?", "\"No. I never sold any. I would never give customer information to scammers.\""), .direct("What about the chat messages?", "\"I sent files to a contact. I thought it was a work contact. I didn't know it was a scammer.\""), .direct("What was your role at the bank?", "\"I worked in the data support unit, pulling reports and helping branches with customer lists. Exports were a regular part of my job.\""), .direct("Who asked you for the exports?", "\"A contact who said they were from a vendor working on a data project. I believed it was a legitimate internal request.\""), .direct("What happened when you learned customers were hurt?", "\"I was sick about it. I told my supervisor what I had done and gave the investigators every message I had.\""), .cross("You received crypto payments, didn't you?", "\"Yes. I got some payments. I thought they were for something unrelated. I know how that sounds.\""), .cross("Sixty customers lost money, didn't they?", "\"Yes. I feel terrible. I never meant for that to happen.\""), .cross("You sent files outside the bank, didn't you?", "\"Yes. I did. I now understand it was a mistake. I didn't know where they were going.\""), .cross("A vendor you could not identify paid you in cryptocurrency. What did you think was happening?", "\"I thought it was a consulting arrangement. I did not ask enough questions, and I accept that.\""), .cross("You exported sixty files outside normal hours without a ticket. Why?", "\"I was trying to finish a request quickly. There was no ticket, and I should have stopped and asked a supervisor first.\"")],
        openings: ("Scammers drained 60 customers' accounts after files were exported from inside a bank. Chat messages show {D}, a bank employee, sending customer files for pay, and crypto payments went to {DL}. The State will present the security officer and the logs.", "The defense will point you to a long-time employee who exported files for what {D.he} believed was work, who never knew where they went, and whose job involved such exports."),
        closings: ("Sixty files exported, chat messages sending them out, and crypto payments to {D}. Sixty customers were drained, and the trail runs through {DL}.", "Exports are part of a bank job, and {D} thought the request was legitimate. The State has not proved {DL} knew the files were going to scammers."),
        timeline: [(-30, "Exports begin."), (0, "Week 4: accounts drained."), (0, "Week 5: the audit."), (0, "Week 6: {DL} is suspended.")],
        identified: "Logs and chats.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "I lost my savings when scammers drained my account. It took me thirty years to build that money, and I woke up one morning to a balance of nothing. The bank helped some, but I still lost sleep and trust. I check my statements three times a day now.",
        doctrines: ["burdenOfProof"])

    static let fakeFundraiserOnline = SmallCases.make(
        key: "story.fakeFundraiserOnline",
        category: .whiteCollar,
        headlines: ["Woman Ran Fake Medical Fundraiser and Collected $90,000", "Donors Find No Patient"],
        law: "falsePretenses100k",
        threshold: 8,
        spec: "Obtained over $100,000 by false pretenses from {V} and others, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} ran a fundraiser for a child's cancer treatment and raised $90,000, but no such child existed. Donors found no hospital records. {DL} says the child's family asked for privacy.",
        state: [E(.document, 3, "Platform Records", "$90,000 paid to {D}."), E(.statement, 3, "Hospital", "No such patient."), E(.digital, 2, "Posts", "Photos copied from another site.")],
        defense: [E(.statement, 1, "Privacy", "{DL} says the family asked for privacy.")],
        role: "Donor",
        exam: [.direct("Why did you donate to {DL}'s fundraiser?", "\"It was for a child's cancer treatment. It touched my heart, and I gave what I could. Many people did.\""), .direct("What did you later learn?", "\"The hospital had no such patient. The platform records show $90,000 paid to {D}. Donors found no hospital records.\""), .direct("What about the photos in the posts?", "\"They were copied from another site. They weren't of the child {DL} described, and that made me feel betrayed.\""), .direct("What first led you to give?", "\"A post shared in a neighborhood group showed a photo of a smiling child in a hospital bed and a story about a treatment fund. It asked for any amount.\""), .direct("How much did you give, and how did you pay?", "\"Fifty dollars through the fundraising platform. I got a thank-you message and updates for a few weeks, and then they stopped.\""), .direct("How did you find out something was wrong?", "\"A group of donors compared notes after the updates stopped and called the hospital named in the post. The hospital said it had no such patient.\""), .cross("{DL} says the family asked for privacy, doesn't {D.he}?", "\"But a family that wants privacy still has a hospital record, and there was none.\""), .cross("Did you ask for proof before giving?", "\"No. I trusted the post. I wish I had asked. I gave because the story moved me.\""), .cross("How much was your donation?", "\"It wasn't large. But the whole fund came to $90,000, and I'm one of hundreds who gave.\""), .cross("Did you check the child's name or doctor before giving?", "\"No. I did not. I wish I had. The page looked real and I assumed it had been vetted.\""), .cross("Were the updates posted by {D} personally?", "\"They came from {DL}'s account, yes. I cannot say who typed them, but they were posted under {DL}'s name.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("Did {DL} talk about a child?", "\"Yes. {D} told me about a child with cancer and a family that needed help. {D.He} seemed sincere.\""), .direct("How did {DL} act?", "\"Concerned and busy with the fundraiser. {D.He} spent a lot of time on it.\""), .direct("Did you donate?", "\"Yes, a little. I believed it was real. I trusted {D.him}.\""), .direct("How long have you known {D}?", "\"Around ten years. We met through work and see each other at events. I considered {DF} a trustworthy friend.\""), .direct("What did the defendant tell you about the fundraiser?", "\"That a family needed help paying for a child's treatment and that {DF} was collecting money for them. {DF} sounded worried and busy.\""), .direct("Did you help the defendant with anything?", "\"I shared the post with my own contacts and gave a small amount. I did not handle any money.\""), .cross("Did {DL} give you the child's name?", "\"No. {D.He} never said the child's name. I didn't ask.\""), .cross("Did you see the child or the family?", "\"No. I never met anyone. I only heard it from {D.him}.\""), .cross("Do you know where the money went?", "\"No. I'm not involved in the money side.\""), .cross("Did the defendant ever show you messages from the family?", "\"No. I asked once and {D.he} said the family wanted privacy, so I let it go.\""), .cross("Has the defendant paid you or others back for anything related to this?", "\"Not that I know of. I only know that {D.he} told me everything was under control.\"")],
        theory: ("{D} faked a fundraiser.", "A private family."),
        allocution: "\"A family I knew asked me to help raise money for a child's treatment, and I posted the story because I wanted to help. They asked for privacy, and I respected it, so I never asked for hospital records. I believed what I was told, and I'm heartbroken for the donors. I'd ask the court to understand I was trusting.\"",
        truths: ("{DL} bought a car with part of it.", "A woman claiming to be the child's aunt asked {DL} to keep her family private."),
        defendant: [.direct("Why did you start the fundraiser?", "\"A family I knew asked me to help raise money for a child's treatment. I wanted to help. I posted the story.\""), .direct("Why were there no hospital records?", "\"The family asked for privacy. I respected that. I didn't ask for records, and I now see I know I should have.\""), .direct("Where did the $90,000 go?", "\"I intended it for the family. I passed some along and I didn't keep track of it as I should. I didn't set out to steal.\""), .direct("How did you come to run a fundraiser?", "\"A family I knew by reputation reached out in a message and asked me to organize one. I made the page and wrote the story they gave me.\""), .direct("What did you do with the donations?", "\"They went to my account first, and I planned to pass them to the family. I moved some of it along and kept some while waiting for details.\""), .direct("How did you respond when donors began asking questions?", "\"I told them the family wanted privacy. I did not push back because I believed it, but I did not ask the family for proof either.\""), .cross("The hospital says there's no such patient, doesn't it?", "\"That's what I'm told. I don't know. I believed what I was told.\""), .cross("The photos came from another site, didn't they?", "\"I used pictures I was given. I didn't check where they came from.\""), .cross("$90,000 was paid to you, wasn't it?", "\"Yes. It came to my account. I'm responsible for it, and I can't explain every dollar.\""), .cross("You never met the child or the family. How can you say they exist?", "\"I only dealt with them by message. I cannot prove it now, and I know that is hard to accept.\""), .cross("Why did the money stay in your account if it was meant for treatment?", "\"I was waiting for the family to tell me where to send it. I should have set up a separate account or asked donors.\"")],
        openings: ("{D} ran an online fundraiser for a child's cancer treatment and raised $90,000. The hospital has no such patient, and the photos were copied from another site. The State will show the platform records and the hospital's response.", "The defense will present someone who believed a family needed help, who respected their wish for privacy, and who never meant to steal from donors."),
        closings: ("Ninety thousand dollars from donors who gave from the heart, no child, no hospital record, and copied photos. {D} took the money and gave nothing to anyone.", "{D} relied on a family that asked for privacy. The State has not proved {DL} knew the child did not exist, and without that there is no fraud."),
        timeline: [(-90, "The fundraiser begins."), (0, "Month 3: donors ask."), (0, "Month 3: hospital says no."), (1, "{DL} is charged.")],
        identified: "Platform records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I felt sick when I learned the child did not exist. I gave money I could barely spare because I thought of my own grandchild, and I told my friends to give too. I keep thinking about how I pushed others to donate. It's hard to trust any appeal now, even for a real family.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let churchInvestmentPonzi = SmallCases.make(
        key: "story.churchInvestmentPonzi",
        category: .whiteCollar,
        headlines: ["Pastor Ran Investment Scheme Among Church Members", "Early Investors Paid With New Deposits"],
        law: "securitiesFraud",
        threshold: 8,
        spec: "Offered and sold securities by fraud to {V} and others, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, a pastor, promised church members 20% returns on real estate deals. Early investors were paid with newer deposits. Losses reached $410,000. {DL} says the market turned.",
        state: [E(.document, 3, "Bank Records", "New deposits paid old investors."), E(.document, 3, "Offering Papers", "No property was purchased."), E(.statement, 2, "Member", "'He called it a calling.'")],
        defense: [E(.statement, 1, "Market", "{DL} says the market turned.")],
        role: "Securities investigator",
        exam: [.direct("What did {DL} promise church members?", "\"{D}, a pastor, promised 20 percent returns on real estate deals. Members trusted {D.him} and handed over their savings.\""), .direct("What did the bank records show?", "\"New deposits paid old investors. That's how a Ponzi scheme operates. Early investors were paid with newer deposits.\""), .direct("What do the offering papers show about property?", "\"No property was purchased. The offering papers describe deals, but there are no deeds, no closings. Losses reached $410,000.\""), .direct("How did your investigation begin?", "\"Several church members filed complaints after their promised payments stopped. I subpoenaed the church's and {D.his} bank records and followed each deposit and each payout.\""), .direct("How did the payouts line up with the deposits?", "\"Each month's returns were paid within days of a new member's deposit. When deposits slowed in year one, the payments slowed too, which is the signature of a Ponzi pattern.\""), .direct("What was the total loss and how many people were affected?", "\"Losses reached $410,000 across dozens of members, many of them retirees who put in their savings because they trusted the pastor.\""), .cross("{DL} says the market turned, doesn't {D.he}?", "\"Markets do turn. But the records show no property bought, so the market wasn't the cause.\""), .cross("Did {DL} personally ask you for money?", "\"No. I'm an investigator. I only know what the records and members tell me.\""), .cross("Did members say {DL} was sincere?", "\"Some did. One said {D.he} called it a calling. Sincerity doesn't make a scheme legal.\""), .cross("Did {D} keep the money for personal spending?", "\"Some of it went to expenses I am still sorting out. I will not say every dollar was personal, and I have not finished tracing all of it.\""), .cross("Was there any property contract that never closed?", "\"There was at least one contract for a parcel that fell through. I cannot say how serious that deal was or how far it went.\"")],
        defenseRole: "Church deacon",
        defenseExam: [.direct("What did {DL} tell the congregation?", "\"That it was a calling. {D} spoke with passion. {D.He} said the investments would help the church family.\""), .direct("How did members react?", "\"Many were excited. People gave what they could. We trusted our pastor.\""), .direct("Was {DL} known for honesty?", "\"Yes. {D.He} has been a good pastor for years. I never doubted {D.him}.\""), .direct("What is your role at the church?", "\"I have served as a deacon for fourteen years, helping with budgets, visits to members, and community events.\""), .direct("How was the investment offer described to you?", "\"By the pastor from the pulpit and in a meeting. It was framed as a way to help church families while also helping the building fund.\""), .direct("Did anyone object to the plan?", "\"A couple of people asked questions, and I answered them. Nobody raised a serious objection before the money was given.\""), .cross("Did you see any property?", "\"No. I never saw a property or a deed. I only heard about the plans.\""), .cross("Did you ask for proof?", "\"No. We took {D.him} at {D.his} word. I'd probably do it differently now.\""), .cross("Did you invest?", "\"Yes. I lost money. I'm still hoping it's all a misunderstanding.\""), .cross("Did you ever ask to see a deed or a closing statement?", "\"No. It did not cross my mind. We took our pastor at {D.his} word.\""), .cross("Did you invest personally, and how much?", "\"Yes, a few thousand dollars. I have not seen it again, and that hurts as much as anything.\"")],
        theory: ("{D} ran a Ponzi scheme.", "A bad market."),
        allocution: "\"I believed in those real estate deals, and I believed in the returns I promised my congregation. I paid investors what I could, using money as it came in, and when the market turned, I could not make everyone whole. I'm heartbroken that members lost their savings. I never set out to harm the people who trusted me.\"",
        truths: ("{DL} took a $60,000 salary from deposits.", "A property contract exists but fell through."),
        defendant: [.direct("What were you trying to do with the investment?", "\"I wanted to help church members build wealth through real estate. I believed in the deals, and I believed in the returns.\""), .direct("Did you pay returns to investors?", "\"Yes, I paid what I'd promised. I used money as it came in. I didn't think of it as one investor paying another.\""), .direct("What happened to the money?", "\"The market turned and the deals didn't pan out. I tried to hold on. I never meant to lose anyone's savings.\""), .direct("How did you come to offer these investments?", "\"A member of the congregation who worked in real estate described some deals, and I thought they could help families build something. I took that to the church.\""), .direct("How did you present it to the congregation?", "\"At meetings after services, with a short handout. I told them it was a calling to help each other, and I did not push anyone to give.\""), .direct("What did you do when payments slowed?", "\"I told members the market had slowed and asked for patience. I kept paying what I could, and I looked for other deals that would work.\""), .cross("New deposits paid older investors, didn't they?", "\"I see that. I didn't think of it that way. I was keeping my promises.\""), .cross("No property was ever purchased, was it?", "\"The deals fell short. I know that's what the records show. I wanted to buy property.\""), .cross("You called it a calling, didn't you?", "\"Yes. I believed it. I thought God was guiding me. I know how that sounds to others.\""), .cross("Telling members about 20 percent returns, did you have a signed purchase for any property to back it up?", "\"Not for every deal. I believed contracts were coming, and I was too optimistic about what I could close.\""), .cross("You used new deposits to pay earlier investors. Why?", "\"Because I had promised those returns and did not have another source. I told myself it would balance out when a deal closed.\"")],
        openings: ("A pastor promised church members 20 percent returns on real estate deals. Early investors were paid with newer deposits, no property was ever purchased, and the losses reached $410,000. The State will show the bank records and the offering papers.", "Jurors will also see a pastor who believed in the deals, who told members it was a calling, and whose plans were hit by a turn in the market. Failure is not fraud."),
        closings: ("Newer investors paying older ones, no property bought, and $410,000 lost by people who trusted their pastor. That is a Ponzi scheme.", "{D} believed in the deals and the market turned. The State has not proved {DL} meant to defraud anyone, only that a venture failed."),
        timeline: [(-365, "The offering begins."), (0, "Year 1: payments slow."), (0, "Year 1: members complain."), (1, "{DL} is charged.")],
        identified: "Bank records.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .divided,
        impact: "I lost my retirement, forty years of saving, because I trusted my pastor. We prayed together, and I thought {D.he} would never steer us wrong. Now I'm seventy and working part time at the grocery store. I don't know whether I'll ever stop feeling foolish.",
        doctrines: ["burdenOfProof"])

    static let homeBuilderDeposits = SmallCases.make(
        key: "story.homeBuilderDeposits",
        category: .whiteCollar,
        headlines: ["Contractor Took Deposits for Dozens of Homes and Built None", "Foundations Never Poured"],
        law: "falsePretenses100k",
        threshold: 8,
        spec: "Obtained over $100,000 by false pretenses from {V} and others, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, a contractor, took $130,000 in deposits from nine families for new homes and never poured a foundation. {DL} says supplier delays stalled the work. One of the families paid $16,000. By the sixth month no permits had been pulled, and by the eighth month the families were complaining.",
        state: [E(.document, 3, "Deposit Records", "$130,000 from nine families."), E(.statement, 3, "Family", "'He said work starts in May.'"), E(.document, 2, "Permit Office", "No permits were pulled.")],
        defense: [E(.document, 1, "Supplier Letter", "A letter about delays.")],
        role: "Homebuyer",
        exam: [.direct("What did you pay {DL} for?", "\"A new home. My family paid $16,000 in deposits to {D}, a contractor, who said work would start in May.\""), .direct("What happened after you paid?", "\"Nothing. By the sixth month no permits had been pulled, and no foundation was ever poured. By the eighth month, the families were complaining.\""), .direct("How many families were involved?", "\"Nine families, with deposits totaling $130,000. The deposit records show it, and the permit office confirms no permits were pulled.\""), .direct("How did you find {D}?", "\"A neighbor recommended {DL} as a builder who could put up a home on our lot. We met twice, reviewed plans, and signed a contract with a deposit.\""), .direct("What did the defendant tell you about the schedule?", "\"That the foundation would be poured by early summer and the house finished by fall. We were told work starts in May.\""), .direct("What happened when May came?", "\"Nothing. The lot was empty. I called and texted, and {D.he} said materials were delayed and promised a new date every few weeks.\""), .cross("{DL} says supplier delays stalled the work, doesn't {D.he}?", "\"There was a letter about delays. But you need a permit to build, and none was ever filed.\""), .cross("Did {DL} keep in touch with you?", "\"For a while. Then the messages got less frequent. {D.He} always had an explanation, but nothing was built.\""), .cross("Did you ask for a refund?", "\"Yes, after the eighth month. I haven't received it. We're still out the money.\""), .cross("Did you ever visit the lot to see whether anything had started?", "\"Yes, a few times. It looked just as it did when we signed. Nothing had been staked and no equipment was ever there.\""), .cross("Did the defendant ever show you the supplier letter?", "\"Late in the process, once. It said lumber was backordered, but it did not explain why no permit had been filed.\"")],
        defenseRole: "Lumber supplier",
        defenseExam: [.direct("What did you supply to {DL}?", "\"Lumber for building jobs. {D} placed orders with me for framing material for new homes.\""), .direct("Were orders delayed?", "\"Yes. There was a backorder on lumber that affected a lot of contractors that season.\""), .direct("Did you write a letter about it?", "\"Yes. I wrote a letter explaining the delays, so {D.he} could show customers.\""), .direct("What is your business?", "\"I supply lumber and building materials to contractors across the county. I have been in this trade for twenty years.\""), .direct("How did the backorder affect contractors that season?", "\"Orders took months instead of weeks. Many builders had to push start dates or switch suppliers.\""), .direct("What did {D} order from you?", "\"Framing lumber and trusses for a couple of projects. The orders were small compared with what nine homes would require.\""), .cross("Was payment made on the orders?", "\"Partly. {D.He} paid some of what was owed. Not all.\""), .cross("How many orders did {DL} place?", "\"A few. Not enough for nine homes, as I recall. I can't give an exact count.\""), .cross("Did the delay prevent pulling permits?", "\"No. Permits have nothing to do with lumber. They're filed with the county.\""), .cross("Did you tell the defendant when the backorder would end?", "\"I gave a rough estimate of six months. That is all I could say, and it moved a bit.\""), .cross("Did the defendant owe you money when the letter was written?", "\"Some, yes. {D.He} had paid part of an account and still owed a balance.\"")],
        theory: ("{D} took deposits and built nothing.", "Supplier delays."),
        allocution: "\"I took those deposits fully planning to build, and then the lumber was backordered and the schedule fell apart. I used some of the money for startup costs and materials, and I should have told the families more clearly where it was going. I'm sorry for their disappointment. I'd like to refund them as best I can.\"",
        truths: ("{DL} spent deposits on an old debt.", "The supplier letter shows a six-month backorder on lumber."),
        defendant: [.direct("Why didn't you start building the homes?", "\"Supplier delays. The lumber was backordered, and I couldn't start without materials. I told the families it would take longer.\""), .direct("What did you do with the deposits?", "\"I used some for startup costs and materials. I intended to build every home. I didn't set out to take anyone's money.\""), .direct("Why were no permits pulled?", "\"I was waiting on the supply situation first. I should have pulled them anyway. I was behind and I let it slide.\""), .direct("How many homes had you built before this?", "\"Roughly thirty over twelve years, mostly smaller builds. I was proud of my record and had never taken deposits for this many homes at once.\""), .direct("What did you do when lumber went on backorder?", "\"I called suppliers, checked other yards, and told the families the schedule would slip. I thought I could still start in the fall.\""), .direct("How did the deposit money get spent?", "\"Some went to deposits with the supplier and some to other costs of the business. I did not keep each family's money separate. In hindsight, yes.\""), .cross("You took $130,000 from nine families, didn't you?", "\"Yes. That's the deposit total. I know it's a lot, and I'm sorry I let it get this far.\""), .cross("No foundation was ever poured, was it?", "\"No. I never got to that point. I wanted to, but the materials weren't there.\""), .cross("You told the families work would start in May, didn't you?", "\"Yes. I believed it. I couldn't keep that promise. I should have told them sooner.\""), .cross("You never pulled a permit for any of the nine homes. Why not?", "\"I was waiting for materials. I know permits do not depend on lumber, and I let that slide.\""), .cross("Did any of the families ask you for their money back?", "\"Yes, starting in month eight. I told them I would work something out, and I was not able to return it.\"")],
        openings: ("{D}, a contractor, took $130,000 in deposits from nine families for new homes, and never poured a foundation. By the sixth month no permits had been pulled. The State will present a homebuyer, the deposit records, and the permit office.", "The defense evidence includes a lumber backorder that stalled the work, a supplier who confirms the delays, and a contractor who meant to build every home."),
        closings: ("Nine families paid $130,000 and got an empty lot. No permits, no foundation, and no refund. That's a contractor who took the money and didn't build.", "A real backorder and a contractor who fell behind. {D} planned to build. The State has not proved {DL} took the deposits with no intent to perform."),
        timeline: [(-240, "The first deposit."), (0, "Month 6: no permits."), (0, "Month 8: families complain."), (1, "{DL} is charged.")],
        identified: "Deposit records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "We lost our down payment, sixteen thousand dollars we saved over six years. We watched the empty lot for months and kept being told it was the lumber. By the time we asked for a permit, we learned none had been pulled. We're renting again, and our baby is sleeping in a closet.",
        doctrines: ["burdenOfProof"])

    static let realtorEscrowTake = SmallCases.make(
        key: "story.realtorEscrowTake",
        category: .whiteCollar,
        headlines: ["Real Estate Agent Took Client Escrow Money", "Closing Funds Never Arrived"],
        law: "embezzlement100k",
        threshold: 8,
        spec: "Embezzled over $100,000 belonging to {V} by a person in a position of trust, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A closing failed on {DATE} because $118,000 in escrow funds from {V} had been moved to {D}'s personal account. {DL} was the agent. {DL} says the money was a temporary bridge.",
        state: [E(.document, 3, "Bank Records", "$118,000 moved to {D}'s account."), E(.document, 3, "Escrow Agreement", "{D} held the funds."), E(.statement, 2, "Lawyer", "The closing failed.")],
        defense: [E(.document, 1, "Bridge Note", "A note promising repayment.")],
        role: "Closing attorney",
        exam: [.direct("What happened to the closing?", "\"It failed because $118,000 in escrow funds from {V} were no longer in the account. They had been moved to {D}'s personal account.\""), .direct("What was {D}'s role?", "\"{DL} was the agent and held the funds under an escrow agreement. {DL} was responsible for keeping them safe.\""), .direct("What do the bank records show?", "\"$118,000 moved from escrow into {D.his} personal account. Part of it was spent on a boat deposit.\""), .direct("What was your role in the transaction?", "\"I represented the buyer at the closing and held the closing file. Escrow funds were to be disbursed on the closing date after a final check of the account.\""), .direct("How did you discover the funds were gone?", "\"On closing morning I asked the bank for a balance confirmation. It showed far less than $118,000, and the transfers to {D.his} personal account were visible.\""), .direct("What happened to the buyer and the seller?", "\"The closing could not go forward. The seller was left waiting, the buyer lost the rate lock, and both had extra costs and stress.\""), .cross("{D} says it was a temporary bridge, doesn't {D.he}?", "\"That is what {D.he} says. {D.He} claims it was meant to be put back.\""), .cross("Was some of it repaid?", "\"A brokerage account paid $70,000 about a week later. That was not the full amount.\""), .cross("Did the closing eventually happen?", "\"Not on schedule. It failed and had to be reworked.\""), .cross("Did {D} tell you about the transfer before you found it?", "\"No. I learned about it from the bank record, not from {D.him}. {D.He} spoke to me only after I confronted {D.him}.\""), .cross("Did the defendant cooperate once the problem came out?", "\"Yes. {D.He} gave us records, talked about repayment, and did not deny that the money was moved.\"")],
        defenseRole: "Title clerk",
        defenseExam: [.direct("Did {D} say anything to you about repaying the money?", "\"Yes. {D} told me it was meant as a bridge and that it would all be repaid before the closing.\""), .direct("Was any of the money actually repaid?", "\"Not all of it. $70,000 came back within about a week from a brokerage account, as I understand it.\""), .direct("How did the defendant act once the problem came out?", "\"{D.He} was open about it once the closing was in trouble. I did not feel {D.he} was trying to hide it.\""), .direct("How does a title clerk handle escrow deposits?", "\"We receive the funds, record them, and move them only on written instruction from both sides. A ledger tracks every deposit and release.\""), .direct("What happened with this file?", "\"The funds were deposited as agreed. When we went to confirm, the balance was short, and the bank detail showed transfers out.\""), .direct("What did the defendant say when it came up?", "\"{D.He} said it was meant as a bridge and that it would be repaid. {D.He} acknowledged the problem right away.\""), .cross("Did the buyer or seller approve the transfer to the defendant's account?", "\"Not as far as I know. Nobody on either side authorized the agent to move escrow funds.\""), .cross("About how much was still unpaid after the $70,000?", "\"About $48,000. I do not know whether it has been paid back since then.\""), .cross("Did the escrow agreement allow the defendant to move the funds?", "\"No, the agreement did not allow it. Escrow money is supposed to stay in escrow until closing.\""), .cross("Did the escrow agreement allow transfers out of the account to the defendant?", "\"No. It only allowed disbursement at closing to the parties named in the settlement statement.\""), .cross("Did the defendant get permission from anyone on the file?", "\"Not from me and not that I know of. I did not authorize it.\"")],
        theory: ("{D} took escrow funds.", "A bridge."),
        allocution: "\"I moved that money as a temporary bridge, and I fully intended to put it back before the closing. I know it was wrong, and I know part of it paid for a boat deposit, which I regret deeply. I repaid seventy thousand dollars within a week. I'm sorry for the family who lost their house because of my choices.\"",
        truths: ("{DL} spent funds on a boat deposit.", "{DL}'s brokerage covered $70,000 of the shortfall within a week."),
        defendant: [.direct("Why did you move the money?", "\"As a temporary bridge. I intended to put it back before the closing.\""), .direct("What did you spend it on?", "\"Part of it was a deposit on a boat. I know that was wrong.\""), .direct("Did you repay?", "\"Yes. I repaid $70,000 within a week from my brokerage account.\""), .direct("Why did you take the money out of escrow?", "\"I had a short-term cash problem and thought I could return the funds within days. I convinced myself it was a loan I could cover.\""), .direct("What was your plan to restore it before closing?", "\"I expected a commission from another sale and a payment from my brokerage. They both took longer than I told myself they would.\""), .direct("What did you do once the closing failed?", "\"I met with the attorney, handed over my statements, and told the buyer and the seller exactly what I had done.\""), .cross("You took $118,000 of someone else's escrow money, didn't you?", "\"Yes. I should not have touched it. I thought I could fix it.\""), .cross("A boat deposit is not a bridge, is it?", "\"No. It is not. I made a bad decision.\""), .cross("The rest, about $48,000, is still missing, isn't it?", "\"I am working to repay it. I have not been able to yet.\""), .cross("You signed an agreement that said escrow funds stay in escrow. Did you understand that?", "\"Yes. I understood it fully. I made a terrible choice, and I knew it was against the agreement.\""), .cross("A note promising repayment means you knew it was not yours, doesn't it?", "\"It means I knew I owed it back. That is the problem. I should never have moved it in the first place.\"")],
        openings: ("A closing failed because $118,000 in escrow funds from {V} had been moved into the personal account of {D}, the agent. Part went toward a boat deposit.", "Weigh the defense proof, which will show that {D} meant the transfer as a temporary bridge and repaid $70,000 within a week from a brokerage account."),
        closings: ("$118,000 in escrow money moved into {D}'s own account, and a boat deposit paid. Escrow funds are not a loan to the agent.", "{D} moved the money as a bridge and repaid most of it quickly. The State must prove {DL} meant to steal, and a rapid repayment points the other way."),
        timeline: [(-14, "Escrow is funded."), (0, "Closing day."), (0, "The funds are missing."), (1, "{DL} is reported.")],
        identified: "Bank records.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "We lost the house we were supposed to close on, and we'd already sold our old home. Our children started the school year living with my sister. The agent knew exactly how much that house meant to us. I still can't believe the money we trusted to an escrow account was gone.",
        doctrines: ["burdenOfProof"])

    static let chopShopTrucks = SmallCases.make(
        key: "story.chopShopTrucks",
        category: .property,
        headlines: ["Deputies Find Chop Shop Stripping Stolen Pickups", "Plates and Serials Ground Off"],
        law: "possStolen",
        threshold: 8,
        spec: "Possessed stolen vehicles and parts valued over $100,000, knowing them to be stolen, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Deputies raided a shop on {DATE} and found six stripped pickups. Serial plates were ground off. {D} owns the shop. {DL} says tenants used the back bay.",
        state: [E(.physical, 3, "Stripped Trucks", "Six pickups with ground serials.", .search), E(.document, 3, "Lease", "{D} owns the shop."), E(.digital, 2, "Phone Messages", "'Need 3 F-250 beds' sent to {D}.")],
        defense: [E(.document, 1, "Tenant Lease", "A lease for the back bay.")],
        role: "Auto theft investigator",
        exam: [.direct("What did deputies find at {DL}'s shop on {DATE}?", "\"Six stripped pickups. The serial plates had been ground off each one. It's the sign of a chop shop.\""), .direct("Who owns the shop?", "\"{D}. The lease shows {DL} owns the property. {D.He} was the one we dealt with there.\""), .direct("What messages connected {DL}?", "\"A message sent to {D.his} phone said, 'Need 3 F-250 beds.' It looks like an order for stolen parts.\""), .direct("How did you get to the shop?", "\"We had a tip about stolen pickups. After watching the property for two days, a team entered at morning with a warrant and found the back bay doors closed.\""), .direct("What exactly was in the back bay?", "\"Six pickups in various stages of stripping, with beds removed, wheels off, and wires cut. Parts were stacked against the wall.\""), .direct("What did you do with the serial information?", "\"We checked frame numbers and hidden stamps and ran them against stolen vehicle reports. Several matched trucks stolen from three different counties.\""), .cross("{DL} says tenants used the back bay, doesn't {D.he}?", "\"{D.He} does say that, and there is a lease for the back bay. I can't say who really used it.\""), .cross("Did you see {DL} strip any truck?", "\"No. I wasn't there at the time. I found the trucks, the ground serials, and the messages.\""), .cross("Can you say {DL} read that message?", "\"I can say it was sent to {D.his} phone. I can't say when it was opened or by whom.\""), .cross("Did you find any paperwork showing {D} bought or sold these parts?", "\"No receipts, no invoices, and no title work for the trucks that I found in the office.\""), .cross("Was the defendant at the shop during the raid?", "\"{DL} arrived a short while after we entered. {DL} said the back bay was leased and gave the name of a tenant.\"")],
        defenseRole: "Neighboring shop owner",
        defenseExam: [.direct("Do you own the shop next door to {DL}'s?", "\"Yes. I see {D}'s place every day. I'm aware of the comings and goings.\""), .direct("Did you see anyone using the back bay?", "\"Yes. A person came and went at odd hours. I assumed it was a tenant.\""), .direct("How often?", "\"Most weeks. Mostly evenings. I didn't pay close attention.\""), .direct("How close is your shop to {D}'s?", "\"Next door. We share a fence line and a driveway entrance, and I see {D.his} building from my office window.\""), .direct("What kind of activity did you notice in the back bay?", "\"A truck backing up now and then, usually after dark. I thought it was a renter bringing in work.\""), .direct("How would you describe your dealings with the defendant?", "\"Friendly. We swap tools sometimes and talk shop at lunch. {DF} never struck me as a person who strips trucks.\""), .cross("Could you see the person's face?", "\"No. I never got a good look. It was dark and from a distance.\""), .cross("Did you see {DL} with that person?", "\"No. I never saw them together. I only saw the person alone.\""), .cross("Do you know whether the person was a tenant?", "\"No. That's what I assumed. I don't know what the arrangement was.\""), .cross("Did you ever go into the back bay?", "\"No. Not once. I do not know what was inside any more than anyone else.\""), .cross("Did the defendant ever tell you about the tenant?", "\"Only that someone was renting the space. {DF} did not name anyone, and I did not ask.\"")],
        theory: ("{D} ran a chop shop.", "A tenant."),
        allocution: "\"I own that shop, and I rented the back bay to a tenant I did not watch closely enough. I did not know where those trucks came from, and I never worked on them. I took the rent and stayed away from the back, and I regret how little attention I paid. I'm sorry for the owners who lost their trucks.\"",
        truths: ("{DL} received the messages.", "The tenant lease is unsigned."),
        defendant: [.direct("Whose trucks were in your shop?", "\"Not mine. I rented the back bay to a tenant. I don't know where the trucks came from. I didn't work on them.\""), .direct("Did you know what the tenant was doing?", "\"No. I took the rent and left the tenant alone. I wasn't in the back bay much.\""), .direct("What about the message about F-250 beds?", "\"I don't recall reading that. I get a lot of messages. I didn't respond to it.\""), .direct("How do you use the shop?", "\"I run a small repair business out of the front bay. The back bay has its own door and I rent it out to cover the mortgage.\""), .direct("Tell the jury about the tenant.", "\"I met the tenant through a mutual acquaintance. We agreed on a monthly rent, the tenant paid cash, and I did not poke around.\""), .direct("How did you react when deputies told you what was in the back bay?", "\"I was stunned. I told them I had not been in that bay in weeks and that I would cooperate fully with any search.\""), .cross("You own the shop, don't you?", "\"Yes. I'm responsible for it. But I didn't operate any chop shop.\""), .cross("Six stripped pickups were in your shop, weren't there?", "\"In the back bay, yes. I didn't know. I didn't go back there.\""), .cross("You can't name the tenant, can you?", "\"I know a first name. I don't have a good way to find the tenant. I realize how that looks.\""), .cross("Your lease with the tenant is unsigned, isn't it?", "\"Yes. We made a handshake deal and I wrote the terms on a piece of paper. I should have had a signed lease.\""), .cross("If a message offered to buy F-250 beds from your shop, why would the sender choose you?", "\"Maybe somebody got my number from a customer. I did not answer, and I do not know who it was.\"")],
        openings: ("Deputies raided {D}'s shop and found six stripped pickups with ground-off serial plates. {D.He} owns the shop, and a message sent to {D.his} phone said, 'Need 3 F-250 beds.' The State will show the trucks, the lease, and the messages.", "The defense will present a back bay leased to a tenant, a neighbor who saw a stranger coming and going, and an owner who stayed out of the tenant's business."),
        closings: ("Six stripped trucks with ground serials, in a shop {D} owns, and a message ordering truck beds sent to {D.his} phone. It's a chop shop, and {D.he} runs the place.", "A landlord is not responsible for everything a tenant does. A stranger used the back bay, and the State has not proved {D} knew."),
        timeline: [(-30, "The back bay is leased, {DL} says."), (0, "Morning: the raid."), (0, "Noon: trucks are logged."), (1, "{DL} is charged.")],
        identified: "A raid.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure"])

    static let cyclistDawnHitRun = SmallCases.make(
        key: "story.cyclistDawnHitRun",
        category: .traffic,
        headlines: ["Cyclist Killed at Dawn; Driver Left the Scene", "Mirror Fragment Found on Shoulder"],
        law: "hitAndRun",
        threshold: 8,
        spec: "Left the scene of a crash causing death without stopping, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a cyclist, was killed on a county road at dawn on {DATE}. A mirror fragment matched a truck owned by {D}, who left. {DL} says {D.he} thought {D.he} hit a deer.",
        state: [E(.physical, 3, "Mirror Fragment", "Matches {D}'s truck.", .search), E(.forensic, 3, "Autopsy", "Fatal head trauma."), E(.digital, 2, "Phone Location", "{DL}'s phone on the road at 6:10.")],
        defense: [E(.statement, 1, "Deer", "{DL} says {D.he} thought it was a deer.")],
        role: "Highway Patrol trooper",
        exam: [.direct("What did you find on the county road at dawn on {DATE}?", "\"{V}, a cyclist, had been killed. The autopsy found fatal head trauma. A vehicle had struck {V} and left.\""), .direct("What was recovered at the scene?", "\"A mirror fragment. It matches a truck owned by {D}. That's what led us to {D.him}.\""), .direct("What other evidence ties {DL} to the road?", "\"{D.his} phone was on that road at 6:10, around the time of the crash. {D.He} left and didn't call for help.\""), .direct("What time and where did the crash happen?", "\"About 6:05 a.m., on a straight stretch of a county road with a narrow shoulder. {V} was on a bicycle with a rear light and a reflective vest.\""), .direct("How was {V} found?", "\"A runner came upon {V} at about 6:40 and called 911. {V} was already gone, and the bicycle lay in a ditch twenty feet beyond the point of impact.\""), .direct("How did you connect the mirror fragment to {D}'s truck?", "\"A small piece of black housing was at the scene. A lab matched its shape and break pattern to the damaged mirror on {D.his} truck, which we inspected.\""), .cross("{DL} says {D.he} thought {D.he} hit a deer, doesn't {D.he}?", "\"Deer are common on that road. I can't say what {D.he} thought.\""), .cross("Was there any sign of a deer at the scene?", "\"I didn't find a deer. I found a cyclist and the mirror fragment. I can't speak to what {D.he} thought.\""), .cross("How much damage did {DL}'s truck have?", "\"The mirror was broken. I recall minor damage. It would have been a noticeable jolt, but I can't say how much.\""), .cross("Did you find skid marks from the defendant's truck?", "\"No. There were no skid marks. It is possible the driver never braked, which is consistent with someone who did not realize what had happened.\""), .cross("Did any evidence at the scene point to a deer?", "\"A deer carcass had been reported on that road earlier, but I found no fresh deer evidence at the point of impact.\"")],
        defenseRole: "Deer hunter",
        defenseExam: [.direct("Are deer common on that road?", "\"Yes. Every morning. I hunt in that area, and I see them all the time.\""), .direct("How often do vehicles hit deer?", "\"Frequently. It's a known problem. People hit deer there and keep going.\""), .direct("What does a deer strike look like?", "\"Often a thud on the side or front. People think it's an animal and sometimes don't stop.\""), .direct("How long have you hunted in the area?", "\"About twenty years, mostly along that stretch of county road at dawn and dusk. I know how the deer move.\""), .direct("How often do deer cross there at that hour?", "\"Most mornings you can see two or three. Drivers hit them regularly, and people often keep going if they only clip one.\""), .direct("Do deer cross that road in groups?", "\"Usually in twos and threes, and one often follows another across. If you hit the first one, others may still be crossing right behind it.\""), .cross("Were any deer struck on that day?", "\"Not that I know of. I didn't hear of any.\""), .cross("Would you stop if you thought you'd hit something?", "\"I'd check. I hope anyone would.\""), .cross("Can a cyclist be mistaken for a deer?", "\"In the dark, maybe. I wouldn't think so. But I wasn't there.\""), .cross("Have you ever heard of a driver mistaking a person for a deer?", "\"No, not personally. I would hope that a driver would look and check.\""), .cross("Were you on the road the morning {V} was hit?", "\"No. I was not there, so I cannot tell you what happened that day.\"")],
        theory: ("{D} killed a cyclist and left.", "A deer."),
        allocution: "\"I felt a hit on the side of my truck that morning, and I thought it was a deer, since they're common on that road. I should have stopped and checked, and I'll have to live with that. I'm so sorry for the family and for the loss of someone who was only riding to work. I never knew.\"",
        truths: ("{DL} drove straight to a car wash.", "A deer carcass was reported on that road the day before."),
        defendant: [.direct("What happened that morning?", "\"I was driving before dawn and felt a hit on the side of my truck. I thought it was a deer. It's common on that road.\""), .direct("Why didn't you stop?", "\"I thought it was a deer and I kept going. It was dark and I was hurrying to work. I never thought it was a person.\""), .direct("How did you find out?", "\"Deputies came to talk to me. I was shocked. I'd never have driven on if I knew it was a person.\""), .direct("What route do you drive to work?", "\"That county road, the same way each morning. I leave around six and the sun comes up while I am on it.\""), .direct("What did you feel when the truck was hit?", "\"A hard thump near the mirror on the passenger side. I looked in the mirror and saw nothing in the dim light, and I assumed a deer.\""), .direct("What did you do afterward?", "\"I kept driving to work and did not call anyone. Later I noticed the mirror was damaged and did not think it was serious.\""), .cross("The mirror fragment is from your truck, isn't it?", "\"Yes, I know that now. I noticed the mirror was damaged later. I connected it to a deer.\""), .cross("You didn't look back, did you?", "\"No. In hindsight, yes. I assumed it was an animal.\""), .cross("Your phone was on that road at 6:10, wasn't it?", "\"Yes, that's my route. I was driving to work.\""), .cross("You noticed the mirror was damaged. Why did you not report a possible collision?", "\"I did not connect it to anything serious. I thought it was an animal strike and just wanted it cleaned up.\""), .cross("Did you try to fix or hide the damaged mirror?", "\"No. I left the truck where it was, and anyone could see the mirror. I did not think I had anything to hide.\"")],
        openings: ("At dawn on a county road, a cyclist was killed by a vehicle that did not stop. A mirror fragment at the scene matches {D}'s truck, and {D.his} phone was on that road at 6:10. The State will present the trooper and the evidence.", "Jurors will also see a driver who thought a strike in the dark was a deer, on a road where deer are everywhere, and who had no idea a person was hit."),
        closings: ("A cyclist dead on the road, a mirror fragment that matches {D}'s truck, and a driver who left. The evidence shows who was there.", "Deer are common on that road, and {D} felt a hit in the dark. The State has not proved {DL} knew a person was struck, and without knowledge there is no hit and run."),
        timeline: [(0, "6:05 a.m.: the crash."), (0, "6:10 a.m.: {DL}'s phone passes."), (0, "6:40 a.m.: a runner finds {V}."), (1, "{DL} is identified.")],
        identified: "A mirror fragment.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "{V.He} was riding to work on that road before dawn, the way {V.he} did every morning. {V.He} wore {V.his} reflective vest and kept to the shoulder. I keep thinking about the minutes {V.he} lay there while someone drove on. Our family has not been the same since, and {V.his} chair at dinner is still empty.",
        doctrines: ["mistakeOfFact"],
        genders: ["V": .female])

    static let flowersAtWork = SmallCases.make(
        key: "story.flowersAtWork",
        category: .family,
        headlines: ["Man Violated Protective Order by Showing Up at Ex's Workplace With Flowers", "Security Camera Shows Him at Desk"],
        law: "dvpoViolation",
        threshold: 7,
        spec: "Willfully violated a valid domestic violence protective order, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} walked into {V}'s workplace on {DATE} with flowers despite a protective order forbidding contact. {DL} says {D.he} was delivering for a florist. The order, entered two weeks earlier, barred contact within 100 feet of {V}'s workplace. {DL} came in at about 10 a.m., {V} called deputies five minutes later, and {DL} was arrested at 10:30 a.m.",
        state: [E(.video, 3, "Lobby Camera", "{D} at the front desk."), E(.document, 3, "Order", "No contact within 100 feet of work."), E(.statement, 2, "Receptionist", "'He asked for {V} by name.'")],
        defense: [E(.document, 1, "Florist Receipt", "A receipt for flowers.")],
        role: "Receptionist",
        exam: [.direct("What happened at your front desk on {DATE}?", "\"At about 10 a.m., {D} walked in with flowers and asked for {V} by name. That was a surprise, because I knew about the order.\""), .direct("What was the order?", "\"A protective order entered two weeks earlier. It bars contact within 100 feet of {V}'s workplace. {DL} came into the lobby.\""), .direct("What did you do?", "\"I told {V} and called for help. {V} called deputies five minutes later, and {DL} was arrested at 10:30.\""), .direct("What did {D} look like when {D.he} came in?", "\"{D.He} wore jeans and a plain jacket and carried a bouquet of flowers wrapped in paper. {D.He} came straight up to my desk and spoke in a calm voice.\""), .direct("What exactly did the defendant say?", "\"{DL} asked for {V} by name and said there was a delivery. I told {DL} to wait, and I stepped away to tell {V} right away.\""), .direct("How did {V} react?", "\"{V} went pale and shook. {V} asked me to call deputies and stayed in a back office until they arrived at about 10:30.\""), .cross("{DL} says {D.he} was delivering for a florist, doesn't {D.he}?", "\"{D.He} had flowers in hand. I can't say whether {D.he} was working or whether it was personal.\""), .cross("Did {DL} threaten anyone?", "\"No. {D.He} was polite at the front desk and didn't raise {D.his} voice. It was a calm exchange.\""), .cross("Did you see a florist's uniform or van?", "\"No uniform that I noticed. I didn't see a van. I only saw {D.him} with the flowers.\""), .cross("Did the defendant try to get past your desk?", "\"No. {D.He} stayed in front of the desk and waited. {D.He} did not move toward the offices or raise a voice.\""), .cross("Did you check whether the flowers had a card?", "\"There was a small card, but I did not read it. I handed the whole matter to {V} and the deputies.\"")],
        defenseRole: "Florist",
        defenseExam: [.direct("Does {DL} work for you?", "\"Part-time. {D} does deliveries now and then. {D.He} has been reliable.\""), .direct("Did {DL} deliver flowers that day?", "\"I have a receipt for flowers. I can say that flowers were prepared that morning.\""), .direct("Who requested the arrangement?", "\"A customer called in. I wrote up the order. I didn't know about any protective order.\""), .direct("How long have you run the flower shop?", "\"Eleven years. I take orders by phone and online, prepare arrangements, and send out deliveries with part-time help.\""), .direct("How did the order in question come in?", "\"A customer called, gave me a name and an address, and paid by card. I wrote it on a slip and put it with the arrangement.\""), .direct("Why did you call {D} to deliver?", "\"My regular driver was out, and {DF} had done deliveries for me before. I phoned that morning and asked for a quick run.\""), .cross("Was {DL} scheduled that day?", "\"No. {D.He} wasn't on the schedule. I may have called {D.him} in to help.\""), .cross("Did you tell {DL} where to deliver?", "\"I gave an address. I didn't notice it was {V}'s workplace. I would have never sent {DF} there.\""), .cross("Did {DL} tell you about a protective order?", "\"No. {D.He} never mentioned one. I wasn't aware of it.\""), .cross("Did you tell the defendant who the recipient was?", "\"The slip had the recipient's name on it. I did not say it out loud, and I did not know {DF}'s history with that person.\""), .cross("Did you ever ask the defendant whether there were any addresses to avoid?", "\"No. I did not think to ask. It was a regular delivery as far as I knew.\"")],
        theory: ("{D} violated an order.", "A delivery."),
        allocution: "\"I work part-time for a florist, and I was sent to deliver an arrangement that morning. I didn't know the recipient was {V} until I was through the door. I knew about the order, and I should have turned around the second I understood, but I froze. I'm sorry for scaring {V.him}, and I meant no contact.\"",
        truths: ("{DL} had texted {V} twice that week.", "A florist's order slip shows a customer asked {DL} to deliver them."),
        defendant: [.direct("Why were you at {V}'s workplace?", "\"I work part-time for a florist. I was told to deliver an arrangement there. I didn't see that the recipient was {V} until I walked in.\""), .direct("Did you know about the protective order?", "\"Yes. I knew there was an order. But I didn't know I was delivering to {V}'s workplace. I was sent to make a delivery.\""), .direct("What did you do when you realized?", "\"I stayed at the desk and asked for the person on the order. Then I realized. I didn't try to see {V}.\""), .direct("How did you end up making this delivery?", "\"The florist called me early that morning and said an order needed to go out right away. I picked up the arrangement and a slip with the address.\""), .direct("What did you notice about the address?", "\"It was a business park, and I did not recognize the name of the company. I did not connect it with where {V} worked.\""), .direct("What happened at the front desk?", "\"I told the receptionist I had a delivery and asked for the name on the order. Then the receptionist stepped away, and I realized whose name it was.\""), .cross("You asked for {V} by name, didn't you?", "\"I asked for the recipient on the order, which was {V}'s name. I know that looks bad.\""), .cross("The order barred you within 100 feet, didn't it?", "\"Yes. I knew that. I should have checked the address. I made a mistake.\""), .cross("You work part-time for the florist, don't you?", "\"Yes. But I wasn't on the schedule that day. I came in because they asked me to.\""), .cross("You knew about the protective order and you asked for {V} by name. How is that not contact?", "\"I asked for the name on the slip without understanding it was {V}. By the time I did, the receptionist had already gone.\""), .cross("You could have called the florist to check the recipient before you went inside. Why didn't you?", "\"I should have. I was in a hurry, and I trusted that the order was ordinary.\"")],
        openings: ("A protective order barred {D} from contact within 100 feet of {V}'s workplace. Two weeks later, at about 10 a.m., {DL} walked into the lobby with flowers and asked for {V} by name. The State will show the lobby camera and the order.", "The defense evidence includes a part-time florist's helper sent on a delivery, who did not know the recipient or the address, and who never tried to reach {V}."),
        closings: ("A protective order, a lobby camera, and {D} asking for {V} by name. {DL} knew about the order, and showed up with flowers anyway.", "A delivery for a florist, an address {D} never checked, and no attempt to reach {V}. The State has not proved {DL} knowingly violated the order."),
        timeline: [(-14, "The order is entered."), (0, "10 a.m.: the visit."), (0, "10:05 a.m.: {V} calls deputies."), (0, "10:30 a.m.: {DL} is arrested.")],
        identified: "A camera.",
        mood: .wantsConviction,
        impact: "I was terrified when {D.he} walked through the door with those flowers. I thought the order meant I was safe at work, and I'd told my coworkers to call someone if they saw {D.him}. I locked myself in the break room and shook for an hour. I don't open the front door anymore.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let lakeCabinRansom = SmallCases.make(
        key: "story.lakeCabinRansom",
        category: .violent,
        headlines: ["Teen Held for Ransom in Lake Cabin, Deputies Say", "Father Receives Photo and Demand"],
        law: "kidnapping1",
        threshold: 8,
        spec: "Unlawfully confined and restrained {V}, a minor, for ransom, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a sixteen-year-old, was held in a lake cabin for two days on {DATE} while a $50,000 demand was sent to {V.his} father. {D}, a family acquaintance, was arrested at the cabin. {DL} says the teen came willingly.",
        state: [E(.digital, 3, "Ransom Message", "A demand from a prepaid phone."), E(.physical, 3, "Phone", "The prepaid phone in {D}'s bag.", .search), E(.statement, 3, "Teen", "'I was locked in.'")],
        defense: [E(.statement, 1, "Willing", "{DL} says {V} came willingly.")],
        role: "Detective",
        exam: [.direct("What led to {D}'s arrest?", "\"A sixteen-year-old was held in a lake cabin for two days while a $50,000 demand was sent to the teen's parent. {D} was arrested at the cabin.\""), .direct("What was found at the cabin?", "\"A prepaid phone in {D.his} bag. The ransom message came from that phone.\""), .direct("What did the teen tell you?", "\"'I was locked in.' The teen described a latch on the door and said there was no way out.\""), .direct("How did the investigation reach the cabin?", "\"On Saturday {V}'s parent received a text demanding $50,000 and warning not to call anyone. We traced the prepaid phone's signal to the lake area and found the cabin.\""), .direct("What happened when deputies entered on Sunday?", "\"We found {V} in a back bedroom and {DL} in the main room. A latch on the outside of the bedroom door was visible, and {V} came out quickly.\""), .direct("What did {V} say about the two days?", "\"That {DL} drove {V} there Friday and then kept the door latched. {V} said {V.he} was frightened and told us {DL} took {V.his} phone.\""), .cross("{D} says the teen came willingly, doesn't {D.he}?", "\"Yes. {D.He} says that. The teen texted a friend about staying, which we noted.\""), .cross("Was {D} in debt?", "\"{D.He} owed $40,000 to a lender. That is part of why I looked at {D.him}.\""), .cross("Was the teen hurt?", "\"No injuries. The teen was frightened but physically unharmed.\""), .cross("The teen texted a friend that {V.he} was staying. Did you look at that message?", "\"Yes. It said {V.he} was staying at a cabin for the weekend. It does not say whether {V.he} was free to leave.\""), .cross("Was the cabin owned by the defendant?", "\"It belonged to a relative of {DL}'s. {DL} had a key and permission to be there.\"")],
        defenseRole: "Cabin neighbor",
        defenseExam: [.direct("Did you see the teen at the lake cabin?", "\"Yes. I saw the teen outside laughing on one afternoon, in the yard near the cabin.\""), .direct("Did the teen seem afraid or upset?", "\"No. The teen looked relaxed to me. I did not notice anything wrong or any sign of trouble.\""), .direct("Was the teen free to leave, as far as you could tell?", "\"I do not know. I did not see a lock or anyone stopping the teen, but I was not watching closely.\""), .direct("How well do you know the cabins along that shore?", "\"I have lived two cabins down for years. We know who comes and goes, and we wave to one another from our docks.\""), .direct("Did you see any adult with the teen that weekend?", "\"No, only the teen. I didn't see any adult out in the yard with them.\""), .direct("Did you hear anything unusual from the cabin?", "\"No shouting and no calls for help. Voices carried across the water on Saturday evening, and they sounded ordinary.\""), .cross("How far were you from the cabin when you saw the teen?", "\"A couple of cabins down the shore. I only saw the teen briefly, and I did not get a close look.\""), .cross("Did you speak with the teen at any time?", "\"No. I only saw the teen from a distance, and I never had a conversation about anything.\""), .cross("How long did you watch the cabin that day?", "\"Just a few minutes. I cannot tell you what went on there during the rest of the two days.\""), .cross("Were you watching the cabin continuously?", "\"No, only in passing. I spent most of the weekend working on my own place.\""), .cross("Did you see the door of the bedroom?", "\"No. I never saw the inside of the cabin. I only saw the yard and the driveway.\"")],
        theory: ("{D} held a teen for ransom.", "A willing guest."),
        allocution: "\"I did not demand ransom from anyone, and I did not send that message. The prepaid phone was mine, but I don't know what was sent from it. I have known that family for years, and I would never harm their child. I'm sorry for the days they spent frightened, and I hope the court will look at the whole story.\"",
        truths: ("{DL} owed $40,000 to a lender.", "The teen texted a friend that {V.he} was staying."),
        defendant: [.direct("Did you demand ransom?", "\"No. I did not demand money from anyone. I did not send that message.\""), .direct("Why did you have a prepaid phone?", "\"It was mine. I use a prepaid phone, and I did not know what had been sent from it.\""), .direct("What about the latch on the door?", "\"It was for privacy. I did not use it to lock anyone in.\""), .direct("How do you know {V}'s family?", "\"Through years of social events and church. I have known {V}'s parent for a long time and have watched {V} grow up.\""), .direct("How did {V} come to the cabin?", "\"I offered to take {V} up to the lake for a quiet weekend, and {V} agreed. We left Friday afternoon in my car.\""), .direct("What did you two do at the cabin?", "\"We cooked, played cards, and walked by the water. I did not keep {V} from going out or from using a phone.\""), .cross("You owed a lender $40,000, didn't you?", "\"Yes. I was under pressure. That does not mean I did this.\""), .cross("The ransom message came from your phone, didn't it?", "\"So they say. I did not send it. Someone else could have used it.\""), .cross("The teen says they were locked in. Is the teen lying?", "\"The teen may be mistaken. I did not lock anyone in.\""), .cross("Your financial trouble was serious. Isn't a ransom what that kind of pressure produces?", "\"I was under pressure, but I would never take a child for money. I was embarrassed about the debt and kept it to myself.\""), .cross("A latch on the outside of a bedroom door is hard to explain. What was it for?", "\"It was already there for privacy or storage. I did not engage it on {V}.\"")],
        openings: ("A sixteen-year-old was held in a lake cabin for two days while a $50,000 ransom demand went to a parent. {D}, a family acquaintance, was arrested at the cabin with the prepaid phone used to send it.", "The defense will present evidence that the teen came willingly, texted a friend about staying, and was seen laughing outside. No one was held."),
        closings: ("A demand for $50,000, a prepaid phone in {D}'s bag, a latch on the door, and a teen who says they were locked in. The debt explains the motive.", "A teen who texted a friend about staying and was seen laughing outside. The State has not proved the teen was held against their will."),
        timeline: [(0, "Friday: the pickup."), (0, "Saturday: the demand."), (0, "Sunday: deputies enter."), (0, "Sunday: {DL} is arrested.")],
        identified: "A phone.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "I still can't sleep. I lie awake listening to the door latch in my mind, and I jump at footsteps in the hall. My parents drove all night to find me, and my dad stopped working for weeks. I used to love that lake, and I can't even look at pictures of it now.",
        doctrines: ["necessity"])

    static let roadMergeShooting = SmallCases.make(
        key: "story.roadMergeShooting",
        category: .violent,
        headlines: ["Driver Shot After Highway Merge Dispute", "Brake-Check Preceded Gunfire"],
        law: "murder2",
        threshold: 9,
        spec: "Unlawfully killed {V} with malice, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was shot at a highway exit on {DATE} after a merge dispute. {D}'s pickup was seen leaving. A pistol was found in {D.his} truck. {DL} says {V} had a bat.",
        state: [E(.forensic, 3, "Ballistics", "The bullet matches {D}'s pistol."), E(.video, 2, "Dash Camera", "A pickup brake-checks a sedan."), E(.statement, 2, "Witness", "A pickup leaves the exit.")],
        defense: [E(.statement, 1, "Bat", "{DL} says {V} had a bat.")],
        role: "Highway Patrol trooper",
        exam: [.direct("What did you find at the exit?", "\"{V} had been shot after a merge dispute at a highway exit. A witness saw a pickup leaving.\""), .direct("What does the dash camera show?", "\"A pickup brake-checking a sedan before the exit. It is a short clip, but it shows the driver acting aggressively.\""), .direct("What did ballistics show?", "\"The bullet matches a pistol found in {D}'s truck. The pistol was loaded and had been fired.\""), .direct("What did you see when you reached the exit?", "\"{V} was lying beside a sedan with a gunshot wound, and medics were already working. A bystander had called in a pickup leaving the exit just before I arrived.\""), .direct("What did the defendant say to you when the truck was stopped?", "\"{D.He} said {V} came at {D.him} with a bat after the merge dispute and that {D.he} fired out of fear. {D.He} did not say anything about leaving the exit.\""), .direct("Where was the pistol found?", "\"In {D.his} truck, stopped about an hour later at 6 p.m. It was loaded, two rounds were missing, and the bullet from the scene matched it.\""), .cross("{D} says {V} came at {D.him} with a bat, doesn't {D.he}?", "\"That is what {DL} says. A bat was found behind the seat of the sedan.\""), .cross("Did anyone see {V} swing the bat?", "\"No. A passing motorist saw {V} get out with a long object, but nobody saw a swing.\""), .cross("How many shots were fired?", "\"Two. One struck {V}. The other missed.\""), .cross("Did the bat have anyone's prints on it?", "\"No usable prints were found. The lab said the grip was too worn to lift anything.\""), .cross("Did the defendant have any injuries from the encounter?", "\"None that I saw. There were no bruises and no signs of a struggle on {D.his} body or clothing.\"")],
        defenseRole: "Passing motorist",
        defenseExam: [.direct("What did you see at the exit?", "\"I saw {V} get out of the car holding something. It was a long object.\""), .direct("Could you tell what the object was?", "\"Not clearly. It was long, like a bat, but I could not be sure.\""), .direct("What were you doing on the highway at that hour?", "\"Driving home from work in the right lane. I was passing the exit when I noticed two vehicles stopped on the shoulder.\""), .direct("What caught your attention?", "\"A driver stepping out of a sedan, walking quickly toward a pickup. It was around 5:15 and traffic was heavy.\""), .direct("What did you do next?", "\"I slowed down a bit, then heard two loud cracks. I called 911 as I drove away from the exit.\""), .direct("Was the object moving?", "\"It was raised, but I couldn't tell if it was swinging. It was only a second before I was past.\""), .cross("Did you see the pickup driver?", "\"Only a shape. I could not describe the driver.\""), .cross("Did you see {V} raise the object?", "\"No. I saw it held at the side. It was not raised.\""), .cross("How far were you from the two vehicles?", "\"About fifty yards. I was passing on the highway.\""), .cross("Could you see the driver's face at that distance?", "\"No. I saw a shape in a dark shirt. I could not describe a face or hair.\""), .cross("You were moving at highway speed when you glanced over, weren't you?", "\"Yes. I was moving with traffic and could only glance over for a second or two before I had to watch the road again.\"")],
        theory: ("{D} killed a driver.", "Self-defense."),
        allocution: "\"I fired my pistol that day because I was afraid, and I will carry the death of {V} for the rest of my life. It all happened in seconds, and I believed {V} was coming at me with a bat. I'm sorry for the loss to {V.his} family. I wish with everything in me that I had driven away.\"",
        truths: ("{DL} fired twice.", "The bat was behind the seat."),
        defendant: [.direct("Did you fire the pistol?", "\"Yes, I did. {V} came at me with a bat, and I was afraid.\""), .direct("Why did you fire twice?", "\"I was in fear. It all happened in seconds. I fired and then fired again.\""), .direct("Where was the bat?", "\"Behind the seat of the sedan. I did not see it, but I saw {V} coming with something.\""), .direct("What led up to the dispute on the highway?", "\"Traffic was heavy and we merged at the same time. The sedan came close, I felt cut off, and I tapped my brakes to send a message.\""), .direct("What happened at the exit?", "\"We both pulled off. {V} got out and started toward my truck, holding something long. I stayed in the cab with the window cracked.\""), .direct("What did you do after the shots?", "\"I drove away because I was terrified. When deputies stopped me, I told them right away that I had a pistol and had used it.\""), .cross("You brake-checked {V}'s car first, didn't you?", "\"I braked, yes. I was upset about the merge. I should not have.\""), .cross("A bat was found behind the seat. Doesn't that mean {V} did not have it in hand?", "\"I saw {V} coming with something. I thought it was a bat.\""), .cross("You shot someone over a merge. Is that reasonable?", "\"No. It is not. I was afraid, and I know it was not the right choice.\""), .cross("You could have driven off instead of stopping at the exit. Why didn't you?", "\"I pulled over because I wanted to talk and calm things down. I did not expect it to get violent.\""), .cross("The bat was behind the seat. What did you think you saw in {V}'s hand?", "\"Something long and dark. I took it for a bat. I did not see it clearly, and I know now it may have been something else.\"")],
        openings: ("After a merge dispute at a highway exit, {V} was shot. A dash camera shows a pickup brake-checking a sedan, and the bullet matches a pistol later found in {D}'s truck.", "The defense witnesses will explain that {V} got out of the sedan with a long object and walked at {D}, and that {DL} fired out of fear."),
        closings: ("A brake-check, a shooting, a pickup leaving, and a pistol in {D}'s truck that matches the bullet. {DL} fired twice at a person who was not armed.", "{V} stepped out with a bat and came at {D}. {DL} fired twice in fear. The law lets a person defend against a perceived attack."),
        timeline: [(0, "5:10 p.m.: the merge."), (0, "5:12 p.m.: the exit."), (0, "5:15 p.m.: the shots."), (0, "6 p.m.: {DL} is stopped.")],
        identified: "Ballistics.",
        aggravating: ["The offense involved a firearm"],
        mood: .divided,
        impact: "{V.He} was my husband, and {V.he} left the house that morning to pick up our daughter from practice. We had been married nineteen years. She keeps asking why her father did not come home, and I don't know how to answer her. The house is quiet now, and I'm raising her alone.",
        doctrines: ["selfDefense", "imperfectSelfDefense", "lesserIncluded"],
        genders: ["V": .male])

    static let churchStairShove = SmallCases.make(
        key: "story.churchStairShove",
        category: .violent,
        headlines: ["Man Dies After Shove Down Church Stairs in Seat Dispute", "Pastor Sees Fall"],
        law: "volManslaughter",
        threshold: 7,
        spec: "Unlawfully killed {V} without malice, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, seventy-one, died on {DATE} after falling down church stairs when {D} shoved {V.him} during a dispute over a pew. {DL} says {V} tripped. The pastor testifies to seeing a shove, and the hall camera shows two people at the top of the stairs. Medics arrived at 12:10 p.m., and {V} died at about 1 p.m. of a skull fracture from the fall.",
        state: [E(.statement, 3, "Pastor", "'I saw a shove.'"), E(.forensic, 3, "Autopsy", "Skull fracture from a fall."), E(.video, 2, "Hall Camera", "Two men at the top of the stairs.")],
        defense: [E(.statement, 1, "Trip", "{DL} says {V} tripped.")],
        role: "Pastor",
        exam: [.direct("What did you see at the church on {DATE}?", "\"{V}, who was seventy-one, and {D} were at the top of the stairs in a dispute over a pew. I saw a shove.\""), .direct("What happened to {V}?", "\"{V} fell down the church stairs. Medics arrived at 12:10. {V} died about an hour later, of a skull fracture from the fall.\""), .direct("What does the hall camera show?", "\"Two people at the top of the stairs. It shows them close together and then {V} going down.\""), .direct("Where were you standing at noon that day?", "\"I was across the hall by the sanctuary doors greeting people after the service. I could see the top of the stairs through the open doorway.\""), .direct("What did you see happen between {D} and {V}?", "\"They were arguing over where {V} had been sitting. {DL} stepped toward {V} and shoved {V.him} with both hands, and {V.he} went backward down the stairs.\""), .direct("What did you do?", "\"I ran to the stairs and shouted for help. Another member called for the medics. I knelt by {V} and prayed until they arrived at about 12:10.\""), .cross("{DL} says {V} tripped, doesn't {D.he}?", "\"I saw a shove. But I only saw it for a moment, and I was across the hall.\""), .cross("Were the stairs in good repair?", "\"I believe the rubber at the top was worn. I'd need to ask the usher. I didn't inspect them.\""), .cross("How far away were you?", "\"Across the hall. I could see them, but not every detail. I'm very sure of what I saw.\""), .cross("How loud was the room, and could you hear the argument?", "\"The hall was crowded after the service. I heard raised voices and a few words about the pew, but not the whole argument.\""), .cross("Did the defendant try to help {V} afterward?", "\"Yes. {DL} came down the stairs right away and stayed beside {V}. {DL} looked horrified.\"")],
        defenseRole: "Usher",
        defenseExam: [.direct("Did you know about the stairs?", "\"Yes. I'm an usher, and I walk them every Sunday. The rubber tread at the top was torn.\""), .direct("Was that dangerous?", "\"It could catch a heel. I'd noticed it before.\""), .direct("Was it reported?", "\"Yes. I told someone about it. It had been a problem for a while.\""), .direct("How long have you been an usher at the church?", "\"Fifteen years. I stand near the doors each Sunday, hand out programs, and help older members with the steps.\""), .direct("What can you tell the jury about the top stair?", "\"The rubber tread had torn at the front edge and curled up. A heel or a cane could catch on it.\""), .direct("Did anyone fall on those stairs before this?", "\"A couple of people tripped over the years, but nobody was seriously hurt. That is why I reported the tread.\""), .cross("When did you report it?", "\"Last month. I told the church office. It wasn't fixed by the day of the fall.\""), .cross("Did you see the fall?", "\"No. I was elsewhere in the building.\""), .cross("Did you see a shove?", "\"No. I wasn't there. I can only tell you about the stairs.\""), .cross("Were you present when {V} fell?", "\"No. I was at the other entrance. I came after I heard the commotion.\""), .cross("Does a torn tread make a fall certain?", "\"No. Most people walk over it fine. It is a hazard, but I cannot say it caused this.\"")],
        theory: ("{D} shoved a man to death.", "A trip."),
        allocution: "\"We were arguing about a pew, and I reached out when {V} stumbled at the top of the stairs. I never pushed {V.him}, and I could not catch {V.him} in time. I'm so sorry that {V.he} died, and I'll think about that morning for the rest of my life. I loved that church, and I still do.\"",
        truths: ("{DL} was angry about the pew.", "The stair rubber was torn at the top."),
        defendant: [.direct("What happened at the top of the stairs?", "\"We were arguing about a pew. {V} stumbled and fell. I reached out, but I couldn't catch {V.him}.\""), .direct("Did you push {V}?", "\"No. I never pushed {V.him}. I may have reached out. {V} tripped on the top stair, and I couldn't stop it.\""), .direct("How are you coping with what happened?", "\"Devastated. I've lost sleep over it. I never wanted anyone hurt, least of all like this.\""), .direct("How long had you known {V}?", "\"Many years. We sat near each other at church and had a small history of friction over seating, but nothing that ever turned physical.\""), .direct("Tell the jury what you remember at the top of the stairs.", "\"We were standing side by side and voices went up. {V} turned to leave and caught a foot on the top step. I reached for {V.his} arm but missed.\""), .direct("How did you react after the fall?", "\"I ran down and held {V}'s head until the medics came. I did not leave, and I told the deputies exactly what I remembered.\""), .cross("The pastor says you shoved {V}, doesn't the pastor?", "\"The pastor believes so. I understand why. It happened fast, and it looked like a shove from a distance.\""), .cross("You were arguing about a pew, weren't you?", "\"Yes. It was a silly argument. I regret that. I'd give anything to take it back.\""), .cross("{V} was seventy-one, wasn't {V.he}?", "\"Yes. {V} was elderly. I know it. I'd never have raised a hand.\""), .cross("You and {V} were standing on the landing at the top of a flight of stairs when you argued, weren't you?", "\"Yes. We were right at the top of the stairs, and I know now that was a dangerous place to be arguing.\""), .cross("Why would the pastor say shove if you only reached?", "\"From across the hall, an outstretched arm toward someone at the top of the stairs could look like a shove. I understand how it appeared.\"")],
        openings: ("{V}, seventy-one, fell down church stairs and died of a skull fracture after, the pastor says, {D} shoved {V} during a dispute over a pew. The hall camera shows two people at the top of the stairs. The State will present the pastor and the autopsy.", "Jurors will also see worn stair tread at the top of the stairs, an usher who had reported it, and an accident that no one meant. A fall is not a killing."),
        closings: ("A dispute over a pew, a shove the pastor saw, a fall down the stairs, and a death. {D} put hands on an elderly person at the top of a staircase.", "The tread was torn and had been reported. {D} says {V} tripped. The State has not proved a shove beyond a reasonable doubt."),
        timeline: [(0, "Noon: the dispute."), (0, "12:05 p.m.: the stairs."), (0, "12:10 p.m.: medics arrive."), (0, "1 p.m.: {V} dies.")],
        identified: "A pastor.",
        aggravating: ["The victim was particularly vulnerable"],
        mitigating: ["The defendant has accepted responsibility"],
        mood: .sympathetic,
        impact: "{V.He} sat in that pew for forty years, and now it sits empty every Sunday. {V.He} was seventy-one and still carried the hymnals for the choir. {V.He} fell on a staircase in the house of God, over a seat. I can't walk into that sanctuary without picturing {V.him} at the top of the steps.",
        doctrines: ["lesserIncluded", "mistakeOfFact"],
        genders: ["V": .male])

    static let ranchPipeAssault = SmallCases.make(
        key: "story.ranchPipeAssault",
        category: .violent,
        headlines: ["Ranch Hand Struck With Pipe Over Unpaid Wages", "Foreman Arrested"],
        law: "awdwik",
        threshold: 8,
        spec: "Assaulted {V} with a steel pipe with intent to kill, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a ranch hand, was struck in the head with a steel pipe on {DATE} after demanding unpaid wages. {D}, the foreman, was seen leaving the barn. {DL} says {V} swung first.",
        state: [E(.statement, 3, "Hand", "'{D} hit me with a pipe.'"), E(.physical, 3, "Pipe", "A bloody pipe in the barn.", .search), E(.forensic, 2, "Medical Report", "Skull fracture.")],
        defense: [E(.statement, 1, "Swing", "{DL} says {V} swung first.")],
        role: "Ranch hand",
        exam: [.direct("What happened in the barn?", "\"I demanded my unpaid wages from {D}, the foreman. {D.He} struck me in the head with a steel pipe.\""), .direct("What injury did you have?", "\"A skull fracture. The medical report records it, and I was in the hospital.\""), .direct("What did deputies find?", "\"A bloody steel pipe in the barn. {D.He} was seen leaving the barn right after.\""), .direct("How long had you worked at the ranch?", "\"About two years. I fed stock, repaired fence, and hauled hay. {D.He} was the foreman and set my hours and my pay.\""), .direct("How did you try to collect your wages?", "\"I asked {DL} several times in the weeks before, and each time {DL} said payday would come soon. By that afternoon I was two months behind.\""), .direct("What happened right before you were struck?", "\"I went into the barn at about 4 p.m. and told {DL} I could not wait any longer. We both got loud, and I said I would go to the owner.\""), .cross("{D} says you swung first, doesn't {D.he}?", "\"I did not swing. I had been asking about wages, and I raised my voice.\""), .cross("Did you have a hay hook in your hand?", "\"I may have had one. I was working with it, and it was in my hand.\""), .cross("Were you owed two months of wages?", "\"Yes. {D.He} owed me two months, and I had asked more than once.\""), .cross("You had a hay hook in your hand. Did you raise it?", "\"I had it in hand from the work I was doing. I did not lift it to swing, and I did not threaten {DL} with it.\""), .cross("How would you describe your tone when you spoke to the defendant?", "\"Angry. I was shouting, and I told {D.him} that was not right. I did not use any threats.\"")],
        defenseRole: "Farrier",
        defenseExam: [.direct("What did you see from where you stood in the barn?", "\"I saw {V} lift a hay hook as the argument got louder and more heated between the two of them.\""), .direct("How far away were you when this happened?", "\"About thirty feet. I had a decent view of both of them, though not the best view in the barn.\""), .direct("What did {D} do after {V} lifted the hook?", "\"{D} swung the pipe. It was quick, and the next thing I knew, {V} was down on the ground.\""), .direct("How do you know the defendant and {V}?", "\"I shoe horses at the ranch every few weeks. I have known both of them for a couple of years from working in the barn.\""), .direct("What were you doing in the barn at 4 p.m.?", "\"Trimming a hoof in the far stall. I had my back half turned, and I looked up when the voices got loud.\""), .direct("What did you hear before the pipe swung?", "\"Shouting about wages and about the owner. Then I heard a clang as something metal moved.\""), .cross("Did you see {V} actually swing the hook at the defendant?", "\"No. I saw {V} lift it up, but I did not see a swing at {DF} or anyone else.\""), .cross("Could {V} have been holding the hook for the job?", "\"Yes, it could have been for work. I cannot say what {V} meant to do with it.\""), .cross("Do you work for the defendant at the ranch?", "\"Yes, on occasion I do shoeing work there. I know that matters, and I am telling you what I saw.\""), .cross("The barn was dim at that hour, wasn't it?", "\"It was dim in the back. A couple of bulbs were on, but the far end where they stood was in shadow.\""), .cross("How much do you get paid by the defendant for shoeing?", "\"I bill the ranch. I have been paid on time. I am not here for money, and I do not owe {DF} anything.\"")],
        theory: ("{D} struck a ranch hand.", "A defense."),
        allocution: "\"Yes, I swung the pipe, and I'll tell you why. {V} came at me with a hay hook, and I was afraid for my life. I did owe {V.him} wages, and I'm sorry I let it get to that point. I never wanted anyone hurt, and I wish I had paid {V.him} and walked away.\"",
        truths: ("{DL} owed {V} two months' wages.", "{V} had a hay hook in his hand."),
        defendant: [.direct("Did you hit {V} with the pipe?", "\"Yes, I did. {V} swung a hay hook at me, and I swung the pipe to protect myself.\""), .direct("Why were you arguing?", "\"About wages. {V} said I owed two months, and I did.\""), .direct("Did {V} have a hook?", "\"Yes. {V} had a hay hook in hand, and I saw it come up.\""), .direct("How long have you been foreman, and what do you handle?", "\"Ten years. I schedule the crew, order feed, and pass the owner's pay to the hands. Cash was tight that spring and I fell behind.\""), .direct("Describe what happened in the barn.", "\"{V} came in loud and demanded pay. I said I had it coming soon. {V} stepped toward me with the hook up. I grabbed a pipe leaning on the stall.\""), .direct("What did you do after the swing?", "\"I saw {V} go down and I froze. I stepped out of the barn to call for help and then waited for the deputies to come.\""), .cross("You owed {V} two months of pay, didn't you?", "\"Yes. I was behind. I was trying to find the money.\""), .cross("You struck {V} on the head with a steel pipe, didn't you?", "\"I did. I swung at what was coming at me, and it landed on the head.\""), .cross("You left the barn right after, didn't you?", "\"Yes. I was shaken. I should have stayed to help.\""), .cross("You owed {V} wages. Isn't that a reason to be angry at {V}?", "\"I was frustrated with myself. I owed {V} the money, and I was embarrassed about it.\""), .cross("A steel pipe against a hay hook. Was that proportional?", "\"In the moment I did not think about proportion. I thought I was about to be hit, and I swung without thinking.\"")],
        openings: ("{V}, a ranch hand, demanded two months of unpaid wages and was struck in the head with a steel pipe by {D}, the foreman. {V} suffered a skull fracture.", "The defense case is that {V} raised a hay hook first and that {D} swung the pipe to defend against a worker in a rage over pay."),
        closings: ("Two months of unpaid wages, a steel pipe, a fractured skull, and a foreman walking out of the barn. The motive is clear, and so is the result.", "A hay hook raised in a heated argument, and a foreman who swung to protect {D.himself}. The State must prove {D} was not defending, and the farrier saw the hook."),
        timeline: [(-60, "Wages go unpaid."), (0, "4 p.m.: the demand."), (0, "4:10 p.m.: the strike."), (0, "5 p.m.: {DL} is arrested.")],
        identified: "A witness and a pipe.",
        aggravating: ["The offense involved a weapon"],
        mood: .divided,
        impact: "I can't work now. The pipe struck me above the ear, and I still have headaches that make me dizzy. I spent two months in a hospital bed and I lost the only job I had. I asked for my wages, and what I got was an ambulance ride and a scar.",
        doctrines: ["selfDefense"],
        genders: ["V": .male])

    static let raceTrackBrawl = SmallCases.make(
        key: "story.raceTrackBrawl",
        category: .publicOrder,
        headlines: ["Crowd Brawl at Stock Car Race Injures Six", "Bleachers Empty After Pit Dispute"],
        law: "riot",
        threshold: 7,
        spec: "Participated in a public disturbance involving three or more persons causing injury, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A pit-road dispute at a stock car race on {DATE} spilled into the stands and injured six. {D} was filmed swinging a cooler. {DL} says {D.he} was shielding a child.",
        state: [E(.video, 3, "Track Camera", "{D} swings a cooler."), E(.statement, 2, "Security", "{D} was among the first."), E(.forensic, 2, "Medical Reports", "Six injured.")],
        defense: [E(.statement, 1, "Shield", "{DL} says {D.he} was shielding a child.")],
        role: "Track security guard",
        exam: [.direct("What happened at the race?", "\"A pit-road dispute spilled into the stands, and six people were hurt. I was on duty as track security.\""), .direct("What does the track camera show?", "\"It shows {D} swinging a cooler into the crowd. It is clear on the video.\""), .direct("Was {D} involved from the start?", "\"{DL} was among the first people I saw in the fight. I cannot say who started it.\""), .direct("What were your duties at the track that night?", "\"I was on stands security at the grandstand. I walked the rows, watched crowd behavior, and answered radio calls from the pit gate.\""), .direct("How did the dispute travel from the pits into the stands?", "\"Two groups were shouting at the rail around 8 p.m. A few minutes later, people started pushing, and by 8:10 the fight reached the upper rows.\""), .direct("How many people were injured and how?", "\"Six. Cuts, bruises, and a broken wrist. Medics treated most on site, and one went to the hospital.\""), .cross("Was a child near the defendant?", "\"Yes. A child was in the row near {D.him}. I did not see the child hit.\""), .cross("Did the defendant swing more than once?", "\"I believe so. The camera shows twice, but it is hard to tell.\""), .cross("Were there other people swinging things?", "\"Yes. It was chaotic. Several people were fighting.\""), .cross("Was the defendant one of the people who began the pushing at the rail?", "\"I did not see who started it. I saw {D.him} in the middle of the fight after it spread to the row.\""), .cross("Did you speak with the defendant afterward?", "\"Briefly. {DL} told me a child had been in the row and that {DL} swung to keep people away.\"")],
        defenseRole: "Concession worker",
        defenseExam: [.direct("Was a child standing near {D} during the fight?", "\"Yes. A child was in the row right behind {D}, and I saw {DF} step in front of the child.\""), .direct("Was the child struck by anyone?", "\"No. The child was not hit, as far as I could see from my stand, and I watched the whole time.\""), .direct("What was the defendant doing with the cooler?", "\"Holding it up and swinging it at people who were coming toward the child. That is how it looked to me.\""), .direct("Where is your concession stand in relation to the defendant's seats?", "\"At the end of the row, maybe thirty feet away. I could see most of the row when it was lit by the track lights.\""), .direct("What did you see the defendant do when the fight reached the row?", "\"{D.He} stood up, put a child behind {D.him}, and held up a cooler like a shield.\""), .direct("How did the child react?", "\"Crying and holding onto {D.his} leg. The child looked terrified, and {D.he} kept stepping in front.\""), .cross("Did you see the defendant actually hit someone with the cooler?", "\"I saw the swing. I did not see who it hit, because there were many people in the way.\""), .cross("Was the child related to the defendant?", "\"I think so. I heard it was a niece, but I did not know for sure at the time.\""), .cross("How many times did the defendant swing the cooler?", "\"I saw it once or twice. I was busy at my own counter, so I cannot be exact.\""), .cross("Did you see the cooler hit anyone?", "\"I saw swings. It was too chaotic to track every contact.\""), .cross("Did you see anyone else with a child in that row?", "\"No. I did not see any other children. That is why this one stood out.\"")],
        theory: ("{D} joined a brawl.", "Shielding a child."),
        allocution: "\"I swung that cooler once, and I did it to keep a fight away from my niece. I did not want anyone hurt, and I was afraid for the child. Six people were injured that day, and I'm sorry for every one of them. I'll never take a child to a crowd like that again.\"",
        truths: ("{DL} swung twice.", "A toddler was in the row behind."),
        defendant: [.direct("Did you swing the cooler?", "\"Once, to keep people off the child. I was not trying to hurt anyone else in that crowd.\""), .direct("Why did you swing it?", "\"A fight was coming toward my niece, and I used what I had. I was afraid for the child.\""), .direct("Whose child was it that you were with?", "\"My niece. I took the child to the race, and I was responsible for watching over the child.\""), .direct("Why did you bring a child to the race?", "\"My niece had never seen a stock car race, and I thought it would be a fun evening. We sat a few rows up with a cooler and snacks.\""), .direct("What did you see right before you picked up the cooler?", "\"Two groups pushing, and then people stumbling backward into our row. A fist went past my niece's head.\""), .direct("What did you do after you swung it?", "\"I grabbed my niece and tried to move toward the stairs. Security found us a minute later and led us out.\""), .cross("The camera shows you swinging twice, doesn't it?", "\"It may be twice. It was chaos, and I was not counting how many times I swung.\""), .cross("Six people were hurt in that fight. Weren't you part of it?", "\"I was in it, but I was protecting a child. I did not start the fight.\""), .cross("You could have picked up the child and left, couldn't you?", "\"I tried. There were people in the way, and I could not get through the row.\""), .cross("The footage shows you swinging at people's heads. Were those people attacking you?", "\"They were coming toward us in a pack. I do not know who was who. I swung to keep them back.\""), .cross("Six people were hurt. Could you have hit any of them?", "\"It is possible. I swung once or twice, and I did not look to see where it landed. I am sorry if I hurt anyone.\"")],
        openings: ("A pit-road dispute at a stock car race spilled into the stands and injured six people. A track camera shows {D} swinging a cooler, and security says {D.he} was among the first in the fight.", "Weigh the defense proof, which will show that {D} swung a cooler to shield a niece in the row behind and was not the one who started the fight."),
        closings: ("Six people hurt, a cooler swung into a crowd, and {D} among the first in the brawl. The camera shows the swing, and it was not the only one.", "{D} stepped in front of a child and swung once or twice at people coming toward the child. Protecting a child in a crowd is not rioting."),
        timeline: [(0, "8 p.m.: the pit dispute."), (0, "8:10 p.m.: the stands."), (0, "8:20 p.m.: the swing."), (0, "9 p.m.: arrests.")],
        identified: "Track video.",
        mood: .divided,
        doctrines: ["defenseOfOthers"])

    static let schoolBoardContract = SmallCases.make(
        key: "story.schoolBoardContract",
        category: .whiteCollar,
        headlines: ["School Board Member Took Cash for Bus Contract", "Envelope Passed in Parking Lot"],
        law: "bribery",
        threshold: 8,
        spec: "Corruptly accepted a thing of value as a public official, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D}, a school board member, accepted $9,000 in cash on {DATE} from a bus company seeking a contract. A video recorded the exchange. {DL} says the cash was a campaign donation.",
        state: [E(.video, 3, "Parking Lot Camera", "An envelope passes to {D}."), E(.document, 3, "Contract", "Awarded to the company."), E(.statement, 2, "Company Owner", "'He said it would help.'")],
        defense: [E(.document, 1, "Donation Form", "A blank campaign form.")],
        role: "SBI agent",
        exam: [.direct("What does the parking lot video show?", "\"An envelope passing from the owner of a bus company to {D}, a school board member, with $9,000 in cash inside.\""), .direct("What came after the exchange?", "\"The board awarded the bus contract to that company within a week. The contract is in the file, and the vote followed the cash.\""), .direct("What did the company owner tell you?", "\"The owner said {DL} told the owner that the cash would help. That is what the owner reported to me during the interview.\""), .direct("How did your agency become involved?", "\"The bus company owner contacted us after being pressured for cash. We set up a controlled meeting, equipped the owner with a recorder, and filmed the parking lot.\""), .direct("What exactly happened in the lot at noon?", "\"The owner handed {DL} an envelope with $9,000 in cash. {DL} looked inside, counted it, and put it in a jacket pocket before leaving.\""), .direct("What happened next with the contract?", "\"Within a week, the board voted on the bus contract and awarded it to that company. {D.He} voted in favor.\""), .cross("{D} calls it a campaign donation, doesn't {D.he}?", "\"Yes. A campaign finance filing lists a $9,000 donation from that company, dated the same week. I will agree the filing exists.\""), .cross("Campaign donations to board members are legal, aren't they?", "\"Donations can be legal when they are properly reported. What concerns us is the cash and the timing near the vote.\""), .cross("Was the donation reported on time?", "\"It was reported late. The filing came after the exchange and not in the usual window.\""), .cross("Did the owner agree to pay anything before the meeting?", "\"The owner told us {DL} had said a contribution would help. We did not have a recorded demand beforehand.\""), .cross("Did anyone disclose the donation before the contract?", "\"Not that I found. The filing was made after the exchange, which is why the timing stood out to us.\"")],
        defenseRole: "Board clerk",
        defenseExam: [.direct("Are donations to board members normal in this district?", "\"Yes. Board members receive donations at election time, and many of them come from local businesses.\""), .direct("Was a cash donation normal?", "\"It was rare. Most donations came by check, so cash stood out to me when I heard about it.\""), .direct("Did {D} file the donation paperwork?", "\"{D} did file it, though it was late. I processed the filing in my office.\""), .direct("What is your role at the board office?", "\"I take minutes, keep records, and process campaign filings for members. I have done it for nine years.\""), .direct("How does the bidding process work for bus contracts?", "\"Each company submits a sealed bid with price and safety history, and the board reviews them in public. The lowest qualified bid usually wins.\""), .direct("How did this company's bid compare?", "\"It was lower than the other two and had a clean safety record. The staff memo recommended it.\""), .cross("Did you see the envelope handed over?", "\"No. I did not see the exchange. I only know what the filing says.\""), .cross("Did the board vote on the contract soon afterward?", "\"Yes. The vote came within a week of that date, which I noticed at the time.\""), .cross("Did the defendant disclose the donation before the vote?", "\"No. The disclosure came afterward. I know that is a problem for the defense.\""), .cross("Did you see anyone hand the defendant money?", "\"No. I was not in the parking lot. I know the filing only.\""), .cross("Was the filing complete and on time?", "\"It was filed late and listed only the amount and the donor. Normally we expect it sooner.\"")],
        theory: ("{D} took a bribe.", "A donation."),
        allocution: "\"I took that envelope as a campaign donation, because the owner said it was to support my reelection. I should have asked for a check and not taken cash in a parking lot, and I'll admit that. I never promised that company a contract. I'm sorry for how it looks to the people who trusted me with their schools.\"",
        truths: ("The vote followed within a week.", "A campaign finance filing lists a $9,000 donation from the company dated that week."),
        defendant: [.direct("Was the $9,000 a bribe?", "\"No. It was a campaign donation. The company owner offered to support my reelection, and I took it for that purpose.\""), .direct("Why did you accept it in cash?", "\"It was handed to me in an envelope at a parking lot. I should have asked for a check, and I know that now.\""), .direct("Did you report the donation?", "\"Yes, but late. I filed the paperwork after the vote, and I should have filed it right away.\""), .direct("What was your role on the board and when were you up for election?", "\"I served on the board for eight years, and my reelection was a few months away. Campaign funds were thin, and I was asking for support.\""), .direct("How did the meeting in the lot come about?", "\"The owner called and said the company wanted to help my campaign. We picked a time and place that suited us both, and I picked up the envelope.\""), .direct("How did you vote on the contract?", "\"I voted for the company with the lowest bid and best safety record. I would have voted that way with or without the donation.\""), .cross("You did not get a receipt for $9,000 in cash, did you?", "\"No. I did not get one, and I did not give one. That was careless of me.\""), .cross("The company got the bus contract within a week. How is that a coincidence?", "\"I voted the way I would have voted anyway. The company had the best bid.\""), .cross("The company owner says you said it would help. What did you mean?", "\"I meant it would help my campaign. I did not mean it would help the company's bid.\""), .cross("If it was a legitimate donation, why a cash envelope in a parking lot?", "\"The owner insisted on cash and a quiet place. It was foolish, and I should have said no.\""), .cross("The company got the contract a week later. Do you see how that looks?", "\"I see it clearly. It looks like a purchase. I can only tell you that the contract was won on the bid.\"")],
        openings: ("A parking lot camera shows an envelope passing to {D}, a school board member, with $9,000 in cash inside. Within a week the board voted to award the bus contract to that same company.", "Jurors will hear that the money was a campaign donation, that the company had the best bid, and that {D} filed the paperwork, however late."),
        closings: ("Nine thousand dollars in cash, an envelope in a parking lot, and a contract awarded within a week. Cash for a vote is a bribe, no matter what it is called afterward.", "A campaign donation reported on a filing, from a company with the best bid. Late paperwork is sloppy, but it is not corruption, and the State must prove a deal."),
        timeline: [(-14, "The proposal."), (0, "Noon: the envelope."), (7, "The vote."), (30, "The sting.")],
        identified: "A video.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let lyingWitnessStand = SmallCases.make(
        key: "story.lyingWitnessStand",
        category: .publicOrder,
        headlines: ["Witness Charged With Perjury After Video Contradicts Testimony", "Parking Lot Fight Caught on Tape"],
        law: "perjury",
        threshold: 7,
        spec: "Willfully made a false statement under oath in a judicial proceeding, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} testified on {DATE} that {D.he} saw a defendant throw the first punch. A security video later showed {DL} was in a store across town. {DL} says {D.he} was confused.",
        state: [E(.video, 3, "Store Camera", "{D} shopping across town."), E(.document, 3, "Transcript", "'I saw him throw the first punch.'"), E(.digital, 2, "Phone Location", "{DL}'s phone across town.")],
        defense: [E(.statement, 1, "Confusion", "{DL} says {D.he} confused dates.")],
        role: "Court reporter",
        exam: [.direct("What did {D} testify to in court?", "\"{D} testified under oath that {D.he} saw a defendant throw the first punch. The transcript records that {D.he} said the defendant threw the first punch.\""), .direct("What did the store camera later show?", "\"It shows {DL} shopping in a store across town at the time of the fight. The camera clock and the phone location both put {DL} there.\""), .direct("Where in the store was the camera?", "\"At the customer service desk of a department store across town. The time stamp is on every frame.\""), .direct("What was your role at the trial where the defendant testified?", "\"I was the court reporter, so I recorded every word spoken in the courtroom. {DL} took the oath and sat in the witness chair about 2 p.m.\""), .direct("What exactly did the transcript record?", "\"{D.He} said, 'I saw the defendant throw the first punch.' Defense counsel asked twice whether {D.he} was sure, and {D.he} said yes both times.\""), .direct("How did the video come to light?", "\"A week later, the defense produced store camera footage and phone records putting {DL} across town at the time of the fight.\""), .cross("Isn't it possible the defendant was simply confused about the date?", "\"It is possible. A similar fight occurred a week earlier, and a mix-up of dates could explain some of it.\""), .cross("Did the defendant correct the testimony on the stand?", "\"No. {D.He} did not correct it. I recorded what was said, and nothing changed.\""), .cross("Were you in the courtroom for all of the testimony?", "\"Yes. I recorded every word, and I have the transcript. I cannot judge who was telling the truth.\""), .cross("Did anyone object during the defendant's testimony?", "\"No. No one objected to that answer. It stood as part of the record.\""), .cross("Did the defendant seem to be reading from notes?", "\"No. {D.He} spoke from memory. I could not see any notes on the stand.\"")],
        defenseRole: "Cousin",
        defenseExam: [.direct("Does {D} often mix up dates?", "\"Quite often. {D} has always mixed up days and events, and our family teases about it.\""), .direct("Was the defendant sworn when testifying?", "\"Yes. {DF} took the oath like any other witness. I was in the room.\""), .direct("How did the defendant seem on the stand?", "\"Nervous and unsure. {D.He} wanted to be helpful and seemed to be trying to remember something.\""), .direct("How long have you known the defendant?", "\"All my life. We grew up together, and we see each other at family gatherings every few weeks.\""), .direct("Tell the jury about the defendant's memory for dates.", "\"Poor. {D.He} shows up a day early or a week late to things. Everyone in the family teases about it.\""), .direct("What did the defendant tell you about the fight?", "\"That {D.he} saw a fight and thought it was the one in court. {D.He} was shaken when the video came out.\""), .cross("Did the defendant ask someone what to say?", "\"I heard that a friend gave {DF} some guidance. I do not know what was said.\""), .cross("Was the defendant in the store at the time of the fight?", "\"I only know what the video shows. I was not with {D.him} that day.\""), .cross("Are you related to the defendant?", "\"Yes. We are cousins. I know that matters, and I am telling you what I know.\""), .cross("Has the defendant ever lied to you about something important?", "\"Not to my knowledge. But I cannot say I know every private thing {DF} does.\""), .cross("Did you attend the defendant's testimony?", "\"No. I only heard about it afterward, so I cannot tell you how {D.he} acted on the stand beyond what {D.he} told me.\"")],
        theory: ("{D} lied under oath.", "Confusion."),
        allocution: "\"I believed I saw that punch, and I said what I remembered. I mixed up the dates because a similar fight happened a week earlier, and I never meant to mislead anyone. I'm sorry that my mistake was heard in court. I'll be much more careful about what I say under oath.\"",
        truths: ("{DL} had asked a friend what to say.", "A similar fight occurred a week earlier."),
        defendant: [.direct("Did you see the first punch?", "\"I thought I did. I believed I had seen it, and I said what I remembered.\""), .direct("Why was your testimony wrong?", "\"I mixed up the dates. A similar fight happened a week earlier, and I confused the two.\""), .direct("Did anyone tell you what to say?", "\"I asked a friend what to expect. I did not ask the friend to tell me what to say.\""), .direct("What do you remember about the fight you testified about?", "\"I remember hearing about a fight and picturing someone throwing a punch. I mixed it up with another fight I had actually seen a week earlier.\""), .direct("Why did you agree to testify?", "\"A friend of the person involved asked me to help tell what I saw. I wanted to be helpful, and I wanted to do the right thing.\""), .direct("What did you do when you learned of the video?", "\"I panicked and called a friend. I could not understand how I was across town, and then I realized I had mixed up days.\""), .cross("The video shows you in a store across town, doesn't it?", "\"Yes. I was in a store. I know the video looks bad for me.\""), .cross("You swore under oath to something that was not true, didn't you?", "\"I swore to what I believed. I was wrong, and I am sorry for that.\""), .cross("Your phone was across town too, wasn't it?", "\"Yes. I was not at the fight. I realize I should not have testified.\""), .cross("You looked at a courtroom and swore that you saw a punch. What did you actually see?", "\"I did not see it. I believed I had because the earlier fight was so vivid in my memory.\""), .cross("You asked a friend what to say before you testified. What did the friend tell you?", "\"The friend said to tell what I remembered. I do not recall specifics, but I know I leaned on that advice.\"")],
        openings: ("{D} testified under oath that {D.he} saw a defendant throw the first punch in a fight. A store camera and {D.his} own phone later put {D.him} across town at that very time.", "The defense evidence will establish that {D} confused two similar fights a week apart and honestly believed the testimony. A mix-up is not perjury."),
        closings: ("A sworn statement, a store camera across town, and a phone that agrees with the camera. {D} said under oath that {D.he} saw something that {D.he} could not have seen.", "{D} mixed up dates, as {D.his} family says {D.he} often does. The State must prove {DL} knew the testimony was false, and confusion is not the same."),
        timeline: [(-7, "An earlier fight."), (0, "2 p.m.: testimony."), (0, "Week after: the video."), (30, "{DL} is charged.")],
        identified: "A video.",
        mood: .divided,
        doctrines: ["mistakeOfFact"])

    static let hiddenGunFriend = SmallCases.make(
        key: "story.hiddenGunFriend",
        category: .publicOrder,
        headlines: ["Man Hid Friend's Gun Before Deputies Arrived", "Weapon Found in Washing Machine"],
        law: "obstruction",
        threshold: 6,
        spec: "Willfully obstructed justice by concealing evidence, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After a shooting on {DATE}, {D} hid the shooter's pistol in a washing machine before deputies arrived. {DL} says the pistol was {D.his} own. {DL} arrived at about 8:10 p.m., ten minutes after the shooting, and a doorbell camera shows {DL} carrying a bag inside. Deputies searched at 9 p.m. and found the pistol in a washing machine.",
        state: [E(.physical, 3, "Pistol", "Recovered from a washing machine.", .search), E(.video, 3, "Doorbell Camera", "{D} carries a bag inside."), E(.statement, 2, "Deputy", "'He told me it was his.'")],
        defense: [E(.statement, 1, "Own Gun", "{DL} says the pistol was {D.his}.")],
        role: "Deputy",
        exam: [.direct("What happened after the shooting on {DATE}?", "\"A shooting happened at about 8 p.m. About ten minutes later, {D} arrived, and the doorbell camera shows {DL} carrying a bag inside.\""), .direct("What did you find when you searched?", "\"At 9 p.m., we found a pistol in a washing machine. It had been hidden there.\""), .direct("What did {DL} tell you?", "\"{D.He} told me the pistol was {D.his} own. I wrote that down. {D.He} said it was there for safekeeping.\""), .direct("What did you learn about the shooting itself?", "\"Shots were fired at about 8 p.m. A person was wounded, and the shooter ran before deputies arrived. We recovered a shell casing at the scene.\""), .direct("What did the doorbell camera show about {D}?", "\"At about 8:20, {D.he} walked up carrying a bag, went into the house, and came out empty handed after a few minutes.\""), .direct("Who conducted the search with you?", "\"My partner and I did it, and the occupants waited outside with another officer the whole time.\""), .cross("Does {DL} own a pistol?", "\"I understand {DL} owns one. I couldn't confirm that it was the one in the washing machine at the time.\""), .cross("Did you see {DL} put the pistol in the machine?", "\"No. The camera shows {DL} carrying a bag inside. I didn't see what was in the bag.\""), .cross("Did {DL} cooperate?", "\"Yes. {D.He} answered my questions and didn't try to leave. {D.He} told me where things were.\""), .cross("Did you test the pistol against the shell casing?", "\"Not at the time of the search. I know ballistics work was requested, and I did not see the result myself.\""), .cross("Was the washing machine running when you arrived?", "\"Yes, it was in a cycle. The pistol was inside when we opened it.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Does {DL} own a pistol?", "\"Yes. {D} has had one for a long time, and I've seen it a few times at get-togethers.\""), .direct("Did you know where {DL} kept it?", "\"Usually at home, as far as I know. I don't know exactly where, but {D.he} is careful about it.\""), .direct("Is {DL} a violent person?", "\"No. I've never known {DF} to be violent in all the years we've been neighbors. {DF} is calm and responsible.\""), .direct("How long have you lived near {D}?", "\"Eight years, next door. We talk in the driveway and share tools. I have watched {DF}'s kids and dog.\""), .direct("What do you know about the defendant's pistol?", "\"I have seen it once or twice on {D.his} hip when {D.he} was out in the yard. {D.He} always handled it carefully.\""), .direct("How would you describe the defendant in a stressful situation?", "\"Calm, if anything, but a little jumpy about safety. When something goes wrong, {D.he} wants to make sure everyone is out of harm's way.\""), .cross("Is the pistol registered?", "\"I think so, but I'm not sure. I assume {DF} follows the rules like everyone else around here.\""), .cross("Did you see {DL} at the house that night?", "\"No. I only heard about it afterward from other neighbors. I wasn't involved in any of it.\""), .cross("Were you home the night of the shooting?", "\"Yes, but I heard only the shots from a distance. I did not see {D.him} that night.\""), .cross("Do you know which pistol was found in the washing machine?", "\"No. I only know {D.he} had one. Which one was in the machine is not something I can answer.\""), .cross("Do you know whether the pistol the defendant hid was the one used in the shooting?", "\"No. I was told it was a different pistol. I only know {D.he} owns one and kept it at home.\"")],
        theory: ("{D} hid a gun.", "His own gun."),
        allocution: "\"I went over to check on my friend after I heard what happened, and I brought a bag with some of my things. The pistol in the washing machine is mine, and I put it away to keep it safe. I did not mean to hide any evidence. I'm sorry for the confusion it caused.\"",
        truths: ("The shooting used a different pistol.", "The washing machine was running."),
        defendant: [.direct("Why did you go to the house?", "\"I heard something had happened and I went to check on my friend. I brought a bag with some of my things.\""), .direct("Whose pistol was it?", "\"Mine. I own a pistol. I put it in the washing machine to keep it safe when I heard about the shooting.\""), .direct("Did you hide the shooter's pistol?", "\"No. The pistol I had was my own. I didn't know which gun was used. I wasn't helping anyone hide anything.\""), .direct("How did you hear about the shooting?", "\"A neighbor texted me. I knew my friend lived on that street, so I drove over to be sure my friend was okay.\""), .direct("What was in the bag you carried?", "\"My own pistol and a couple of personal things. I was uneasy and decided to keep the pistol out of sight until things calmed down.\""), .direct("Why the washing machine?", "\"It was the first place I thought of that was out of the way. I did not want it near deputies or children in the house.\""), .cross("You arrived ten minutes after the shooting, didn't you?", "\"Yes. I wasn't there when it happened. I came after I heard.\""), .cross("You put a pistol in a washing machine, didn't you?", "\"Yes. It wasn't a smart thing. I wanted it out of sight and secure.\""), .cross("The deputies found it in less than an hour, didn't they?", "\"Yes. They searched at nine. I told them it was mine.\""), .cross("You hid a gun in a washing machine ten minutes after a shooting. Why should the jury believe it was not the shooter's gun?", "\"Because it was mine. I told the deputy right away. I had nothing to do with the shooting and I did not know which gun was used.\""), .cross("If it was yours, why not just hand it to the deputies when they arrived?", "\"I was scared and not thinking. I know it looks like I was hiding evidence, and I regret that.\"")],
        openings: ("After a shooting, {D} arrived ten minutes later with a bag, and deputies later found a pistol hidden in a washing machine. {DL} told a deputy it was {D.his} own. The State will show the pistol, the doorbell camera, and the deputy's account.", "The defense evidence includes a person who owns a pistol, who stashed it in a washing machine in a panic, and who never hid anyone else's weapon."),
        closings: ("A shooting, a bag carried inside ten minutes later, and a pistol in a washing machine. {D} claimed the pistol, but it was hidden after a shooting.", "{D} owns a pistol and hid it in a panic. The State has not proved it was the shooter's gun or that {D.he} knew."),
        timeline: [(0, "8 p.m.: the shooting."), (0, "8:10 p.m.: {DL} arrives."), (0, "8:20 p.m.: the bag."), (0, "9 p.m.: deputies search.")],
        identified: "A doorbell camera.",
        mood: .divided,
        doctrines: ["searchSeizure"],
        genders: ["D": .male])

    static let restaurantOrderHack = SmallCases.make(
        key: "story.restaurantOrderHack",
        category: .cyber,
        headlines: ["Hacker Locked Restaurant Ordering System and Demanded Payment", "Dinner Rush Halted"],
        law: "extortion",
        threshold: 7,
        spec: "Threatened to continue damage to computers of {V} unless paid $4,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A restaurant's ordering system was locked during the dinner rush on {DATE} with a $4,000 demand. The demand traced to {D}, a former server. {DL} says someone used {D.his} old login.",
        state: [E(.digital, 3, "Demand Message", "Sent from {D}'s account."), E(.digital, 3, "Access Log", "{D}'s old login used at 6 p.m."), E(.document, 2, "Termination Notice", "{D} was fired a month earlier.")],
        defense: [E(.statement, 1, "Old Login", "{DL} says anyone could use the old login.")],
        role: "Restaurant owner",
        exam: [.direct("What happened to your ordering system?", "\"It was locked during the dinner rush, and a message demanded $4,000 to unlock it. We could not take orders for the entire rush.\""), .direct("Where did the demand come from?", "\"The demand message was sent from {D}'s account. {D.He} is a former server who was fired a month earlier.\""), .direct("What does the access log show?", "\"{D.his} old login was used at 6 p.m., right at the start of the dinner rush, to get into the system.\""), .direct("When did the system lock and what did you see?", "\"At about 6 p.m., right as the dinner rush started. Every ticket screen froze and a message on the main screen demanded $4,000 to restore access.\""), .direct("What did you do during the lockout?", "\"We wrote orders by hand and ran tickets to the kitchen. It slowed everything down, and we lost a lot of business that night.\""), .direct("How did you trace the demand message?", "\"I called the system vendor, who traced the message to a user account in {D.his} name. Deputies later confirmed the account and the old login.\""), .cross("Did staff share logins at your restaurant?", "\"Some of them did. I will admit that was loose, and I did not enforce rules on it.\""), .cross("Did you disable {D}'s login after the firing?", "\"No. I forgot to disable it. That is my mistake, and it left the old login active.\""), .cross("Could someone else have used the defendant's old login?", "\"Yes, it is possible. Others knew the shared login, and I cannot rule that out.\""), .cross("Did you ever tell the defendant the old login was active?", "\"No. I forgot about it. After the firing I assumed the account was closed and never went back to check.\""), .cross("How many people knew the defendant's login information?", "\"Several people on the line and in the front. We were casual about passwords, and that was careless of us.\"")],
        defenseRole: "Line cook",
        defenseExam: [.direct("Did staff at the restaurant share logins?", "\"Yes, everyone did. We all used the same shared logins, and that was how the system had always worked.\""), .direct("Who had access to those logins?", "\"Everyone on the line and in the front. I knew the login, and so did most of the servers.\""), .direct("Did {D} ever mention the system after being fired?", "\"No. I never heard from {D} after the firing. I do not know what {D.he} thought about it.\""), .direct("How long have you cooked at the restaurant?", "\"Four years. I work the line during dinner and help set up the tablet that sends tickets to the kitchen.\""), .direct("How did people use the old logins?", "\"We kept a shared sheet taped inside a cabinet. Everyone used whichever login was handy when their own would not work.\""), .direct("What happened when the system locked at 6 p.m.?", "\"The tickets froze, and the owner had to scramble. We spent the night passing paper slips back and forth.\""), .cross("Did you see the defendant use the login on that night?", "\"No. I was in the kitchen and did not see anyone use the system on the front counter.\""), .cross("Do you know who sent the demand?", "\"No. I do not know. I only know that it caused a mess in the kitchen.\""), .cross("Did you like the defendant?", "\"We got along. I am not going to say anything unfair about {D.him}.\""), .cross("Where were you at 6 p.m.?", "\"On the line, a few feet from the printer. I did not touch the system that night.\""), .cross("Do you remember seeing the defendant around the restaurant after the firing?", "\"Not once. I assumed {DF} had moved on.\"")],
        theory: ("{D} extorted a restaurant.", "An old login."),
        allocution: "\"I did not lock that ordering system, and I did not demand any money. I have not used my old login since I was let go, and I don't know who did. I worked there for years, and I know how a dinner rush depends on that system. I'm sorry that the owner lost a night's sales.\"",
        truths: ("The demand used {DL}'s email.", "The owner forgot to disable old logins."),
        defendant: [.direct("Did you lock the ordering system?", "\"No. I did not lock anything. I did not demand any money from anyone.\""), .direct("Did you use your old login?", "\"I never used it after I was fired. I did not try to get into the system.\""), .direct("What about the email on the demand?", "\"It was spoofed. Someone used my email address. I did not send that message.\""), .direct("Why were you fired?", "\"A disagreement over my schedule and a few late arrivals. I was frustrated, but I accepted it and found another job.\""), .direct("Where were you at 6 p.m. on the night of the lockout?", "\"At my new job, serving dinner. I clocked in at five, and my coworkers saw me there.\""), .direct("How do you think someone else got your account?", "\"I never changed my password after I left, and it was something everyone on the line knew. Anyone could have used it.\""), .cross("You were fired a month earlier, weren't you?", "\"Yes. I was upset, but I would not have done something like this.\""), .cross("Your old login was used at 6 p.m. Who else would use it?", "\"Anyone who knew it. Everyone at the restaurant shared those logins.\""), .cross("The demand came from your account, didn't it?", "\"It came from an account with my name. That is not proof that I sent it.\""), .cross("The email on the demand is yours. Why would a stranger use your email?", "\"Someone could have set up a fake address with my name or my old email. I do not know how it was done.\""), .cross("You were angry at the restaurant when you were fired. Isn't that motive?", "\"I was upset, but not enough to attack the place. I had already moved on to other work.\"")],
        openings: ("During a dinner rush, a restaurant's ordering system was locked and a message demanded $4,000. The demand came from the account of {D}, a server fired a month earlier, and {D.his} old login was used at 6 p.m.", "The defense will present evidence that everyone at the restaurant shared logins, that the owner never disabled the old ones, and that {D}'s email could be spoofed."),
        closings: ("A fired server, an old login used at the start of the rush, and a demand sent from {D}'s account. The motive and the means point to {D.him}.", "Shared logins, an owner who never disabled old accounts, and an email that could be spoofed. The State has not proved who typed the demand."),
        timeline: [(-30, "{DL} is fired."), (0, "6 p.m.: the lockout."), (0, "6:20 p.m.: the demand."), (1, "Deputies trace it.")],
        identified: "A demand message.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        impact: "We lost a night's sales on the busiest Friday of the month. The system froze at six, the line grew out the door, and my servers were writing orders on napkins. People left angry, and some of them have not come back. I still pay the staff for hours that earned us nothing.",
        doctrines: ["burdenOfProof"])

    static let churchFireFormer = SmallCases.make(
        key: "story.churchFireFormer",
        category: .violent,
        headlines: ["Church Burned at Night by Former Member, Investigators Say", "Pews Soaked in Accelerant"],
        law: "burningBuildings",
        threshold: 8,
        spec: "Willfully and maliciously burned a church owned by {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A church burned overnight on {DATE}. Investigators found accelerant in the sanctuary. {D}, a former member who lost a leadership vote, was seen leaving. {DL} says {D.he} walked the grounds in grief.",
        state: [E(.forensic, 3, "Fire Report", "Accelerant in the sanctuary."), E(.video, 2, "Neighbor Camera", "{D} leaves at 1 a.m."), E(.statement, 2, "Pastor", "{D} threatened to 'make them pay.'")],
        defense: [E(.statement, 1, "Grief", "{DL} says {D.he} walked the grounds in grief.")],
        role: "Fire marshal",
        exam: [.direct("What did your investigation find at the church?", "\"The church burned overnight. I found accelerant in the sanctuary. That's where the fire started and spread.\""), .direct("What does the neighbor's camera show?", "\"It shows {D} leaving at 1 a.m. It shows {DL} walking away from the church grounds.\""), .direct("What did the pastor tell you?", "\"That {DL}, a former member who lost a leadership vote, had threatened to 'make them pay.'\""), .direct("How was the church found burning, and when?", "\"A passerby called at about 2 a.m. and crews arrived by 3. The sanctuary was fully involved, and the roof collapsed an hour later.\""), .direct("How did you determine the cause?", "\"Burn patterns showed multiple points of origin in the sanctuary, and a lab confirmed ignitable liquid in the debris. We ruled out the electrical panel.\""), .direct("What did you learn about {D}'s history with the church?", "\"{D.He} was a longtime member who ran for a leadership seat and lost the vote a few weeks earlier. The pastor reported that {D.he} was bitter about it.\""), .cross("Did anyone see {DL} start the fire?", "\"No. No one saw {DL} enter the building or light anything. I have a camera of {DL} leaving.\""), .cross("{DL} says {D.he} walked the grounds in grief, doesn't {D.he}?", "\"I can't say it's not true. {D.He} was a longtime member, and I know the vote hurt.\""), .cross("Was {DL} carrying anything?", "\"I can't tell from the camera. It's too far and too dark for that.\""), .cross("Did you recover a gas can or container at the church?", "\"No container was recovered at the scene. I do not have a physical item that ties the liquid to a purchase.\""), .cross("How many people lost a vote or a post in that church election?", "\"Several people ran for different seats. I do not know how many were disappointed.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Did you see {DL} that night?", "\"Yes. I saw {D} walking near the church. {DF} was just walking, slowly, like someone lost in thought.\""), .direct("What time was that?", "\"Around one in the morning. I was up and looked out my window. {D.He} walked along the grounds.\""), .direct("How did {DL} seem?", "\"Sad. Not angry. {D.He} stood by the fence for a while and then walked off.\""), .direct("How close do you live to the church?", "\"Across the street. My living room window looks right at the parking lot and the side fence.\""), .direct("How well do you know {D}?", "\"Mostly by sight. We wave at each other and I have spoken to {D.him} after services. {D.He} seemed gentle.\""), .direct("What would you want the court to know about the defendant?", "\"{D.He} is a quiet neighbor, and what I saw that night was someone troubled, not someone dangerous.\""), .cross("Was {DL} carrying anything?", "\"Not that I saw. I couldn't see well. I saw {DF} walking, with nothing obvious in hand.\""), .cross("Could {DL} have gone into the church?", "\"I didn't see that. I only saw the walk. I can't say what happened out of my view.\""), .cross("Did you see the fire start?", "\"No. I went back to bed. I heard sirens later.\""), .cross("Did you watch the defendant the whole time?", "\"No. I looked at the window for a minute or two and then went back to my chair.\""), .cross("Could the defendant have come back later?", "\"I suppose so. I went to bed and did not look out again until the sirens.\"")],
        theory: ("{D} burned a church.", "A grieving walk."),
        allocution: "\"I lost the vote, and I felt like I had lost my church, so I walked the grounds that night to think and to pray. I would never burn a church, least of all one I loved for so many years. I'm grieving the building, too. I'm sorry for everyone who has lost their place of worship, and I hope the court will believe that.\"",
        truths: ("{DL} bought a gas can that week.", "The can was used for a mower."),
        defendant: [.direct("Why were you at the church at night?", "\"I was grieving. I lost the vote, and I felt like I'd lost my church. I walked the grounds to think and to pray.\""), .direct("Did you set the fire?", "\"No. I'd never burn a church, least of all one I loved. I walked the grounds and left.\""), .direct("What did you mean by 'make them pay'?", "\"I was angry and I said something I shouldn't have. I didn't mean fire. It was only words.\""), .direct("What did the church mean to you?", "\"I was baptized there and served on committees for decades. My family has been going for three generations.\""), .direct("Tell us about your walk that night.", "\"I could not sleep after the vote, so I walked to the church grounds around one. I stood by the fence and walked the lot for a while, then went home.\""), .direct("How did you learn about the fire?", "\"A neighbor called me in the morning. I was devastated and drove over to see it. I told the deputies where I had been.\""), .cross("You lost the leadership vote, didn't you?", "\"Yes. It hurt a lot. But I never wanted harm to anyone.\""), .cross("You left at 1 a.m., didn't you?", "\"Yes. I walked home. The fire must have started later.\""), .cross("Accelerant was found in the sanctuary, wasn't it?", "\"That's what I'm told. It wasn't me. I wasn't in the sanctuary.\""), .cross("You said they would pay. Why wouldn't a jury hear that as a threat?", "\"I said it in anger when I lost. It was bitterness, and I regret the words. I would never set fire to the church.\""), .cross("Your walk was at 1 a.m. and the fire was at 2 a.m. Were you really home by then?", "\"Yes. I walked home and fell asleep. Nobody can vouch for me, and I understand why that sounds weak.\"")],
        openings: ("A church burned overnight, with accelerant in the sanctuary. {D}, a former member who had lost a leadership vote, had threatened to 'make them pay' and was filmed leaving at 1 a.m. The State will present the fire marshal and the pastor.", "The defense will present a grieving longtime member who walked the grounds in sorrow, was seen by a neighbor carrying nothing, and had no part in a fire."),
        closings: ("Accelerant in the sanctuary, a threat to make them pay, and {D} on camera leaving at 1 a.m. {D.He} had the motive and the opportunity.", "A walk in grief, nothing in {D}'s hands, and a neighbor who saw it. The State has a threat and a camera, but not proof that {D.he} set the fire."),
        timeline: [(-14, "The vote."), (0, "1 a.m.: {DL} walks."), (0, "2 a.m.: the fire."), (0, "3 a.m.: crews arrive.")],
        identified: "A camera.",
        mood: .divided,
        impact: "Our home of worship is gone. The sanctuary where we married, baptized our children, and buried our parents burned down in one night. Members stood in the parking lot the next morning and wept. We are meeting in a borrowed fellowship hall now, and no one knows if we can rebuild.",
        doctrines: ["burdenOfProof"])

    static let tireSparePills = SmallCases.make(
        key: "story.tireSparePills",
        category: .drugs,
        headlines: ["Traffic Stop Finds Fentanyl Pills Packed in Spare Tire", "K-9 Alerts on Trunk"],
        law: "traffickingOpioid",
        threshold: 8,
        spec: "Trafficked in opium or opioids by possession of 4 grams or more, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A trooper stopped {D} on {DATE} and a K-9 alerted. A spare tire held 3,000 fentanyl pills. {DL} says {D.he} borrowed the car for a job.",
        state: [E(.forensic, 3, "Lab Report", "3,000 fentanyl pills."), E(.physical, 3, "Spare Tire", "Pills packed inside.", .search), E(.digital, 2, "Phone Messages", "'Almost there.'")],
        defense: [E(.statement, 1, "Borrowed", "{DL} says the car was borrowed.")],
        role: "Highway Patrol trooper",
        exam: [.direct("Why did you stop {D}?", "\"I stopped {D} on the highway, and my K-9 alerted on the car. A search found pills packed inside the spare tire.\""), .direct("What was in the spare tire?", "\"The lab report counts 3,000 fentanyl pills. They were packed tightly inside the tire.\""), .direct("What did you find on the defendant's phone?", "\"A message that said 'Almost there.' I also found $4,000 in cash in {D.his} possession.\""), .direct("Why did you pull the defendant over, and where?", "\"I clocked the car at about 1 p.m. on the interstate for following too closely and a loose license plate frame. I stopped it on the shoulder near a mile marker.\""), .direct("What happened when your K-9 arrived?", "\"At about 1:15 the dog circled the car and alerted at the rear. I told {DL} we would search, and {DL} agreed without argument.\""), .direct("How were the pills hidden?", "\"In the spare tire, which was mounted under the cargo floor. Several vacuum-sealed bags were packed around the rim, and the lab counted 3,000 pills.\""), .cross("The car belonged to someone else, didn't it?", "\"Yes. The car was borrowed, and the owner confirmed lending it. I agree with that.\""), .cross("Did the defendant seem nervous?", "\"{D.He} was calm and cooperative. {D.He} agreed to the search and answered my questions.\""), .cross("Could the pills have been in the tire before the defendant borrowed the car?", "\"It is possible. I cannot say when they were placed in the tire.\""), .cross("Did the defendant give you consent to search?", "\"Yes. {D.He} signed the consent form at the scene and watched while we searched.\""), .cross("Did the registered owner give you a statement?", "\"Yes, by phone. The owner said the car had been lent to {DL} for a few days and that nothing was said about the spare tire.\"")],
        defenseRole: "Car owner",
        defenseExam: [.direct("Did you lend your car to {D}?", "\"Yes. I lent it for a few days so {D} could do a job. I trusted {D.him}.\""), .direct("Did you know there were pills in the spare tire?", "\"No. I had no idea. I would never have lent the car if I had known.\""), .direct("When did you last check the spare tire?", "\"Months ago, when I got the car. I did not look at it since then.\""), .direct("How do you know the defendant?", "\"{DF} and I go back many years and have helped each other move and build things, and we lend each other what we need.\""), .direct("How long did the defendant keep your car?", "\"Four days. {D.He} brought it back on Sunday with a full tank.\""), .direct("What do you use the spare tire for?", "\"Nothing. I never had a flat. I last looked at it when I bought the car, and I did not have any reason to look since.\""), .cross("Did the defendant offer to pay you for the car?", "\"No. {D.He} did not pay anything. It was a favor.\""), .cross("Do you know what job the defendant was doing?", "\"Only that it was a job in another town. I did not ask for details.\""), .cross("Who else has driven the car recently?", "\"A couple of people. A friend borrowed it once a few weeks earlier, and I did not ask what the friend carried.\""), .cross("Did you ever check that the spare was the original one?", "\"No. I assumed it was. I never took it out.\""), .cross("Did you ever tell the defendant not to touch the spare tire?", "\"No. I never thought about it. I lent the car for a day, and I did not check what was in the trunk before handing over the keys.\"")],
        theory: ("{D} trafficked fentanyl.", "A borrowed car."),
        allocution: "\"I borrowed that car for a job, and I had no idea anything was inside the spare tire. The cash was for paying a crew and buying materials. I know how it looks, but I have never been in this kind of trouble. I'm sorry for the worry this has put on my family, and I'd ask the court to see I was just working.\"",
        truths: ("{DL} had $4,000 in cash.", "The friend confirmed the loan."),
        defendant: [.direct("Were the pills yours?", "\"No. I did not know they were in the spare tire. I borrowed the car for a job.\""), .direct("Why did you have $4,000 in cash?", "\"It was to pay for a job. I was going to pay a crew and buy materials.\""), .direct("What did your 'Almost there' message mean?", "\"I was meeting someone about the job. It was about a meeting, nothing more.\""), .direct("What was the job you were driving to?", "\"A remodeling job in another county. I was bringing cash for a crew and supplies, and I borrowed a friend's car because my own was in the shop.\""), .direct("How did the stop go from your side?", "\"The trooper said I was following too close, and then asked to search. I agreed because I had nothing to hide and I figured it would end quickly.\""), .direct("What was your reaction when the pills were found?", "\"Shock. I told the trooper I had no idea and that the car belonged to a friend. I gave my friend's number right then.\""), .cross("3,000 fentanyl pills in a car you were driving, and you knew nothing?", "\"I knew nothing. The car was borrowed, and I did not look in the tire.\""), .cross("$4,000 in cash and a message saying 'Almost there.' Isn't that a delivery?", "\"No. It was a work trip. I know how it sounds.\""), .cross("Can the friend confirm the loan?", "\"Yes. The friend has confirmed lending me the car.\""), .cross("'Almost there' and $4,000 in a borrowed car. Doesn't that look like a drug delivery?", "\"I understand why you would say that. It was a crew payment and a text to the foreman. I had no pills and no idea about the tire.\""), .cross("Have you been in that tire or in that trunk before?", "\"No. I put my bag in the back seat. I never opened the cargo floor.\"")],
        openings: ("A trooper stopped {D} on the highway, a K-9 alerted, and a search of the spare tire found 3,000 fentanyl pills. {D.He} also carried $4,000 in cash and a message that said 'Almost there.'", "Listen for the defense evidence, which will show that {D} borrowed the car for a job, that the owner confirmed the loan, and that {DL} never knew what was in the tire."),
        closings: ("Three thousand fentanyl pills hidden in a spare tire, $4,000 in cash, and a message saying 'Almost there.' The driver of a car answers for what it carries.", "A borrowed car, a spare tire no driver checks, and an owner who confirms the loan. The State must prove {D} knew the pills were there."),
        timeline: [(0, "1 p.m.: the stop."), (0, "1:15 p.m.: the K-9."), (0, "1:40 p.m.: the search."), (0, "2 p.m.: arrest.")],
        identified: "A search.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure", "mistakeOfFact"])

    static let pawnStrawBuy = SmallCases.make(
        key: "story.pawnStrawBuy",
        category: .violent,
        headlines: ["Woman Bought Guns for Felon Boyfriend at Pawn Shop", "Texts List Models Wanted"],
        law: "felonFirearm",
        threshold: 8,
        spec: "Aided a person with a felony conviction in possessing a firearm, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} bought three handguns at a pawn shop on {DATE}. Texts showed {D.his} boyfriend, a felon, picking the models. {DL} says they were gifts.",
        state: [E(.digital, 3, "Text Messages", "The boyfriend lists models."), E(.document, 3, "Pawn Records", "{D} purchased three guns."), E(.statement, 2, "Pawn Clerk", "The boyfriend waited outside.")],
        defense: [E(.statement, 1, "Gifts", "{DL} says the guns were gifts.")],
        role: "Pawn shop clerk",
        exam: [.direct("What did {D} buy at your shop?", "\"Three handguns on that day. Our pawn records show {D} purchased all three and passed the background check.\""), .direct("What did the text messages show?", "\"{D.his} partner, who is a felon, listing the models to buy. The texts spell out which guns to get.\""), .direct("Where was the partner during the purchase?", "\"Waiting outside. {DL}'s partner did not come in, and I never spoke with that person.\""), .direct("Walk the jury through the purchase.", "\"{D.He} came in at about noon, picked out three handguns, filled out the federal form, and passed the instant background check. I rang up the sale.\""), .direct("What did you notice about the person waiting outside?", "\"A person stood by a truck near the front window and looked in several times. I could see them through the glass but never spoke with them.\""), .direct("What do the pawn records include?", "\"The serial numbers of all three guns, the purchase date, the form, the check approval number, and the debit card receipt.\""), .cross("{D} says they were gifts, doesn't {D.he}?", "\"Yes. {D.He} told me that. It is not unusual for a person to buy a gift.\""), .cross("Did {D} pay with {D}'s own debit card?", "\"Yes, a receipt shows {DL} paid by debit card. The money came from {DL}'s account.\""), .cross("Was the defendant qualified to buy guns?", "\"Yes. {D.He} cleared the background check and had no record that would bar the purchase.\""), .cross("Did the defendant ask you to hold anything or hide anything?", "\"No. {DL} bought the guns openly and left with them in the box. There was no odd request.\""), .cross("Did the defendant say anything about who the guns were for?", "\"{DL} mentioned something about presents for people. I did not press, because it is not unusual.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("Does {D} shoot as a hobby?", "\"Often. {D} goes to the range regularly, and I have been with {DF} several times.\""), .direct("Does the defendant own guns?", "\"Two that I know of. {DF} bought them years ago for target shooting.\""), .direct("Did the defendant ever talk about buying guns for someone else?", "\"No. I never heard {D.him} say that. {D.He} talked about gifts for family.\""), .direct("How often do you see the defendant?", "\"A couple of times a month. We shoot at the same range, and I have eaten dinner at {D.his} place.\""), .direct("What do you know about the guns the defendant owns?", "\"Two handguns that {DF} bought for the range. {DF} keeps them in a locked case and is careful when handling them.\""), .direct("Did the defendant ever mention gifts?", "\"Yes. {D.He} talked about wanting to give something to family and friends who like the range. I did not hear any details.\""), .cross("Did you know the defendant's partner?", "\"I have met them. I know about a felony, but I do not know the details.\""), .cross("Did the defendant mention buying three guns at once?", "\"No. I was not told about that. I only heard about it later.\""), .cross("Have you seen the guns that the defendant bought that day?", "\"No. I never saw them. I do not know where they ended up.\""), .cross("Were you with the defendant on the day of the purchase?", "\"No. I was working and did not hear about it until later.\""), .cross("You have never seen the defendant's partner at the range, have you?", "\"No. I have only ever seen {DF} there, and I never saw any partner shoot or even hold a gun.\"")],
        theory: ("{D} bought guns for a felon.", "Gifts."),
        allocution: "\"Those guns were meant as gifts, one for me and others for friends who share my hobby. I never meant to help anyone who wasn't allowed to have them. I'm sorry that the purchases looked the way they did, and I regret that I didn't think harder about where they ended up. I'll be far more careful.\"",
        truths: ("The guns were found at the boyfriend's home.", "A receipt shows {DL} paid by debit card."),
        defendant: [.direct("Why did you buy three guns?", "\"They were gifts. I wanted to give them to people I care about.\""), .direct("Who were they for?", "\"For me, and for friends. I wanted to share my hobby with them.\""), .direct("Why were the guns found at your partner's home?", "\"I was visiting. I took them with me, and I left them there when I left.\""), .direct("Tell us about your interest in firearms.", "\"I have been target shooting for years and I enjoy it. I own a couple of guns and go to the range most weekends.\""), .direct("How did you choose those three guns?", "\"I liked the price and the models. My partner had mentioned some brands we both liked, and I read their messages and made my own list.\""), .direct("How long had you owned the guns?", "\"Only a few days. I'd just bought them, and I hadn't found a safe place for them yet.\""), .cross("The text messages show your partner picking the models, don't they?", "\"Yes. My partner likes guns, and we talked about them. That does not mean they were for my partner.\""), .cross("You paid with your debit card. Whose money was it?", "\"Mine. I paid with my own debit card for what I bought.\""), .cross("A felon cannot own guns. Did you know that?", "\"Yes. I know that. I would never give a gun to a felon.\""), .cross("Your partner texted you a list of models. How is that not an order?", "\"It was a conversation about what we both liked. I did the buying and the paying, and nothing was demanded of me.\""), .cross("You knew your partner could not lawfully have a gun. Why leave three there?", "\"I did not think it through. I never intended my partner to use them, and I should have kept them at my house.\"")],
        openings: ("{D} bought three handguns at a pawn shop. Text messages show {D.his} partner, a felon, picking the models, and the guns were later found at the partner's home.", "The defense case is that {D} paid with {DL}'s own debit card and bought gifts for family and friends, not guns for a prohibited person."),
        closings: ("A felon picked the models, {D} bought the guns, and they ended up at the felon's home. That is a straw purchase.", "{D} cleared a background check, paid with a personal debit card, and bought gifts. The State must prove {DL} bought them for someone who could not."),
        timeline: [(-7, "The texts."), (0, "Noon: the buy."), (1, "Search at his home."), (1, "{DL} is charged.")],
        identified: "Pawn records.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let forgedDeedLot = SmallCases.make(
        key: "story.forgedDeedLot",
        category: .whiteCollar,
        headlines: ["Man Forged Deed to Sell Neighbor's Vacant Lot", "Notary Stamp Was Fake"],
        law: "forgery",
        threshold: 8,
        spec: "Forged a deed of {V} with intent to defraud, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} recorded a deed on {DATE} transferring {V}'s vacant lot and sold it for $38,000. The notary stamp was fake and {V}'s signature did not match. {DL} says a lawyer prepared it.",
        state: [E(.document, 3, "Deed", "A forged signature and notary stamp."), E(.document, 3, "Sale Record", "{D} received $38,000."), E(.forensic, 2, "Handwriting Report", "Not {V}'s signature.")],
        defense: [E(.statement, 1, "Lawyer", "{DL} says a lawyer prepared it.")],
        role: "Register of deeds clerk",
        exam: [.direct("What did you receive in your office on {DATE}?", "\"A deed transferring {V}'s vacant lot. {D} recorded it. I processed it as a normal recording.\""), .direct("What was wrong with it?", "\"The signature was forged, and the notary stamp was fake. Later, a handwriting report found it was not {V}'s signature.\""), .direct("What happened to the lot?", "\"It was sold for $38,000. The sale record shows {DL} received the $38,000.\""), .direct("What did you do when {D} handed you the deed?", "\"I checked the form, the notary block, and the fees, scanned it, and recorded it in the county index. It looked like a normal conveyance of a vacant lot.\""), .direct("How did the problem come to light?", "\"{V} came into the office a few months later and said the lot was no longer theirs. We pulled the deed and compared the signatures.\""), .direct("What did the handwriting report say?", "\"It said the signature on the deed was not {V}'s. A second examiner agreed, and the notary seal number belonged to nobody in our county.\""), .cross("{DL} says a lawyer prepared the deed, doesn't {D.he}?", "\"I can't say who prepared it. I only know who brought it in.\""), .cross("Did you check the notary stamp?", "\"We look at the face of the deed. It looked normal. We can't verify each notary stamp when it's recorded.\""), .cross("Did {DL} act suspicious at your counter?", "\"No. {D.He} was polite and ordinary. I have no recollection of anything odd.\""), .cross("Does your office verify signatures on a deed?", "\"No. We check form and fees, not identity. It is the job of the notary and the closing attorney.\""), .cross("Did you ask the defendant any questions at the counter?", "\"Only the standard ones about the parcel number and who wanted copies. {DL} answered them without a problem.\"")],
        defenseRole: "Closing agent",
        defenseExam: [.direct("Did you close the sale of {V}'s lot?", "\"Yes. I was the closing agent. {D} brought the deed and the sale went through.\""), .direct("Who brought the deed?", "\"{DF} presented it and the paperwork. It looked in order.\""), .direct("What did you check?", "\"I checked ID. {D.He} had a real ID, and the names lined up.\""), .direct("What does a closing agent do on a sale like this?", "\"I confirm the parties, review the deed and the payoff, collect fees, and pay out the proceeds. I do not draft the documents.\""), .direct("How did the closing go?", "\"Smoothly. {DF} brought the paperwork, showed a driver's license, and signed the seller's papers. The buyer funded the sale, and we disbursed $38,000.\""), .direct("Did anything look unusual to you?", "\"Not at the time. The deed had a notary block and a stamp, and the transfer was recorded. Nothing jumped out.\""), .cross("Did you check the notary?", "\"Not individually. I relied on the stamp being there. I assumed it was valid.\""), .cross("Did you check {V}'s signature?", "\"No. I didn't have a sample. I relied on what was presented.\""), .cross("Did {DL} tell you who prepared the deed?", "\"A lawyer, I believe. I didn't follow up on it.\""), .cross("Did you ever speak with the real owner of the lot?", "\"No. I never spoke with {V}. We relied on the deed and {DF}'s ID.\""), .cross("You did not call the county register of deeds before closing, did you?", "\"No. We closed on the paperwork we were given, and I never called the register.\"")],
        theory: ("{D} forged a deed.", "A lawyer."),
        allocution: "\"A lawyer gave me that deed and told me it was a valid transfer, and I took it to the register of deeds in good faith. I never saw {V} sign anything, and I would never forge a name. I'm sorry for the family who lost the lot and for the trouble in sorting it out. I trusted the wrong person.\"",
        truths: ("{DL} owed back taxes.", "The lawyer's number reached a real office."),
        defendant: [.direct("Where did the deed come from?", "\"A lawyer prepared it. I was told it was a valid transfer. I took it to the register of deeds.\""), .direct("Did you forge {V}'s signature?", "\"No. I did not. I never saw {V} sign. I trusted the lawyer and the paperwork.\""), .direct("What did you do with the $38,000?", "\"I received it from the sale. I thought I was entitled to it. I didn't know the deed was forged.\""), .direct("How did you come to sell a vacant lot?", "\"A person called and said the lot was available. I understood a lawyer would prepare the deed and I would be paid after it sold.\""), .direct("What did the lawyer tell you?", "\"That everything was in order and that I only needed to carry the deed to the register's office. I never met the lawyer in person.\""), .direct("What did you do with the sale proceeds?", "\"I paid some bills with it and put the rest in an account. I thought it was mine because the paperwork said so.\""), .cross("You recorded the deed yourself, didn't you?", "\"Yes. I brought it in. I thought everything was in order.\""), .cross("You received $38,000, didn't you?", "\"Yes. I did. I'm sorry now. I was told the lot was mine to sell.\""), .cross("You can't name the lawyer, can you?", "\"I know the name I was given, but it didn't check out. I realize that makes it look bad.\""), .cross("You never checked that the lawyer was real. Why?", "\"I took it on trust. The number I was given rang through to an office, and I did not push further.\""), .cross("You owed back taxes at the time. Isn't that why the money mattered?", "\"I did owe taxes. I would not say that is why I did this. I thought the sale was legitimate.\"")],
        openings: ("{D} recorded a deed transferring {V}'s vacant lot and sold it for $38,000. The notary stamp was fake, and a handwriting report says the signature is not {V}'s. The State will show the deed and the sale record.", "The defense will point you to a person who brought paperwork prepared, {D} says, by a lawyer, and who used a real ID at every step. A forger does not stand in the open."),
        closings: ("A forged signature, a fake notary stamp, and $38,000 paid to {D}. {D.He} walked the forged deed in and walked the money out, and {V} lost a lot.", "{D} used a real ID at every step and believed a lawyer had prepared the deed. The State has not proved {DL} knew the signature was forged or the stamp was fake."),
        timeline: [(-30, "The lot is listed."), (0, "The deed is recorded."), (14, "The sale closes."), (60, "{V} finds out.")],
        identified: "A deed and a stamp.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "It was my late father's lot, the one {V.he} bought when {V.he} was just starting out, and {V.he} planned to leave it to my children. I found out it had been sold when a stranger called me about it. Someone forged a signature on {V.his} own land, and I'm still fighting to get it back.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let cafeBurnedForInsurance = SmallCases.make(
        key: "story.cafeBurnedForInsurance",
        category: .whiteCollar,
        headlines: ["Cafe Owner Burned Own Restaurant for Insurance, Investigators Say", "Grease Fire Theory Rejected"],
        law: "insuranceFraud",
        threshold: 8,
        spec: "Presented a false claim to an insurer after willfully burning an insured building, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A cafe burned overnight on {DATE}. {D}, the owner, filed a $210,000 claim. Investigators found two ignition points and removed equipment. {DL} says it was a grease fire.",
        state: [E(.forensic, 3, "Fire Report", "Two ignition points."), E(.document, 3, "Financial Records", "Cafe was $90,000 in debt."), E(.video, 2, "Street Camera", "{D} leaves at midnight.")],
        defense: [E(.statement, 1, "Grease", "{DL} says it was a grease fire.")],
        role: "Fire marshal",
        exam: [.direct("What did you find at the cafe on {DATE}?", "\"The cafe burned overnight. I found two separate ignition points, and equipment had been removed before the fire.\""), .direct("What do the financial records show?", "\"The cafe was $90,000 in debt. {D}, the owner, then filed a $210,000 insurance claim.\""), .direct("What does the street camera show?", "\"It shows {DL} leaving at midnight. The fire was discovered after that.\""), .direct("How did you determine there were two ignition points?", "\"Charring and burn patterns started in the kitchen near the fryer and again in the storage room by the back door. They were forty feet apart with no connection.\""), .direct("What did you find about equipment?", "\"An espresso machine, a commercial mixer, and a walk-in cooler unit were missing, with clean outlines on the floor showing where they had stood.\""), .direct("What did the claim include?", "\"The owner filed $210,000 for building contents, equipment, and lost income, which was more than twice the cafe's outstanding debts.\""), .cross("{DL} says it was a grease fire, doesn't {D.he}?", "\"Grease fires happen. But a grease fire doesn't usually start in two places.\""), .cross("Did anyone see {DL} start the fire?", "\"No. No one saw {D.him} do anything. {D.He} was on camera leaving. It's a circumstantial case.\""), .cross("Was the equipment removed by {DL}?", "\"I can say equipment was gone. I can't say who removed it or when with certainty.\""), .cross("Did you find an ignitable liquid?", "\"The lab found traces consistent with a petroleum distillate in the storage room. I cannot say whether it came from a spill or a cleaner.\""), .cross("How would a grease fire start in two places?", "\"It would require grease build-up near two heat sources, and a spread through ducts. That can happen, but it is unusual.\"")],
        defenseRole: "Fire inspector",
        defenseExam: [.direct("Did you inspect {DL}'s cafe?", "\"Yes, over the years. I'm a fire inspector, and I've been in that kitchen several times.\""), .direct("Was there grease build-up?", "\"Yes. It was a busy kitchen, and grease was a concern. It's common in restaurants.\""), .direct("What did your inspection find on code?", "\"The cafe passed the fire code on my last inspection. I'd have flagged anything major.\""), .direct("How long have you inspected restaurants?", "\"Eighteen years. I check hoods, extinguishers, wiring, and grease control, and I write each inspection up in a standard report.\""), .direct("What did you note about this kitchen on your last visit?", "\"Heavy grease on the hood filter and some build-up in the duct. I wrote a notice to clean it and gave a deadline.\""), .direct("Was the deadline met?", "\"I never confirmed it. We did a follow-up call and the owner said a cleaning was scheduled, but I did not verify it.\""), .cross("Could a grease fire start in two places?", "\"It's unusual. A grease fire typically starts in one place and spreads. I wouldn't expect two points.\""), .cross("Did you inspect after the fire?", "\"No. I only inspected before. I can't speak to what the fire marshal found.\""), .cross("Did you check the equipment?", "\"I looked at the major appliances. I don't recall what was there on the last visit.\""), .cross("Did you see the equipment that was removed?", "\"I recall the espresso machine and the mixer from earlier visits. I did not take inventory.\""), .cross("Could grease alone start a second fire elsewhere?", "\"Only if burning debris or smoke traveled in the duct. It is possible, but it would be less typical.\"")],
        theory: ("{D} burned a cafe.", "An accident."),
        allocution: "\"That cafe was my life. I put every dollar and every hour into it, and I would never have burned it down. I believe it was a grease fire, because we had buildup in the kitchen that I'd been meaning to clean. I'm sorry for the loss to my staff, my customers, and my family.\"",
        truths: ("{DL} had raised coverage a month earlier.", "Grease traps were overdue for cleaning."),
        defendant: [.direct("Did you burn your cafe?", "\"No. It was my life. I put everything into it. I'd never burn it down.\""), .direct("What do you think caused the fire?", "\"A grease fire. We had a lot of grease build-up in the kitchen. It was an accident waiting to happen.\""), .direct("Why did you file the claim?", "\"Because my cafe was destroyed. That's what insurance is for. I did what any owner would do.\""), .direct("How long had you owned the cafe?", "\"Six years. I started it after working for others for a long time. I did the cooking, the books, and most of the cleaning.\""), .direct("Why was the cafe in debt?", "\"I took a loan to fix the ventilation and replace appliances, and the numbers did not work out. Business slowed after a road project cut off parking.\""), .direct("Why had you increased the insurance coverage?", "\"My broker suggested raising it after I added equipment. It was not a secret, and the paperwork went through the normal channels.\""), .cross("The cafe was $90,000 in debt, wasn't it?", "\"Yes. Business was hard. But that's not why the fire happened.\""), .cross("Two ignition points were found, weren't there?", "\"That's what they say. I don't know about that. I'm not a fire expert.\""), .cross("You left at midnight, didn't you?", "\"Yes, I closed up and went home. The fire started after.\""), .cross("Equipment disappeared before the fire. Who took it?", "\"I moved some to a friend's garage because I was changing menus and had no space. I did not tell anyone, and I wish I had.\""), .cross("A cafe in debt with raised coverage and two fires. Do you see why people suspect you?", "\"I also see a kitchen full of old grease that I had not been able to afford to clean.\"")],
        openings: ("A cafe burned overnight with two ignition points, after equipment was removed. {D}, the owner, was $90,000 in debt and filed a $210,000 claim. A street camera shows {DL} leaving at midnight. The State will show the report and the finances.", "The defense will present a busy kitchen with a grease problem, an inspector who passed the cafe, and an owner who lost everything in a fire."),
        closings: ("Two ignition points, a $90,000 debt, and a $210,000 claim. {D} had every reason to want the cafe gone, and the fire marshal found it was set.", "A grease fire in a kitchen full of grease. {D} had everything invested in that cafe. The State has not proved the fire was set or that {D.he} set it."),
        timeline: [(-30, "Coverage is raised."), (0, "Midnight: {DL} leaves."), (0, "2 a.m.: the fire."), (7, "The claim.")],
        identified: "A fire report.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let groupHomeWanderFreeze = SmallCases.make(
        key: "story.groupHomeWanderFreeze",
        category: .family,
        headlines: ["Resident Froze After Wandering From Group Home Overnight", "Door Alarm Was Off"],
        law: "patientNeglect",
        threshold: 7,
        spec: "Neglected a disabled adult in {D}'s care, causing serious injury, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a resident with dementia, wandered from a group home on {DATE} and was found frostbitten. The door alarm was off. {D}, the night aide, was asleep. {DL} says the alarm was broken.",
        state: [E(.statement, 3, "Supervisor", "The alarm was working at shift change."), E(.forensic, 3, "Medical Report", "Severe frostbite."), E(.video, 2, "Porch Camera", "{V} leaves at 2 a.m.")],
        defense: [E(.statement, 1, "Broken", "{DL} says the alarm was broken.")],
        role: "Group home supervisor",
        exam: [.direct("What happened to {V} on {DATE}?", "\"{V}, a resident with dementia, wandered from the group home at 2 a.m. and was found frostbitten. The porch camera shows {V} leaving.\""), .direct("What was the status of the door alarm?", "\"It was off when {V} left. At shift change, it was working. It was off during the night shift.\""), .direct("Where was the night aide?", "\"{D}, the night aide, was asleep. That's what I found when I reviewed the shift.\""), .direct("What was the condition of the group home that morning?", "\"Eight residents, all with some memory impairment. The back door was ajar when I arrived at six, and {V}'s bed was empty.\""), .direct("How did you find {V}?", "\"A neighbor spotted {V} sitting by a fence three blocks away at about six in the morning. {V} was wearing only a nightgown and slippers in freezing weather.\""), .direct("What were {V}'s injuries?", "\"Severe frostbite on the fingers and toes, and two toes were later amputated. {V} was hospitalized for several weeks.\""), .cross("{DL} says the alarm was broken, doesn't {D.he}?", "\"I know the alarm has had issues. But at shift change it was working.\""), .cross("Was the alarm ever repaired or logged?", "\"There's a maintenance log of problems. I'd have to review it for the dates. I know there were some problems.\""), .cross("How many aides were on duty?", "\"Just one at night, {DL}. That's the staffing. I know that's thin for a facility like ours.\""), .cross("Who tests the alarm?", "\"The security officer on each shift. The log shows the initials of whoever tested it.\""), .cross("Did {D} have a history of problems on shift?", "\"No. {D.He} had a clean record and good evaluations. This is the first incident I have had with {D.him}.\"")],
        defenseRole: "Maintenance worker",
        defenseExam: [.direct("Do you maintain the group home's alarms?", "\"Yes. I'm the maintenance worker. I check the door alarms when staff reports a problem.\""), .direct("Was the alarm broken?", "\"Intermittent. It worked sometimes and not others. We'd had trouble with it.\""), .direct("Did you log that?", "\"Yes. There's a repair log. I logged it each time it was reported.\""), .direct("How long have you maintained this building?", "\"Five years. I replace bulbs, fix doors, and service the alarm system whenever a staff member reports a problem.\""), .direct("Describe the problem with the door alarm.", "\"It would fail to sound when the door opened, then work normally for days. The maker's service line said it could happen after a power flicker.\""), .direct("Did you replace it?", "\"I ordered a new unit weeks earlier. It had not arrived, and we were making do with the old one.\""), .cross("Was the alarm working at shift change?", "\"I don't know. I wasn't there. I only know the history of problems.\""), .cross("Was it repaired before that night?", "\"I'd have to check the log. I'd say it wasn't fully fixed.\""), .cross("Did {DL} report the alarm?", "\"Not that I recall. I don't have a report from {D} on that night.\""), .cross("Did anyone tell you the alarm failed on the night in question?", "\"No. I learned about it after the fact when the supervisor called me in.\""), .cross("Could a staff member have switched the alarm off by hand?", "\"Yes. There is a keypad, and an aide could turn it off. I do not know whether that happened that night.\"")],
        theory: ("{D} slept on shift.", "A broken alarm."),
        allocution: "\"I was exhausted after a long stretch of shifts, and I may have dozed off that night. The door alarm had been acting up for weeks, and I reported it, but nothing was done. I'm heartbroken that {V} was hurt in the cold. I care for those residents, and I'm sorry I wasn't more alert.\"",
        truths: ("{DL} worked a double.", "The alarm's maker had issued a recall for false-off failures."),
        defendant: [.direct("Why was the alarm off?", "\"It was broken. It had been acting up for weeks. It would go off and then not work. I thought it was malfunctioning.\""), .direct("Were you asleep?", "\"I may have dozed. I'd worked a long stretch and I was exhausted. I didn't know {V} had left.\""), .direct("How has this affected you?", "\"Honestly, I feel terrible. I'd never want anyone hurt. {V} is a sweet person, and I should have been awake.\""), .direct("What was your shift that night?", "\"I came on at ten for the overnight and I had already worked a long day. I was alone with eight residents until the morning shift.\""), .direct("How did the alarm behave on your shifts?", "\"It would chirp, then go silent, then sometimes beep randomly. I reported it more than once, and it never stayed fixed.\""), .direct("What do you remember of the night?", "\"I checked everyone at midnight, and the doors were secure. I sat down to chart and I dozed, and I woke at five to find the door open.\""), .cross("You were the only aide on duty, weren't you?", "\"Yes. I was alone. That's a lot of responsibility.\""), .cross("You fell asleep on duty, didn't you?", "\"Yes. I did. I'm ashamed. I know I should have stayed alert.\""), .cross("{V} was out for hours in the cold, wasn't {V.he}?", "\"I understand so. I'm sorry. I didn't know until I woke up.\""), .cross("You are the only person responsible for the doors overnight. How did you let this happen?", "\"I fell asleep. I do not offer excuses, but I was exhausted and no one could cover me.\""), .cross("If the alarm failed, why did you not stay awake and check the doors every hour?", "\"I know I should have. I trusted the alarm, and I am sorry I did.\"")],
        openings: ("{V}, a resident with dementia, wandered out of a group home at 2 a.m. and was found with severe frostbite. The door alarm was off and the night aide, {D}, was asleep. The State will present the supervisor and the medical report.", "Jurors will also see an alarm that was unreliable, a repair log that proves it, and an overworked aide who had no idea {V} was gone."),
        closings: ("A resident with dementia left in the cold, an alarm that was off, and an aide who was asleep. {D} was responsible for {V}'s safety that night.", "A broken alarm and a single aide on duty. {D} did not know and did not intend harm. The State has not proved the willful neglect the law requires."),
        timeline: [(0, "2 a.m.: {V} leaves."), (0, "6 a.m.: {V} is found."), (0, "6:30 a.m.: medics."), (1, "{DL} is suspended.")],
        identified: "A porch camera.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .divided,
        impact: "{V.He} was never the same after that night. {V.He} was found barely able to walk, with frostbite on {V.his} hands and feet, and the doctors weren't sure {V.he} would keep {V.his} toes. {V.He} is more afraid now and confused about where {V.he} is. We trusted that home to keep {V.him} safe.",
        doctrines: ["burdenOfProof"],
        genders: ["V": .female])

    static let roofingWidowScam = SmallCases.make(
        key: "story.roofingWidowScam",
        category: .whiteCollar,
        headlines: ["Roofing Crew Charged Widow for Repairs Never Needed", "Photos Show Staged Damage"],
        law: "exploitationElder",
        threshold: 8,
        spec: "Exploited an elder adult by deception, obtaining $24,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A widow, {V}, paid $24,000 to {D}'s crew for roof repairs after being shown staged photos of damage. An inspector found a sound roof. {DL} says damage was real.",
        state: [E(.document, 3, "Inspector Report", "Roof sound; no damage."), E(.digital, 3, "Photos", "Photos from another house."), E(.document, 3, "Contract", "$24,000 signed on the spot.")],
        defense: [E(.statement, 1, "Damage", "{DL} says damage was real.")],
        role: "Home inspector",
        exam: [.direct("What did you find when you inspected {V}'s roof?", "\"The roof was sound. I found no hail damage and no storm damage that would require $24,000 in repairs.\""), .direct("What did you learn about the photos?", "\"The photos {V} was shown came from another house. They did not match {V}'s roof or its shingles.\""), .direct("How was the contract signed?", "\"$24,000 signed on the spot, on the same day. {V} was pressured to sign right then.\""), .direct("How was the inspection arranged?", "\"The homeowner's family grew suspicious and hired me after the repairs were done. I went up on the roof with a ladder, a camera, and a moisture meter.\""), .direct("What did you see on the roof?", "\"Intact shingles with no hail dents, normal granule wear, and no signs of recent replacement. The roof was about ten years old and sound.\""), .direct("What did {V} say about the sales visit?", "\"{V} said two workers knocked on the door, showed pictures of damaged shingles, and pressed for a signature before leaving. {V} did not feel there was time to think.\""), .cross("A hail storm hit the county that year, didn't it?", "\"Yes, there was hail that year. Many roofs in the county had real damage.\""), .cross("Could {V}'s roof have had minor hail damage?", "\"I found none. I looked carefully, and the shingles were intact.\""), .cross("Photos get mixed up sometimes, don't they?", "\"They can. But photos from another house in a sales presentation are a big problem.\""), .cross("Did any roof on that street have hail damage?", "\"A couple did. I inspected two in the neighborhood and found hail dents on one. {V}'s roof was not one of them.\""), .cross("Is it possible work was actually done on {V}'s roof?", "\"The crew did some work. It was minor, like resealing flashing. It was nowhere near $24,000 worth.\"")],
        defenseRole: "Roofer",
        defenseExam: [.direct("Was there hail damage in the area that year?", "\"Yes. In places, hail damaged many roofs. Our crew did dozens of repairs that season.\""), .direct("Was {V}'s roof one of them?", "\"I am unsure. I did not look at it myself. I only heard about it from {D}.\""), .direct("How did {D} run the sales visits?", "\"Fast. {D.He} wanted the contract signed that day because of the crew's schedule.\""), .direct("How long have you been roofing?", "\"Twenty-two years. I work for a crew that does repairs and replacements across this part of the state.\""), .direct("What kind of storm hit that year?", "\"A big hailstorm in the spring tore up roofs across several counties. We had a waiting list for months.\""), .direct("How do you tell hail damage on a roof?", "\"Round dents in the shingle with a loss of granules and a bruised mat underneath. It takes a close look, and not every roof shows it.\""), .cross("Did you see the photos the defendant showed?", "\"No. I did not see them. I only know about them from others.\""), .cross("Did you work on {V}'s roof?", "\"No. I did not work on that job. I was on other jobs.\""), .cross("Is same-day signing normal?", "\"It is common in storm work, but not good practice. I do not like it.\""), .cross("Did you personally go up on {V}'s roof?", "\"No. {DF} handled that visit while I was on another job, so everything I know about it came from {DF}'s account afterward.\""), .cross("Do you think the roof needed $24,000 in work?", "\"I cannot say without seeing it. That is a big number for a roof of that size.\"")],
        theory: ("{D} staged damage.", "Real damage."),
        allocution: "\"I believed there was real damage on that roof, because hail hit the whole county that year and I saw it on nearby houses. If the photos were of another house, that was a mix-up and not a plan. I'm sorry that {V} paid so much and feels so betrayed. I'd like to make it right.\"",
        truths: ("{DL} pressured {V} to sign the same day.", "A hail storm hit the county that year."),
        defendant: [.direct("Did you stage the photos of damage?", "\"No. The photos were mixed up. I did not mean to show photos of another house.\""), .direct("Was there damage to {V}'s roof?", "\"I believed so. Hail hit the county that year, and I saw damage on nearby roofs.\""), .direct("Did you ask {V} to sign the same day?", "\"Yes. I wanted to lock in the work before the next storm. I know that was pushy.\""), .direct("How did you find {V} as a customer?", "\"My crew was working on a roof in the neighborhood after the storm, and I knocked on doors to offer free inspections. {V} was friendly and let us up.\""), .direct("Tell the jury what you saw on the roof.", "\"Some curled shingles and a few spots I thought were hail marks. I took pictures of the damage and brought them down to show {V}.\""), .direct("Why did you want the contract signed that day?", "\"My crew's schedule was filling up, and prices for materials were rising. I wanted to lock in a start date.\""), .cross("The inspector found a sound roof. Who is wrong?", "\"The inspector may have missed something. I believed there was damage.\""), .cross("$24,000 for a roof that did not need work. Isn't that a scam?", "\"It was not. I believed the work was needed. I did the work I was paid for.\""), .cross("The photos came from another house. How is that a mix-up?", "\"It was a folder with many jobs. I picked the wrong ones. I know how it looks.\""), .cross("The inspector found no hail damage. Were you looking at the same roof?", "\"Yes, but I looked from a different angle and with a different standard. I stand by what I thought I saw.\""), .cross("Why were the pictures from another house?", "\"I had them mixed together in one folder. I did not realize until later that I showed the wrong ones.\"")],
        openings: ("{V}, a widow, paid $24,000 to {D}'s crew for roof repairs after being shown photos of hail damage. An inspector found a sound roof, and the photos came from another house.", "By the end of this trial, the proof will show that hail struck the county that year, that photos can be mixed up, and that {D} believed the roof needed work."),
        closings: ("Photos from another house, a roof that was sound, and a $24,000 contract signed on the spot by a widow. This was a scam.", "A hail storm that damaged roofs across the county, a salesman in a hurry, and a mixed-up folder. The State must prove {D} meant to deceive."),
        timeline: [(0, "The knock."), (0, "Noon: the contract."), (14, "The work is done."), (60, "The inspection.")],
        identified: "An inspector.",
        aggravating: ["The victim was particularly vulnerable", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "{D.He} was kind, then {D.he} was gone. {D.He} sat at my kitchen table, drank my coffee, and showed me photos of damage that wasn't mine. I paid twenty-four thousand dollars of my husband's savings. I'm eighty, and I feel ashamed that I trusted a stranger.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let loanSharkThreats = SmallCases.make(
        key: "story.loanSharkThreats",
        category: .whiteCollar,
        headlines: ["Lender Threatened Borrower Over Triple-Interest Debt", "Voicemails Warn of 'Visit'"],
        law: "extortion",
        threshold: 7,
        spec: "Threatened {V} with injury to obtain payment of $6,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} lent {V} $2,000 and demanded $6,000 in repayment, leaving voicemails that threatened a 'visit.' {DL} says it was just firm collection. The loan note puts the interest at 300%. The voicemails began the first week, {D.he} made the visit in the second week, and a relative says {V} was afraid.",
        state: [E(.digital, 3, "Voicemails", "'I'll visit your house.'"), E(.document, 2, "Loan Note", "$2,000 at 300%."), E(.statement, 2, "Sister", "{V} was afraid.")],
        defense: [E(.statement, 1, "Collection", "{DL} says it was firm collection.")],
        role: "Detective",
        exam: [.direct("What did {D} lend {V}, and what was demanded?", "\"{D} lent {V} $2,000 and demanded $6,000 back. The loan note puts the interest at 300 percent.\""), .direct("What do the voicemails say?", "\"They say, 'I'll visit your house.' They began in the first week, and {DL} made a visit in the second week.\""), .direct("What did {V}'s relative tell you?", "\"That {V} was afraid. {V} told the relative about the calls and the visits.\""), .direct("How did you learn about the loan?", "\"{V}'s relative called us after hearing voicemails left on {V}'s phone. {V} came in a day later with the loan note and the recordings.\""), .direct("What does the note say about repayment?", "\"$2,000 borrowed, $6,000 due in thirty days, which works out to 300 percent interest. It carries both signatures and a date.\""), .direct("What did the visit look like?", "\"{DL} came to the door in the second week and stood on the porch. {V} did not open the door, and {DL} told {V} through it that the money was overdue.\""), .cross("{V} signed the note freely, didn't {V.he}?", "\"Yes. {V} signed it, and I do not dispute that. The question is what happened afterward.\""), .cross("Did the defendant ever hurt {V}?", "\"No. There was no violence. {DL} spoke and showed up, but did not touch {V}.\""), .cross("{D} says it was firm collection, doesn't {D.he}?", "\"Yes. A lender can press for payment. But the voicemails and the visits went further than that.\""), .cross("Did the defendant ever say a specific act of violence?", "\"No. The voicemails speak of a visit but not of hurting anyone. I cannot point to a specific threatened injury.\""), .cross("What did {V} do to get the money?", "\"{V} said {V.he} tried to borrow from friends but could not raise it. {V.he} had not paid anything when the calls started.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Did {D} act violently toward anyone?", "\"No. I never saw {D} do anything violent. {D.He} has always been calm around the neighborhood.\""), .direct("Did the defendant come to {V}'s house?", "\"Yes. I saw {DF} at the door. {DF} knocked, stood outside, and left after a few minutes.\""), .direct("What did the defendant do when {V} answered?", "\"They spoke at the door. I could not hear it, but it did not look like a fight.\""), .direct("How long have you lived near the defendant?", "\"Seven years, a few doors down. We say hello over the fence, and I have watched {D.his} house when {D.he} was away.\""), .direct("What did {D} do when you saw {D} at {V}'s door?", "\"{DF} knocked and waited. When no one answered, {DF} spoke to the door and left. I saw no shouting or banging.\""), .direct("How would you describe the defendant in the neighborhood?", "\"Steady and polite. {DF} helps with yard work for older neighbors, and I never saw {DF} lose a temper.\""), .cross("How many times did the defendant come by?", "\"Twice that I noticed. I do not know if there were more.\""), .cross("Did {V} seem afraid to you?", "\"{V} looked nervous. I cannot say more than that.\""), .cross("Do you know the terms of the loan?", "\"I know it was high interest. I do not know the exact terms.\""), .cross("How far is your house from {V}'s?", "\"A few doors down, about forty yards. I saw {DF} on the porch but could not hear the words.\""), .cross("Did you hear anything about the voicemails?", "\"Only after the fact from other neighbors. I have never heard them.\"")],
        theory: ("{D} threatened a borrower.", "Collection."),
        allocution: "\"I lent that money to help, and I wanted to be paid back, and I was firm about it. I never threatened anyone, and when I said I would visit, I only meant to come and talk. I know the interest was high, and I'm sorry it caused trouble. I'd like to settle this in a way that is fair.\"",
        truths: ("{DL} showed up at {V}'s house twice.", "{V} signed the note freely."),
        defendant: [.direct("Did you threaten {V}?", "\"No. I did not threaten {V.him}. I was firm about the money, and I wanted to be repaid.\""), .direct("What did you mean by 'I'll visit your house'?", "\"I meant I would come talk.\""), .direct("Did you go to {V}'s house?", "\"Yes. I went to talk about the loan. I did not go to hurt anyone.\""), .direct("How did you come to lend {V} money?", "\"{V} asked me at a neighborhood gathering. {V} said it was an emergency and that the bank would not help. I handed over $2,000.\""), .direct("Why did you set the terms the way you did?", "\"It was a short-term personal loan with no collateral. I thought a big return was fair for the risk, and {V} agreed.\""), .direct("What happened when {V} did not pay?", "\"I called, and when I got no answer I left voicemails. Then I went to the house to ask for a plan to pay.\""), .cross("The interest is 300 percent, isn't it?", "\"It is high. {V} agreed to it, and I did not hide it.\""), .cross("You showed up twice, didn't you?", "\"Yes. Twice. I wanted to get paid.\""), .cross("The voicemails say you will visit. How is that not a threat?", "\"I can see how it sounds. I did not intend it as one.\""), .cross("Did you tell {V} that you would 'visit' on purpose to scare {V.him}?", "\"No. I said it to let {V.him} know I was coming. I can see now that it sounded like pressure, and I did not think about that.\""), .cross("A 300 percent rate is not a normal loan. Why did you charge it?", "\"Because I could. {V} signed, and I did not give it much thought. I know it is too high.\"")],
        openings: ("{D} lent {V} $2,000 at 300 percent interest and demanded $6,000 back, leaving voicemails that said 'I'll visit your house' and then showing up twice. {V} was afraid.", "The defense will present evidence that {V} signed the note freely and that {D} was a firm lender who never raised a hand or made a threat."),
        closings: ("A loan at 300 percent, voicemails about a visit, and a lender who showed up twice at {V}'s door. {V} was afraid, and the evidence shows why.", "A signed note, a firm lender, and visits to talk. The State must prove a threat, and a collector who knocks on a door is not a criminal."),
        timeline: [(-30, "The loan."), (0, "Week 1: voicemails."), (0, "Week 2: the visit."), (1, "{V} reports.")],
        identified: "Voicemails.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I stopped sleeping after the first voicemail. I borrowed two thousand dollars to fix my truck, and then I was told I owed six. Every call ended with a promise to come by the house, and my kids were home. I bought a lock and moved my children into the back room.",
        doctrines: ["burdenOfProof"])

    static let bailBondsJailer = SmallCases.make(
        key: "story.bailBondsJailer",
        category: .whiteCollar,
        headlines: ["Bail Bondsman Paid Jailer for Names of New Arrests", "Cash App Records Tell the Story"],
        law: "bribery",
        threshold: 7,
        spec: "Corruptly gave a thing of value to a public official, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D}, a bail bondsman, paid a jailer $300 a week for names of new arrestees. App records show payments on {DATE}. {DL} says they were friends sharing meals.",
        state: [E(.digital, 3, "Payment App", "Weekly $300 to the jailer."), E(.digital, 3, "Texts", "'Who came in?'"), E(.statement, 2, "Jailer", "'I gave him names.'")],
        defense: [E(.statement, 1, "Friends", "{DL} says they were friends.")],
        role: "Jail administrator",
        exam: [.direct("What did you find about {DL}'s payments to a jailer?", "\"App records show a weekly $300 payment from {D}, a bail bondsman, to one of our jailers. The payments run week after week.\""), .direct("What do the text messages show?", "\"Messages from {D.him} to the jailer asking, 'Who came in?' That's a request for the names of new arrestees.\""), .direct("What did the jailer tell you?", "\"The jailer said names were given to {D.him}. That statement is in evidence, and it explains the weekly payments.\""), .direct("How did you find the payment pattern?", "\"A routine audit flagged a jailer's personal app account receiving $300 every Friday from {D.him}. The deposits went back four months.\""), .direct("What did {D} get in return?", "\"The jailer told us the names of new arrestees were sent by text the same day, usually before a bond hearing, so {D.he} could call families first.\""), .direct("What did your policies say?", "\"Staff may not share arrest information or accept payment from bonding agents. The jailer signed those policies at hire.\""), .cross("{DL} says they were friends sharing meals, doesn't {D.he}?", "\"Friends do share meals. But the texts and the weekly amount are not typical of a lunch.\""), .cross("Does {DL} do business with your jail?", "\"Bail bondsmen deal with the jail every day. That's normal. Paying for arrest information isn't.\""), .cross("Did you see {DL} pay the jailer?", "\"No. I found the app records and the messages. I didn't see any exchange in person.\""), .cross("Did the jailer admit being paid for names?", "\"The jailer admitted giving names and acknowledged the payments, but described some of them as lunch money.\""), .cross("Were the names confidential?", "\"Arrest records are public eventually, but the timing is the issue. Receiving names before the public posting gave {DL} an advantage.\"")],
        defenseRole: "Bartender",
        defenseExam: [.direct("Do you know {DL} and the jailer?", "\"Yes. They come into my bar. They've been regulars together for a long time.\""), .direct("How often did they dine together?", "\"Weekly, usually. They'd sit at the same table and eat and talk.\""), .direct("Who paid?", "\"They'd split it, or one would cover. I never kept track.\""), .direct("What kind of bar do you tend?", "\"A neighborhood place near the courthouse. Many people who work around the jail and court stop in for dinner after a shift.\""), .direct("What did you see of {D} and the jailer?", "\"They came in on Fridays and took the corner booth. They ordered food and drinks, talked, and sometimes laughed loudly.\""), .direct("Did either of them seem secretive?", "\"No. They sat in plain view and talked to people who stopped by the table. It looked like friends having dinner.\""), .cross("Did you hear what they talked about?", "\"Mostly small talk about sports and work. I wasn't listening in, since I was busy serving other tables.\""), .cross("Did you ever see money change hands?", "\"Not directly. They settled the tab at the end of the meal, and that's all I ever saw happen.\""), .cross("Do you know about the weekly $300?", "\"No. I only know about the weekly meals together. I heard about any payments much later.\""), .cross("Did you ever hear either of them mention arrests or names?", "\"Not that I recall. I mostly heard sports talk. I was behind the bar and not trying to listen.\""), .cross("Did you see the defendant hand over any money?", "\"I saw them split a bill sometimes. I never saw an envelope or cash passed across the table.\"")],
        theory: ("{D} paid a jailer for names.", "A friendship."),
        allocution: "\"The jailer is a friend of mine, and we have shared lunches and dinners for years. The money I sent was to cover meals, and it was never a payment for names. I may have asked who came in as ordinary talk about the day. I'm sorry if it looked improper to anyone.\"",
        truths: ("Names were sent before bond hearings.", "The jailer and {DL} dined together often."),
        defendant: [.direct("Why did you send money to the jailer?", "\"We're friends. We share meals, and I covered a lot of them. It was never a payment for information.\""), .direct("What did you mean by 'Who came in?'", "\"It was casual. I was asking about the day, who was in the news. I wasn't asking for names to solicit business.\""), .direct("Did the jailer give you names?", "\"Not for money. We talked about the jail in general. I never offered pay for any list.\""), .direct("How long have you been a bondsman?", "\"Twelve years. I make money when families call me after an arrest, so contacts at the jail are part of the landscape.\""), .direct("Tell the jury about your friendship with the jailer.", "\"We met years ago and started having dinner on Fridays. I covered most meals, and I sent money to help with bills at times.\""), .direct("What were you asking when you texted 'Who came in?'", "\"I was making conversation about the day. The jailer would sometimes talk about the shift, and I would ask if it was busy.\""), .cross("$300 each week is a lot for dinner, isn't it?", "\"We ate out often, and I paid. I'd rather not say I'm a generous friend, but it adds up.\""), .cross("The jailer says names were given to you, doesn't the jailer?", "\"The jailer may remember it that way. I don't. We chatted, and I may have heard some names.\""), .cross("You earn money from new arrestees, don't you?", "\"Yes. That's my business. But I never paid to get an inside edge.\""), .cross("Why would you send the same amount every week for dinners?", "\"It was easier than keeping track of tabs. It added up to about that much, and I never thought it would look like a payment.\""), .cross("The jailer says names were provided. Why would the jailer say that if it was not true?", "\"I cannot answer for another person. Maybe I heard some names during our talks, but I never paid for them.\"")],
        openings: ("A bail bondsman, {D}, paid a jailer $300 every week, and texted, 'Who came in?' The jailer says names were given. The State will show the payment app, the texts, and the jailer's statement.", "The defense will present a long friendship, weekly dinners with a bartender who saw them, and a bondsman whose messages were small talk. Friends share money and meals."),
        closings: ("Weekly payments of $300, a text asking who came in, and a jailer who says names were given. That's not a dinner club. It's a business arrangement.", "Friends share meals and pay for each other. A bartender saw it. The State has not proved the money was a bribe for official information."),
        timeline: [(-90, "Payments begin."), (0, "Month 3: audit."), (0, "Month 3: texts found."), (1, "{DL} is charged.")],
        identified: "An app.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let barnFeudFire = SmallCases.make(
        key: "story.barnFeudFire",
        category: .violent,
        headlines: ["Farmer's Barn Burned in Feud Over Land", "Hay and Equipment Lost"],
        law: "burningBuildings",
        threshold: 8,
        spec: "Willfully and maliciously burned a barn owned by {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A barn burned overnight on {DATE}, destroying hay and equipment worth $140,000. {D}, a neighbor in a land feud, was seen leaving. {DL} says {D.he} was checking cattle.",
        state: [E(.forensic, 3, "Fire Report", "Accelerant at the hay."), E(.video, 2, "Road Camera", "{D}'s tractor passes at midnight."), E(.statement, 2, "Neighbor", "Saw a light.")],
        defense: [E(.statement, 1, "Cattle", "{DL} says {D.he} was checking cattle.")],
        role: "Fire marshal",
        exam: [.direct("What did you find at the barn on {DATE}?", "\"It burned overnight. Hay and equipment worth $140,000 were destroyed. I found accelerant at the hay, where the fire started.\""), .direct("What ties {DL} to the area?", "\"A road camera shows {D}'s tractor passing at midnight. A neighbor also saw a light near the barn that night.\""), .direct("What was the relationship between {DL} and {V}?", "\"They were neighbors in a land feud. That's what the neighbor told us, and what the records show.\""), .direct("When were you called and what did you find on arrival?", "\"Crews were called at about 1 a.m. and I arrived by 2. The barn was fully involved, and the hay loft had already collapsed into the lower level.\""), .direct("How did you determine where the fire started?", "\"Burn patterns led to the hay stacked against the east wall. A lab confirmed an ignitable liquid in samples from that spot, and no electrical source was nearby.\""), .direct("What did the neighbor report?", "\"The neighbor saw a flashlight beam moving near the barn just before the glow started. The neighbor could not say who held the light.\""), .cross("Did anyone see {DL} at the barn?", "\"No. The road camera shows the tractor passing by. It doesn't show {D.him} at the barn.\""), .cross("{DL} says {D.he} was checking cattle, doesn't {D.he}?", "\"People do check cattle at night. I can't say it's not true.\""), .cross("Can you say the accelerant came from {DL}?", "\"No. I found accelerant at the hay. I can't say where it came from.\""), .cross("How far is the barn from the road camera?", "\"About a quarter mile. The camera shows the road, not the barn.\""), .cross("Was there any sign of loose cattle in the area?", "\"I did not look for them. A veterinarian later told me a fence was down that night, but I did not verify it.\"")],
        defenseRole: "Veterinarian",
        defenseExam: [.direct("Do you treat {DL}'s cattle?", "\"Yes. I'm a veterinarian, and I've seen {D}'s herd. I know the farm.\""), .direct("Were cattle loose that night?", "\"Yes. A fence had gone down and several cattle were out. I got a call about it.\""), .direct("Whose cattle were they?", "\"They were {DF}'s goats. They were on the road and in the area. {DF} was trying to round them up.\""), .direct("How long have you been {D}'s veterinarian?", "\"About fifteen years. I treat the herd, check the pastures, and take emergency calls when cattle get out.\""), .direct("What did you do that night?", "\"I got a call around eleven that cattle were loose near the road. I drove out and found {DF} on the tractor trying to move them.\""), .direct("What condition was the fence in?", "\"A section of wire had been pulled down, with a post leaning over. It looked like animals had pushed on it.\""), .cross("Did you see {DL} that night?", "\"Briefly, I think. I was called to a different problem. I don't recall exactly.\""), .cross("Did you see the barn fire?", "\"No. I heard about it afterward. I wasn't near the barn.\""), .cross("Could {DL} have checked cattle and also set a fire?", "\"I can't speak to that. I only know cattle were loose.\""), .cross("How long were you with the defendant?", "\"Only about twenty minutes. I left to help with a calf, and I do not know where {D.he} went after that.\""), .cross("Did you see anything near {V}'s barn?", "\"No. I never went down that road. I saw only the stretch where the cattle were.\"")],
        theory: ("{D} burned a barn.", "Checking cattle."),
        allocution: "\"My cattle were loose that night because a fence was down, and I took the tractor out to look for them. I did not set that barn on fire, and I never would, even in a feud over land. I'm sorry for my neighbor's loss. I'd like to settle our dispute peacefully and put the bad blood aside.\"",
        truths: ("{DL} had threatened {V} at a hearing.", "{DL}'s cattle were out on the road."),
        defendant: [.direct("Why was your tractor on the road at midnight?", "\"My cattle were loose. A fence was down, and I was out checking on them. I used the tractor to get around.\""), .direct("Did you set the barn on fire?", "\"No. I would never burn a barn, even with the feud. I was out on the road looking for cattle.\""), .direct("What about the feud with {V}?", "\"It's been a hard dispute about land. We argue, but I'd never destroy property over it.\""), .direct("How long have you farmed that land?", "\"All my life, as did my parents. The feud with {V} is about where our boundary runs, and it has gone on through two surveys.\""), .direct("Describe what happened that night.", "\"Around eleven, a neighbor called to say my cattle were on the road. I took the tractor, found the fence down, and spent a while looking for them.\""), .direct("What did you see when you went past {V}'s barn?", "\"Nothing unusual. It was dark and quiet. I kept going and found most of my cattle in a ditch down the road.\""), .cross("Your tractor passed {V}'s barn at midnight, didn't it?", "\"The camera says so. I went along that road to find my cattle. I didn't stop at the barn.\""), .cross("You and {V} are in a land feud, aren't you?", "\"Yes. It's no secret. But that doesn't mean I'd burn a barn.\""), .cross("$140,000 in hay and equipment burned, didn't it?", "\"So I'm told. I'm sorry for the loss. It wasn't me.\""), .cross("You and {V} fought over land for years. Isn't that motive?", "\"It would be, if I were that kind of person. I argued with {V} but I would never burn a barn.\""), .cross("A tractor on that road at midnight, near a barn that burns an hour later. Why shouldn't the jury connect those?", "\"Because I was chasing cattle. I understand why the timing looks bad, but I did not stop there.\"")],
        openings: ("A barn burned overnight, destroying $140,000 in hay and equipment, with accelerant at the hay. {D}, a neighbor in a land feud, was on camera driving past at midnight. The State will show the fire report and the road camera.", "Jurors will also see loose cattle, a farmer out on a tractor looking for them, and a veterinarian who confirms it. A feud is not proof of a fire."),
        closings: ("A land feud, accelerant at the hay, and {D}'s tractor on camera at midnight. The fire marshal can tell you how the fire started, and the motive points to {D.him}.", "Cattle were loose and {D} was out looking. No one saw {D.him} at the barn, and the State cannot tie any accelerant to {D.him}. A feud is not a fire."),
        timeline: [(-30, "The land hearing."), (0, "Midnight: the tractor passes."), (0, "1 a.m.: the fire."), (0, "2 a.m.: crews arrive.")],
        identified: "A camera.",
        mood: .divided,
        impact: "Three generations of work burned in that barn. My grandfather built it, my father filled it, and I put up hay in it every summer. We lost equipment and a hundred forty thousand dollars of feed in a few hours. I still smell the smoke when the wind turns.",
        doctrines: ["burdenOfProof"])

    static let chaserStagedInjuries = SmallCases.make(
        key: "story.chaserStagedInjuries",
        category: .whiteCollar,
        headlines: ["Law Office Runner Paid People to File Staged Injury Claims", "Same Clinic, Same Injuries"],
        law: "insuranceFraud",
        threshold: 8,
        spec: "Presented false insurance claims totaling $85,000, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D}, a law office runner, recruited people to file injury claims from staged falls and low-speed crashes. Claims used the same clinic and phrases. {DL} says {D.he} only referred clients.",
        state: [E(.document, 3, "Claim Files", "Twelve claims, same clinic."), E(.digital, 3, "Texts", "'$500 if you say your back hurts.'"), E(.document, 2, "Payment Ledger", "Payments to claimants.")],
        defense: [E(.statement, 1, "Referral", "{DL} says {D.he} only referred clients.")],
        role: "Insurance investigator",
        exam: [.direct("What did you find in your investigation of staged injury claims?", "\"Twelve claims, all using the same clinic and the same phrases. They came from staged falls and low-speed crashes.\""), .direct("What role did {DL} play?", "\"{D}, a law office runner, recruited people to file claims. Texts show offers like '$500 if you say your back hurts.'\""), .direct("What does the payment ledger show?", "\"Payments to claimants. It shows money moving to the people who filed the claims.\""), .direct("How did you spot the pattern?", "\"The claims all described similar falls or low-speed crashes, used the same clinic, and repeated phrases such as 'sudden sharp pain in the lower back' almost word for word.\""), .direct("What did the text messages say?", "\"One read, '$500 if you say your back hurts.' Others set meeting times at the law office and told claimants which clinic to visit.\""), .direct("How much did the claims total?", "\"The twelve files sought roughly $210,000 combined, and the ledger shows cash payments of several hundred dollars to each claimant.\""), .cross("{DL} says {D.he} only referred clients, doesn't {D.he}?", "\"Referring clients is legal. But the texts suggest paying people to claim injuries.\""), .cross("Were some injuries real?", "\"I can't rule that out. Some claimants may have been hurt. That's part of what makes these cases hard.\""), .cross("Did {DL} file any claims personally?", "\"No. {D.He} recruited. The claims were filed by others. I can't say {D.he} signed any.\""), .cross("Were payments listed as coming from the law office?", "\"Some were. Others were from {DL} personally, so I cannot say who authorized each one.\""), .cross("Did any claimant admit that the injury was staged?", "\"Two told us the incident was exaggerated. The others stood by their accounts.\"")],
        defenseRole: "Clinic nurse",
        defenseExam: [.direct("Did you treat {DL}'s referred clients?", "\"Yes. Many came to our clinic. I'm a nurse and I saw them for evaluations.\""), .direct("Were injuries real?", "\"Some were. I saw documented problems with several clients.\""), .direct("What did {DL} say to you?", "\"{D} said the clients needed care and that the office would cover it. I took that at face value.\""), .direct("What do you do at the clinic?", "\"I am a nurse. I take histories, check vitals, and write up findings for the doctor.\""), .direct("How many of {D}'s referrals did you see?", "\"A dozen or so over the year. Some came in limping or holding their backs, and a few had bruising.\""), .direct("Did you ever feel pressure to document injuries?", "\"No. I wrote what I saw and what patients told me. Nobody told me to exaggerate.\""), .cross("Were all the injuries real?", "\"No. Some had little to show. I'd say some complaints were hard to verify.\""), .cross("Did you notice the same phrases in the reports?", "\"I noticed some similarities. I assumed it was template language.\""), .cross("Did {DL} tell you what to write?", "\"No. I never took instructions from {D.him}. I wrote what I observed.\""), .cross("How did you know the patients came through the defendant?", "\"They said so at intake. Many mentioned the law office and a person who gave them the clinic's name.\""), .cross("Did you see the defendant in the clinic?", "\"Occasionally in the waiting room. I never saw {DF} speak with the doctor or touch a chart.\"")],
        theory: ("{D} staged injury claims.", "A referrer."),
        allocution: "\"I worked as a runner, connecting people who had been hurt with lawyers, which is a normal part of that line of work. I never staged a fall or a crash, and I never told anyone to lie. I'm sorry that some of those claims turned out to be false. I'd ask the court to see I only made referrals.\"",
        truths: ("{DL} was paid per claim.", "Several claimants had real injuries."),
        defendant: [.direct("What did you do at the law office?", "\"I was a runner. I connected people who were hurt with the lawyers. It's a normal part of that kind of work.\""), .direct("Did you stage any falls or crashes?", "\"No. I never staged anything. I only talked to people who said they were hurt.\""), .direct("What about the $500 text?", "\"It was poorly worded. I meant a fee for their time to come to the office. I know how it reads.\""), .direct("How did you get your job at the law office?", "\"I started as a receptionist and became a runner, meeting people at their homes or at the office to explain how a claim works.\""), .direct("How did you pick the clinic?", "\"It was the one the office used for evaluations, and the staff there were quick to see people. I never considered another one.\""), .direct("How were you paid?", "\"The office paid me per client who signed up. I did not set the fee, and I did not look closely at what it was for.\""), .cross("You offered $500 if people said their back hurt, didn't you?", "\"The text says that. I didn't mean to buy a claim. I was careless.\""), .cross("Twelve claims went to the same clinic, didn't they?", "\"Yes. It's the clinic we referred to. It's convenient. I didn't think it was suspicious.\""), .cross("You were paid for each client, weren't you?", "\"I was paid by the office. I didn't think about how it looked.\""), .cross("Why offer $500 for a back complaint?", "\"I wrote it badly. I meant payment for time and travel, but I know it looks like paying for a claim.\""), .cross("Is it a coincidence that twelve claims used the same words?", "\"I used a form from the office. People copied what they were given, and I did not think about how identical they looked.\"")],
        openings: ("{D}, a law office runner, recruited people to file injury claims after staged falls and low-speed crashes. Twelve claims used the same clinic and phrases, and a text offered '$500 if you say your back hurts.' The State will present the investigator and the texts.", "The defense evidence includes a runner who referred clients to a clinic, a nurse who found some injuries real, and no proof that {D} staged anything."),
        closings: ("Twelve claims, one clinic, and a text offering $500 to say your back hurts. That is how a staged-injury ring is built, and {D} recruited the people.", "Referring clients to a clinic is legal, and some injuries were real. The State has not proved {D} staged any accident or knew claims were false."),
        timeline: [(-120, "Claims begin."), (0, "Month 4: pattern flagged."), (0, "Month 5: texts found."), (1, "{DL} is charged.")],
        identified: "Claim files.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let hayrideTractorWreck = SmallCases.make(
        key: "story.hayrideTractorWreck",
        category: .traffic,
        headlines: ["Child Dies When Drunk Driver's Tractor Overturns Hayride Wagon", "Hill Road Wreck"],
        law: "felonyDBV",
        threshold: 7,
        spec: "Unintentionally caused the death of {V} while driving impaired, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A hayride wagon overturned on a hill road on {DATE}, killing {V}, a nine-year-old. {D}, driving the tractor, blew .13. {DL} says a brake line failed.",
        state: [E(.forensic, 3, "Breath Result", "A result of .13."), E(.statement, 3, "Passenger", "'He took the curve fast.'"), E(.forensic, 2, "Autopsy", "Fatal head injury.")],
        defense: [E(.document, 1, "Mechanic Note", "A note on worn brake lines.")],
        role: "Highway Patrol trooper",
        exam: [.direct("What happened on the hill road on {DATE}?", "\"A hayride wagon overturned. {V}, a nine-year-old, was killed. {D} was driving the tractor pulling the wagon.\""), .direct("What did {DL}'s breath test show?", "\"A .13. That's well above the legal limit. I took the test at the scene.\""), .direct("What did a passenger tell you?", "\"That {D.he} took the curve fast. That statement is in evidence. The autopsy found a fatal head injury.\""), .direct("Where were you when you got the call, and what did you find?", "\"I was on patrol a few miles away. On a steep hill road I found the wagon on its side, the tractor stopped upright, and a crowd around {V}.\""), .direct("How was the breath test given?", "\"About an hour later at the scene, after medics cleared {D.him} to talk. I used a calibrated device, and {D.he} blew .13 twice.\""), .direct("What did {V}'s injuries look like?", "\"A fatal head injury from the wagon rolling over. {V} was nine years old and was pronounced dead at about 7 p.m.\""), .cross("{DL} says a brake line failed, doesn't {D.he}?", "\"I've seen a note about worn brake lines. Whether a line actually failed is another question.\""), .cross("Can you say what caused the wagon to overturn?", "\"Speed on the curve is what the passenger described. Brakes may have played a role. I can't say for sure.\""), .cross("Was the road in good condition?", "\"It was a hill road, with a curve. Nothing unusual about the surface that I noted.\""), .cross("Did you inspect the tractor brakes?", "\"I looked at the tractor but I am not a mechanic. I noted fluid at one fitting, and I left a full inspection to an expert.\""), .cross("How many passengers were on the wagon?", "\"Eleven, including several children. Most had bruises and scrapes, and one had a broken arm.\"")],
        defenseRole: "Farm mechanic",
        defenseExam: [.direct("Do you work on {DL}'s farm equipment?", "\"Yes. I'm the farm mechanic. I look at the tractors and the wagons.\""), .direct("Were the brakes worn?", "\"Yes. I noted worn brake lines on the tractor. I wrote a note about it.\""), .direct("Did you tell {DL}?", "\"I mentioned it. We talked about getting the lines replaced. It hadn't been done yet.\""), .direct("How long have you worked on {D}'s equipment?", "\"About ten years. I service the tractors, the mower, and the wagon whenever something needs attention.\""), .direct("What did you find on the tractor before the ride?", "\"A brake line with cracking and some fluid seepage. I wrote it in my notes and recommended replacing it soon.\""), .direct("How serious is that kind of wear?", "\"It can lead to a soft pedal or a sudden loss of pressure, but plenty of tractors run with it for a while. It depends on how hard the brakes are used.\""), .cross("Did the brakes fail?", "\"Unclear. I don't know what happened on that road. I only know the lines were worn.\""), .cross("Could the brakes have worked well enough to stop?", "\"They might have. Worn lines don't always fail. I can't say for certain.\""), .cross("Did you inspect the tractor after the crash?", "\"I looked at it afterward. I can't say the worn line was the cause.\""), .cross("Did you tell the defendant to stop using the tractor?", "\"No. I said it should be replaced. I did not say to park it, and I did not know how soon it would be needed.\""), .cross("Did you look at the tractor after the wreck?", "\"Briefly. I saw some fluid at the fitting. I could not tell you whether it leaked before or after the crash.\"")],
        theory: ("{D} drove drunk and killed a child.", "A brake failure."),
        allocution: "\"I'd had a few drinks earlier, and I should never have gotten behind the wheel of that tractor. I felt the brakes give out on the hill, but that doesn't change what I did. I'm sorrier than I can say for the family of that child. I will carry those children's screams with me forever.\"",
        truths: ("{DL} had been drinking at the farm.", "A mechanic's invoice shows the brake line was flagged worn before the ride."),
        defendant: [.direct("What happened with the wagon?", "\"I was driving carefully on the hill. The brakes didn't hold as I came to the curve. The wagon began to push me, and I couldn't stop it.\""), .direct("How many drinks had you had?", "\"I'd had a few drinks earlier. I felt steady on my feet, which I now see proves nothing. I'd never put children at risk knowingly.\""), .direct("How do you feel about {V}?", "\"I'm devastated. Not a day goes by that I don't think of {V} and the family.\""), .direct("How did the hayride come together?", "\"It was a family fall event on my farm. I had done this ride for years with the same tractor and wagon, and the kids always loved it.\""), .direct("What did you drink before the ride?", "\"A couple of beers with the relatives while we got the wagon ready. I did not feel any effect, and I would not have driven if I had.\""), .direct("Describe what happened at the curve.", "\"I touched the brake as we started down. It felt soft, and the wagon pushed ahead of me. The tractor slid, and the wagon went over.\""), .cross("You blew a .13, didn't you?", "\"Yes. I did. I know that's over the limit. I thought I was fine.\""), .cross("The passenger says you took the curve fast, doesn't the passenger?", "\"The passenger may think so. I felt the brakes giving out. I wasn't going fast on purpose.\""), .cross("You knew the brakes were worn, didn't you?", "\"I'd heard something about the lines. I didn't think they'd fail. I should have checked.\""), .cross("You had been drinking and you were hauling children on a steep road. Why drive?", "\"I thought I was fine. I know now that was a terrible judgment.\""), .cross("The mechanic told you the brake lines were worn. Why take that tractor on a hill?", "\"I did not think it was urgent. I planned to get them replaced after the season, and I regret waiting.\"")],
        openings: ("A hayride wagon overturned on a hill road and killed {V}, a nine-year-old. {D}, driving the tractor, blew a .13, and a passenger says {DL} took the curve fast. The State will present the trooper and the passenger.", "The defense will point you to worn brake lines, a mechanic who noted them, and a driver who felt the brakes give out. A tragedy is not automatically a crime by the driver."),
        closings: ("A nine-year-old killed, a driver at .13, and a curve taken too fast. {D} was in charge of that tractor and the lives behind it.", "Worn brake lines, a steep hill, and a sharp curve. The State must prove that {D}'s impairment, and not a mechanical failure, caused this terrible tragedy."),
        timeline: [(0, "6 p.m.: the ride."), (0, "6:20 p.m.: the curve."), (0, "6:25 p.m.: the overturn."), (0, "7 p.m.: {V} dies.")],
        identified: "A breath test.",
        aggravating: [],
        mitigating: ["The defendant has accepted responsibility"],
        mood: .sympathetic,
        impact: "{V.He} was our only child. Nine years old, and {V.he} had been counting the days to that hayride all month. We buried {V.him} in the jacket {V.he} wore that night. Our house has no sound in it now, and we don't know how to keep living in it.",
        doctrines: ["intoxication", "lesserIncluded"])

    static let teacherHallAttack = SmallCases.make(
        key: "story.teacherHallAttack",
        category: .violent,
        headlines: ["Parent Attacks Teacher in School Hallway Over Grade", "Security Camera Captures Shove"],
        law: "assaultGovOfficial",
        threshold: 6,
        spec: "Assaulted {V}, a school employee, while performing duties, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, a parent, shoved {V}, a teacher, into a locker on {DATE} over a failing grade. {DL} says {V} blocked the way. The shove came about ten minutes into a 3 p.m. meeting about the grade. Deputies were called at 3:15 p.m., and {V} had a bruise on the shoulder.",
        state: [E(.video, 3, "Hall Camera", "{D} shoves {V}."), E(.forensic, 2, "Medical Note", "Shoulder bruise."), E(.statement, 2, "Principal", "'I heard shouting.'")],
        defense: [E(.statement, 1, "Block", "{DL} says {V} blocked the way.")],
        role: "Principal",
        exam: [.direct("What was the 3 p.m. meeting about?", "\"A failing grade. {D}, a parent, came to talk with {V}, a teacher, and the meeting got heated about ten minutes in.\""), .direct("What does the hall camera show?", "\"It shows {DL} shoving {V} into a locker. {V} had a bruise on the shoulder afterward.\""), .direct("What did you hear?", "\"I heard shouting from the hallway and went out. Deputies were called at about 3:15.\""), .direct("How did {DL} act when the meeting began?", "\"{D.He} came in firm but polite, with the grade report in hand. It was only about ten minutes in that {D.his} voice started rising.\""), .direct("What happened around ten past three?", "\"I heard raised voices in the hallway and stepped out. I saw {DL} shoving {V} backward into a row of lockers, and {V} grabbed {V.his} shoulder.\""), .direct("What did you do?", "\"I stepped between them and told {DL} to leave. I called the office to contact deputies, who arrived at 3:15, and {DL} was arrested later at about 4.\""), .cross("{D} had been told to leave, hadn't {D.he}?", "\"Yes. {D.He} was told to leave, and the shove came after that.\""), .cross("Was {V} standing in a doorway?", "\"Yes. {V} stood in a doorway. {DL} says {V} blocked the way.\""), .cross("Did {V} touch the defendant?", "\"I did not see {V} touch {DL}. The video shows {V} standing there.\""), .cross("How loud was the defendant before the shove?", "\"Loud, but I did not hear threats. {D.He} was upset about the grade and kept saying it was unfair.\""), .cross("Did {V} step into the doorway on purpose?", "\"I cannot say. {V} was standing near the door when I first saw them, but I do not know if it was to block {DL}.\"")],
        defenseRole: "Hall monitor",
        defenseExam: [.direct("Did {V} block the way?", "\"{V} was standing close, near the doorway. It looked like {V} was in the way.\""), .direct("Was it a narrow hall?", "\"Yes. It was a tight space near the lockers. Two people could barely pass.\""), .direct("What did {D} do before the shove?", "\"{D} was upset and loud. {D.He} tried to get past, and then it happened.\""), .direct("What is your job at the school?", "\"I monitor the halls between classes and after school. I stand near the main hallway and watch for trouble.\""), .direct("Where were you standing when the meeting room door opened?", "\"At the corner by the main hall, about twenty feet from the lockers. I could see that whole stretch of hallway and the meeting room door.\""), .direct("How narrow is that hallway?", "\"Very. The lockers narrow it to maybe four feet. If two people stand there, a third has to squeeze past.\""), .cross("Did {V} say anything to block the defendant?", "\"I did not hear. I only saw {V} standing there.\""), .cross("Did the defendant have to shove?", "\"I cannot say. I would have waited.\""), .cross("How far were you from the two?", "\"About twenty feet. I saw it from the end of the hall.\""), .cross("Did you see {V} deliberately block the defendant?", "\"I saw {V} standing close. I cannot tell you whether it was deliberate.\""), .cross("Did you step in?", "\"Not right away. I was at the other end of the hall, and the principal reached them first.\"")],
        theory: ("{D} shoved a teacher.", "A block."),
        allocution: "\"I lost my temper that afternoon, and I shoved a teacher because I was upset and wanted to leave. I was told to go, and I should have walked out calmly. I'm ashamed to have put my hands on anyone in a school. I'm sorry to the teacher, to the students who saw it, and to my own child.\"",
        truths: ("{DL} had been told to leave.", "{V} stood in a doorway."),
        defendant: [.direct("Did you shove {V}?", "\"Yes, I did. {V} was blocking the way, and I pushed past.\""), .direct("Why did you push?", "\"I was upset and trying to leave, and {V} was in the doorway. I lost my temper.\""), .direct("Were you told to leave?", "\"Yes. I was told, and I was trying to go. {V} was in my way.\""), .direct("What was the meeting supposed to accomplish?", "\"I wanted to understand why my child was failing and how to fix it. I had been trying to reach {V} for weeks without luck.\""), .direct("How did it go wrong?", "\"We went over the grade book and I felt dismissed. I raised my voice, and I was told to leave.\""), .direct("What happened at the door?", "\"I tried to walk out, and {V} was standing in the way near the lockers. I put both hands out to move past, and it turned into a shove.\""), .cross("You were loud, weren't you?", "\"Yes. I was loud. I was upset about my child's grade.\""), .cross("You shoved a teacher into a locker, didn't you?", "\"I did not mean for it to go that far. I apologize.\""), .cross("You could have waited, couldn't you?", "\"Yes. I wish I had. I let anger win.\""), .cross("You pushed a teacher into a locker. Isn't that assault?", "\"Yes. I accept that I pushed. I did not intend to hurt {V}, but I understand that I did.\""), .cross("Why not just ask {V} to step aside?", "\"I was angry, and I should have. I was already out of control, and that is on me.\"")],
        openings: ("During a 3 p.m. meeting about a failing grade, {D}, a parent, shoved {V}, a teacher, into a locker. A hall camera recorded it, and {V} had a bruised shoulder.", "Jurors will hear that {V} stood in a doorway as {D} tried to leave, and that the shove was a frustrated push, not an attack."),
        closings: ("A parent told to leave, a teacher in a hallway, and a shove into a locker caught on camera. A bruised shoulder proves it.", "A narrow hall, a teacher in the doorway, and a parent who pushed to get out. One shove in frustration is not the attack the State describes."),
        timeline: [(0, "3 p.m.: the meeting."), (0, "3:10 p.m.: the shove."), (0, "3:15 p.m.: deputies."), (0, "4 p.m.: arrest.")],
        identified: "A camera.",
        mood: .divided,
        impact: "I fear the hallways now. I've taught in that school for nine years, and I've never been afraid of a parent before. I was pushed into a locker, and my shoulder still aches in the morning. Some days I stand at my classroom door and wonder who is walking toward me.",
        doctrines: ["lesserIncluded"])

    static let illegalFireworksBlast = SmallCases.make(
        key: "story.illegalFireworksBlast",
        category: .violent,
        headlines: ["Illegal Firework Warehouse Explodes, Injuring Firefighters", "Storage Unit Held Hundreds of Cases"],
        law: "firefighterInjury",
        threshold: 7,
        spec: "Willfully caused injury to firefighters through unlawful storage of explosives, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A storage unit holding hundreds of cases of illegal fireworks exploded on {DATE}, injuring three firefighters. {D} rented the unit. {DL} says {D.he} stored them for a friend.",
        state: [E(.document, 3, "Rental Agreement", "Unit rented by {D}."), E(.forensic, 3, "Fire Report", "Fireworks were the fuel."), E(.statement, 2, "Fire Captain", "Three firefighters hurt.")],
        defense: [E(.statement, 1, "Friend", "{DL} says the cases belonged to a friend.")],
        role: "Fire captain",
        exam: [.direct("What happened at the storage unit on {DATE}?", "\"It exploded. Hundreds of cases of illegal fireworks were inside. Fireworks were the fuel for the fire, and three firefighters were hurt.\""), .direct("Who rented the unit?", "\"{D}. The rental agreement shows the unit rented by {DL}. That's what ties {DL} to what was inside.\""), .direct("What injuries did your crew suffer?", "\"Three firefighters were hurt in the blast. We were fighting what we thought was an ordinary fire, and the explosion was a surprise.\""), .direct("How did the incident begin?", "\"At about noon we got a call about smoke from a unit in a row of storage units. We arrived and saw a thin column of gray smoke coming from the door seam.\""), .direct("What happened at 12:20?", "\"As we staged hoses, the unit exploded. A blast and a fireball threw the roll-up door across the lot and knocked down several crew members.\""), .direct("How were your firefighters hurt?", "\"One had a concussion, one burns on the hands, and one a broken collarbone. All three were treated and released, and none of them was back on duty for weeks.\""), .cross("{DL} says the cases belonged to a friend, doesn't {D.he}?", "\"I don't know who owned the fireworks. I only know who rented the unit.\""), .cross("Did you see {DL} store the fireworks?", "\"No. I arrived after the fire started. I only know what the storage records and the fire report show.\""), .cross("Was {DL} at the scene?", "\"I don't recall. I was focused on the fire. I don't think I saw {D.him}.\""), .cross("Could the fire department have known fireworks were inside?", "\"No. The unit was closed and there was no placard. We found out only afterward from the cases and debris.\""), .cross("Did you see anyone come to the scene claiming the unit?", "\"Not while I was there. Deputies later told me they traced the rental agreement to {DL}.\"")],
        defenseRole: "Storage manager",
        defenseExam: [.direct("Do you manage the storage facility?", "\"Yes. I know who rents what. {D} rented a unit from us.\""), .direct("Who paid the rent?", "\"Cash. The rent was paid in cash each month. I remember because most customers use cards.\""), .direct("Who brought the cash?", "\"Usually {DF}. Sometimes someone else came. I didn't keep track.\""), .direct("How long have you managed the facility?", "\"Nine years. I handle rentals, collect rent, and keep the gate and the lights working.\""), .direct("What can you tell the jury about this unit?", "\"It was a ten by twenty drive-up unit rented a year earlier. The rent was paid regularly, and the tenant never complained.\""), .direct("What do tenants sign about hazardous items?", "\"The agreement forbids storing explosives and flammables. We do not inspect, so we rely on tenants to follow the rule.\""), .cross("Whose cash was it?", "\"Unknown. I don't ask. I just take it and give a receipt.\""), .cross("Did you see what was stored?", "\"No. We don't inspect units. I couldn't tell you what was inside.\""), .cross("Did you see {DL} bring boxes?", "\"Not that I recall. I don't watch customers load. I only see them at the office.\""), .cross("Did you ever see boxes labeled as fireworks?", "\"No. If I had, I would have called someone. I never saw inside.\""), .cross("Who else came to the unit?", "\"Occasionally a pickup would stop by. I did not get plate numbers and I cannot describe who was driving.\"")],
        theory: ("{D} stored explosives.", "A friend's goods."),
        allocution: "\"I rented that unit in my own name as a favor to a friend, and I did not look inside. I knew some things were stored there, but I did not know they were fireworks. I'm sorry that firefighters were hurt coming to a fire I did not understand. I wish I'd asked more questions.\"",
        truths: ("{DL} sold fireworks online.", "The friend paid the rent."),
        defendant: [.direct("Why did you rent the unit?", "\"I was storing things for a friend. I rented it in my own name as a favor. I didn't look inside much.\""), .direct("Did you know there were fireworks in the unit?", "\"I knew some things were stored. I didn't know they were illegal fireworks, and I didn't know how many.\""), .direct("Whose fireworks were they?", "\"My friend's. I was holding the unit for my friend. I didn't think they were dangerous.\""), .direct("How did you come to rent the unit?", "\"A friend asked me to put some things in storage because there was no room at the friend's place. I signed the agreement in my own name.\""), .direct("How often did you visit the unit?", "\"A couple of times in the first months. After that I let my friend handle it, and I only paid when asked.\""), .direct("What did you learn after the explosion?", "\"That the unit held fireworks, and that firefighters were injured. I told deputies right away that I rented it for a friend.\""), .cross("The unit was rented in your name, wasn't it?", "\"Yes. I'm responsible for it. I never asked my friend what exactly was going in there.\""), .cross("Hundreds of cases is a lot to not notice, isn't it?", "\"I didn't go in often. I hear how that sounds. I trusted my friend.\""), .cross("Three firefighters were hurt, weren't they?", "\"Yes. I'm so sorry about that. I never imagined anything like that.\""), .cross("You signed the rental agreement. Don't you carry some responsibility for what was inside?", "\"I do. I should have asked, and I should have looked. I took my friend's word and that was a mistake.\""), .cross("Did you ever look inside before the fire?", "\"I opened the door once. I saw boxes stacked high, and I did not read the labels.\"")],
        openings: ("A storage unit holding hundreds of cases of illegal fireworks exploded, injuring three firefighters. {D} rented the unit. The State will show the rental agreement, the fire report, and the fire captain.", "Jurors will also see a person who rented a unit as a favor for a friend, never inspected what was inside, and paid cash like other customers."),
        closings: ("Hundreds of cases of illegal fireworks in a unit rented by {D}, and three firefighters hurt in the blast. The lease is in {D.his} name.", "{D} rented a unit for a friend and did not know what was in it. The State has not proved {DL} knew about illegal fireworks."),
        timeline: [(-30, "The unit is rented."), (0, "Noon: the fire."), (0, "12:20 p.m.: the blast."), (1, "{DL} is identified.")],
        identified: "A rental agreement.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I have burns on my arms from where the wall of that unit blew out. We went in to put out a fire, and nobody told us about the cases inside. Two of my crew are still in therapy for their hands. We do the job to protect people, and we didn't expect an explosion.",
        doctrines: ["burdenOfProof"])

    static let medicSpitBite = SmallCases.make(
        key: "story.medicSpitBite",
        category: .violent,
        headlines: ["Patient Bites Paramedic During Transport", "Ambulance Camera Shows Attack"],
        law: "assaultGovOfficial",
        threshold: 6,
        spec: "Assaulted {V}, an emergency medical worker, while performing duties, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} bit a paramedic's arm during transport on {DATE}. {DL} says {D.he} was disoriented from low blood sugar. The call came at 9 p.m., and the bite came at about 9:15 p.m. A glucose reading of 41 was recorded, and {V}'s skin was broken.",
        state: [E(.video, 3, "Ambulance Camera", "{D} bites {V}."), E(.forensic, 2, "Medical Note", "Skin broken."), E(.statement, 2, "Partner", "'He lunged.'")],
        defense: [E(.document, 1, "Glucose Reading", "A reading of 41.")],
        role: "Paramedic partner",
        exam: [.direct("What happened during transport?", "\"At about 9:15 p.m., {D} lunged and bit my partner's arm. The skin was broken.\""), .direct("What does the ambulance camera show?", "\"It shows {DL} biting {V}'s arm. It is a short clip, and it is clear.\""), .direct("What was {D}'s condition?", "\"Disoriented. A glucose reading of 41 was recorded, which is very low.\""), .direct("What was the call and what did you find?", "\"At about 9 p.m. we were dispatched to a person down on a sidewalk. {D.He} was sweaty, confused, and slurring words, and we loaded {D.him} for transport.\""), .direct("What did you do for the defendant in the ambulance?", "\"I took vitals, checked a glucose reading of 41, and my partner prepared to give sugar. {D.He} was agitated and kept trying to sit up.\""), .direct("How did the bite happen?", "\"At about 9:15 my partner leaned over to start an IV. {D.He} grabbed the arm and bit down hard enough to break the skin.\""), .cross("Low blood sugar can cause confusion, can't it?", "\"Yes. A glucose of 41 can cause confusion and unusual behavior.\""), .cross("Had the defendant been drinking?", "\"I smelled alcohol. I cannot say how much {DL} had.\""), .cross("Did the defendant apologize?", "\"Yes, later. {D.He} said sorry and said {D.he} did not remember.\""), .cross("Was the defendant responding to questions before the bite?", "\"Partly. {D.He} gave a name and said the stomach hurt, but did not know the day or where we were headed.\""), .cross("Did the defendant resist after the bite?", "\"No. {D.He} went limp, looked startled, and said sorry several times. {D.He} stayed calm for the rest of the ride.\"")],
        defenseRole: "ER nurse",
        defenseExam: [.direct("Was {D}'s glucose low when {D} arrived at the ER?", "\"Yes. The reading was 41 on arrival, which is dangerously low.\""), .direct("What does a glucose level that low do to a person?", "\"It causes confusion, agitation, and trouble following what is happening. A person can act out without knowing.\""), .direct("How did the defendant act in the ER?", "\"Confused and slow to respond. {D} did not know where {D.he} was for a while.\""), .direct("What is your role in the ER?", "\"I am a nurse who triages arrivals and manages patients who come in by ambulance, including those with diabetic emergencies.\""), .direct("What was the defendant's condition when the ambulance arrived?", "\"Pale, sweaty, and confused. The reading was 41 at arrival, and we gave sugar right away.\""), .direct("How quickly did the defendant recover?", "\"Within thirty minutes. {D.He} became alert, understood what had happened, and asked about the paramedic who was hurt.\""), .cross("Could alcohol have contributed?", "\"It could have. I smelled it, and I cannot say how much.\""), .cross("Did the defendant bite anyone in the ER?", "\"No. {D.He} was calm once {D.his} sugar was up.\""), .cross("Was the confusion entirely from low sugar?", "\"I cannot say that. Several factors can cause it.\""), .cross("Did you smell alcohol on the defendant?", "\"A little. It was faint, and I cannot say how much was consumed.\""), .cross("Were you present for the bite?", "\"No. I saw only the injured arm when the paramedic came in. I know the bite only from what the crew reported.\"")],
        theory: ("{D} bit a paramedic.", "Low blood sugar."),
        allocution: "\"I don't remember biting anyone, and I'm told that I did. My blood sugar was very low that night, and when that happens I become confused and do things I would never do. I'm sorry that the paramedic was hurt while trying to help me. I've changed how I manage my condition.\"",
        truths: ("{DL} had been drinking.", "The reading was 41 at arrival."),
        defendant: [.direct("Did you bite the paramedic?", "\"I do not remember. I was told I did. I was not myself.\""), .direct("Why would you do that?", "\"My blood sugar was low. I get confused and I do things I would never do.\""), .direct("Had you been drinking?", "\"Some. I had a couple of drinks, and I did not eat. I should have known better.\""), .direct("What is the condition that affects your blood sugar?", "\"I am diabetic and have been for years. My sugar can drop quickly if I skip a meal or drink, and then I get confused.\""), .direct("What do you remember about that evening?", "\"I had a couple of drinks with friends and did not eat. I remember feeling dizzy on the sidewalk, and after that very little.\""), .direct("What did you do when you learned about the bite?", "\"I apologized to the paramedic and asked how I could make it right. I offered to pay for any treatment.\""), .cross("You do not remember the bite, do you?", "\"No. I do not. I only know what I was told.\""), .cross("You broke the skin of someone who was helping you, didn't you?", "\"I am told I did. I am sorry for that.\""), .cross("You drank on an empty stomach with a blood sugar problem, didn't you?", "\"Yes. That was a mistake. I should have been careful.\""), .cross("You knew about your condition and you still drank without eating. Why?", "\"It was a mistake. I thought I could handle it, and I know better now.\""), .cross("The camera shows you lunging. Was that confusion or aggression?", "\"I do not remember it, but a glucose that low has made me confused before. I would not attack someone who was helping.\"")],
        openings: ("During an ambulance transport at about 9:15 p.m., {D} bit a paramedic's arm and broke the skin. The ambulance camera shows it, and {D.he} had been drinking.", "By the end of this trial, the proof will show that {D}'s blood sugar was 41, a dangerously low level that causes confusion, and that {D.he} does not remember the bite."),
        closings: ("A bite caught on camera, a broken arm skin, and a patient who had been drinking. {D} bit someone who was trying to help.", "A glucose reading of 41 and a patient who was disoriented and does not remember. The State must prove {D} acted knowingly, and a medical emergency is not a crime."),
        timeline: [(0, "9 p.m.: the call."), (0, "9:15 p.m.: the bite."), (0, "9:40 p.m.: the ER."), (1, "{DL} is charged.")],
        identified: "A camera.",
        mood: .sympathetic,
        impact: "I had to get tested after my partner was bitten, and then I had to wait for results. It was the longest week of our lives, and neither of us slept. We were just trying to help someone who was in trouble. I think about that bite every time we put someone in the rig.",
        doctrines: ["intoxication", "mistakeOfFact"])

    static let countyClerkFees = SmallCases.make(
        key: "story.countyClerkFees",
        category: .whiteCollar,
        headlines: ["County Clerk's Office Employee Pocketed Filing Fees", "Receipts Missing From Drawer"],
        law: "embezzlement",
        threshold: 7,
        spec: "Embezzled $14,000 belonging to {V}, a county, by a person in a position of trust, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A county clerk's office employee, {D}, pocketed cash filing fees totaling $14,000 over a year. Receipts did not match deposits. {DL} says the drawer was shared.",
        state: [E(.document, 3, "Receipt Audit", "$14,000 in unmatched cash."), E(.video, 2, "Office Camera", "{D} pockets cash."), E(.document, 2, "Shift Logs", "{D} on duty for each gap.")],
        defense: [E(.statement, 1, "Shared", "{DL} says the drawer was shared.")],
        role: "County finance officer",
        exam: [.direct("What did the county's audit find?", "\"A receipt audit found $14,000 in unmatched cash over a year. Receipts did not match deposits.\""), .direct("How was {DL} connected?", "\"{D} was on duty for each gap, according to the shift logs. And the office camera shows {DL} pocketing cash.\""), .direct("What kind of money was involved?", "\"Cash filing fees. People came to the clerk's office, paid fees in cash, and received receipts. The cash didn't all reach the bank.\""), .direct("How did you find the missing cash?", "\"A monthly reconciliation showed receipts for cash fees that never reached the bank deposit. The gaps repeated month after month, totaling $14,000.\""), .direct("What did the shift logs show?", "\"For each gap, {D.he} was on the drawer for at least part of the day. Other clerks were sometimes also on shift.\""), .direct("What did the office camera show?", "\"After we installed a camera, {DL} is seen taking bills from the drawer and putting them into a jacket pocket on at least two days.\""), .cross("{DL} says the drawer was shared, doesn't {D.he}?", "\"Several clerks had keys. I can't say who else may have taken cash.\""), .cross("Was {DL} on duty every time?", "\"For each gap, yes. But others were on duty too at times. The logs show more than one person.\""), .cross("Did you see {DL} take money?", "\"I saw the camera footage of {DL} pocketing cash. I wasn't in the office when it happened.\""), .cross("How many people worked that drawer?", "\"Three clerks had keys. We have since changed that so each person has a separate till.\""), .cross("Did the camera show where the cash went?", "\"No. It shows {DL} pocketing money, but it does not follow the cash after that.\"")],
        defenseRole: "Co-clerk",
        defenseExam: [.direct("How did the drawer work?", "\"We shared one drawer at the front. Each of us had a key, and we took turns taking payments.\""), .direct("Who had keys?", "\"Three of us. Everyone on the counter had access.\""), .direct("Was {DL} a good coworker?", "\"Yes. I've never had a problem with {D}. {D.He} was honest and reliable as far as I knew.\""), .direct("How long have you worked at the counter?", "\"Eleven years. I handle recordings, certified copies, and filing fees alongside two other clerks.\""), .direct("How was the drawer secured?", "\"A single drawer with three keys. At the end of the day the counts were rough, and we often found a few dollars off.\""), .direct("What kind of employee was {D}?", "\"Friendly and dependable, always covering shifts. I never saw {DF} handle money in a way that bothered me.\""), .cross("Was {DL} on shift when the cash went missing?", "\"Often, yes. I can't say every time. {D.He} works a lot.\""), .cross("Did you take any cash?", "\"No. Never. I'd never do that.\""), .cross("Did you see {DL} take any?", "\"No. I never saw anything. I'm only telling what I know about the drawer.\""), .cross("Were you ever alone with the drawer?", "\"Yes, on my own shifts. I did not take any cash, and I am not the person under investigation.\""), .cross("Did you notice the shortages as they happened?", "\"Not in real time. I heard about them after the audit.\"")],
        theory: ("{D} took filing fees.", "A shared drawer."),
        allocution: "\"I never took cash from the office, and I would not steal from the county. The drawer was shared among several of us, and I may have put my own change in my pocket when I made a purchase. I'm sorry that the books don't match. I've worked there honestly for years, and I'd ask the court to look at the shared drawer.\"",
        truths: ("{DL} bought a new truck.", "Two other clerks had keys."),
        defendant: [.direct("Did you take cash from the drawer?", "\"No. I never took cash from the office. I handled the drawer like everyone else, and I'd never steal from the county.\""), .direct("Why are you on camera putting cash in your pocket?", "\"I may have put my own change away. I don't remember the moment. I never put county fees in my pocket.\""), .direct("Who else had access to the drawer?", "\"Several clerks had keys. We shared it. Any of us could have had access.\""), .direct("What was your job?", "\"I worked the filing counter, took fees in cash and check, wrote receipts, and put the drawer together at the end of the day.\""), .direct("What do you remember about the day on the camera?", "\"I gave someone change and put my own bills away. I do not remember any more than that. It looked like a normal afternoon.\""), .direct("How did the drawer work?", "\"One cash drawer shared by three of us. We each signed in with a key and counted down at close. Sometimes the count was off and we shrugged.\""), .cross("The shift logs show you on duty for each gap, don't they?", "\"I'm often on duty. I work a lot of shifts. That doesn't mean I took anything.\""), .cross("$14,000 in a year is a lot, isn't it?", "\"It is. It's a serious loss. I'm sorry for it. I'm not the one who took it.\""), .cross("The camera shows you pocketing cash, doesn't it?", "\"It shows something. I can't say it was county money. I understand how it looks.\""), .cross("You were on duty for every shortage. Did you consider that a problem?", "\"I did not think about it. I work most shifts, and anyone could have taken money when I stepped away.\""), .cross("You bought a new truck during that year. Where did the money come from?", "\"I used savings and a loan. I did not use county cash. I can show the paperwork.\"")],
        openings: ("A county clerk's office lost $14,000 in cash filing fees over a year, with receipts not matching deposits. The shift logs show {D} on duty for each gap, and the office camera shows {DL} pocketing cash. The State will present the finance officer and the audit.", "The defense will point you to a shared drawer, three clerks with keys, and a video that does not show what was in {D}'s hand."),
        closings: ("$14,000 missing, {D} on duty for every gap, and a camera showing {DL} pocketing cash. The audit, the logs, and the video fit.", "A drawer shared among three clerks, and a camera that doesn't show whose money it was. The State has not proved {D} was the one who took it."),
        timeline: [(-365, "The gaps begin."), (0, "Year 1: audit."), (0, "Year 1: camera installed."), (30, "{DL} is charged.")],
        identified: "An audit.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let crossbowNeighborDispute = SmallCases.make(
        key: "story.crossbowNeighborDispute",
        category: .violent,
        headlines: ["Neighbor Aimed Crossbow at Man Over Property Line", "Bolt Found in Fence Post"],
        law: "assaultPointingGun",
        threshold: 7,
        spec: "Assaulted {V} by pointing a crossbow, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} aimed a loaded crossbow at {V} on {DATE} during a property line dispute and fired a bolt into a fence post. {DL} says {D.he} was aiming at a hawk. The argument began that morning, and the shot came at about 4 p.m. Deputies arrived about twenty minutes later and found the bolt in the fence post.",
        state: [E(.physical, 3, "Bolt", "A bolt in the fence post.", .search), E(.video, 3, "Doorbell Camera", "{D} aims at {V}."), E(.statement, 2, "Neighbor", "'He aimed at {V}.'")],
        defense: [E(.statement, 1, "Hawk", "{DL} says {D.he} aimed at a hawk.")],
        role: "Neighbor",
        exam: [.direct("What did you see on {DATE}?", "\"{D} and {V} were having a property line dispute. About 4 p.m., I saw {DL} aim a loaded crossbow at {V}. I saw it clearly.\""), .direct("What happened with the crossbow?", "\"{D.He} fired. The bolt went into a fence post. Deputies arrived about twenty minutes later and found the bolt in the post.\""), .direct("What does the doorbell camera show?", "\"It shows {DL} aiming at {V}. It shows the crossbow raised and pointed toward {V}'s direction.\""), .direct("How long have you lived next to {D} and {V}?", "\"Nine years. I can see both properties from my porch and the fence line where the dispute centers.\""), .direct("What had the morning been like?", "\"Loud. {DL} and {V} argued over where a survey stake belonged. By afternoon things had cooled, or so I thought.\""), .direct("What did you see at about 4 p.m.?", "\"{D.He} stepped out with a crossbow, raised it, and pointed it toward {V}, who was near the fence. The bolt flew with a crack and stuck in a post.\""), .cross("{DL} says {D.he} was aiming at a hawk, doesn't {D.he}?", "\"I know there's a hawk in the area. But I saw the crossbow pointed at {V}.\""), .cross("Was {V} hit?", "\"No. The bolt went into the fence post. {V} wasn't hit. It was close.\""), .cross("How far away were you?", "\"I was across the lot. I saw the aim and the shot. I'm confident in what I saw.\""), .cross("How far apart were the defendant and {V}?", "\"About forty yards. I cannot say precisely how close the bolt came.\""), .cross("Did you see a hawk?", "\"I did not. I was looking at {D.him} and {V}, so I would not have noticed.\"")],
        defenseRole: "Wildlife officer",
        defenseExam: [.direct("Do you know the area around the fence?", "\"Yes. I'm a wildlife officer, and I know that stretch. There's an oak near the property line.\""), .direct("Was there a nest?", "\"Yes. A hawk nest in the oak. Raptors are common there.\""), .direct("Does a hawk go after chickens?", "\"It can. Hawks hunt small animals, including poultry. It's not unusual.\""), .direct("What is your job as a wildlife officer?", "\"I enforce hunting and wildlife laws, respond to animal complaints, and advise landowners on predator problems in this county.\""), .direct("What did you learn about the oak and the nest?", "\"A red-tailed hawk nest sits in the upper branches, in plain view from the fence line. They are protected, but they do take poultry.\""), .direct("Where was the bolt found?", "\"In a fence post at roughly chest height, about twenty feet from where {V} said {V.he} was standing.\""), .cross("Was the crossbow aimed at the nest?", "\"Unclear. I wasn't there at the shot. I only know the nest was there.\""), .cross("Did you see {DL} aim?", "\"No. I only know what I saw on the property later.\""), .cross("Could the hawk have been in line with {V}?", "\"I can't say. The geometry matters, and I didn't measure it.\""), .cross("Does the nest line up with the direction of the shot?", "\"The nest is in the same general direction, but I have not mapped the shot precisely.\""), .cross("Were you there when the shot was fired?", "\"No. I came after the call. I measured and photographed, and I cannot tell you what {D} was aiming at.\"")],
        theory: ("{D} aimed a crossbow at a neighbor.", "A hawk."),
        allocution: "\"I was aiming at a hawk in the oak tree, which had been going after my chickens. I never pointed that crossbow at my neighbor, and I would not do that. I understand how it looked in the middle of our argument, and I'm sorry that it frightened {V}. I won't take a shot like that again.\"",
        truths: ("{DL} had argued with {V} that morning.", "A hawk nest sat in the oak."),
        defendant: [.direct("What were you doing with the crossbow?", "\"I was aiming at a hawk in the oak. It had been after my chickens. I wasn't pointing it at {V}.\""), .direct("Why did you shoot toward the fence?", "\"The hawk was near the fence line. I took the shot, and the bolt hit the post. I'm not a great shot.\""), .direct("What about the argument with {V}?", "\"We'd argued that morning about the property line. It was heated, but I'd never shoot at {V.him}.\""), .direct("How long had the hawk been a problem?", "\"For a couple of weeks. It took a hen from my coop and kept circling. I had seen it land in the oak near the fence.\""), .direct("Where was {V} when you aimed?", "\"Beyond the fence, near the line. I did not see {V.him} at first because the hawk was in the branches in front of the oak.\""), .direct("What did you do after the shot?", "\"I heard {V} shout and lowered the crossbow. I walked over to see whether anyone was hurt and told {V} it was for the hawk.\""), .cross("{V} was near the line, wasn't {V.he}?", "\"Yes. I know. That's why I'm so sorry. I should have waited until {V} was out of the way.\""), .cross("You fired a loaded crossbow near a neighbor, didn't you?", "\"Yes. It was reckless. I'm not going to argue that. I wasn't aiming at {V.him}.\""), .cross("You'd been arguing all morning, hadn't you?", "\"Yes. I was upset, and I picked up the crossbow. I should have walked away.\""), .cross("You fired a loaded crossbow with a neighbor in the line of fire. How is that not reckless?", "\"It was reckless, and I admit it. I should have waited until I had a clear view.\""), .cross("You had been arguing with {V} all day. Why pick up a crossbow?", "\"Because that was when the hawk showed up. I know the timing looks terrible, but I was after the bird.\"")],
        openings: ("During a property line dispute, a neighbor saw {D} aim a loaded crossbow at {V} at about 4 p.m. and fire a bolt into a fence post. The doorbell camera shows the aim. The State will show the bolt and the video.", "The defense will present a hawk nest in an oak, a farmer protecting chickens, and a shot that hit a fence post and no one."),
        closings: ("A loaded crossbow aimed at {V}, a bolt in the fence post, and an argument that same day. {D} put a neighbor in fear of death.", "A hawk nest, a wildlife officer who knows the area, and a bolt that hit a post. The State has not proved {D} aimed at {V} rather than the bird."),
        timeline: [(0, "Morning: the argument."), (0, "4 p.m.: the aim."), (0, "4:01 p.m.: the shot."), (0, "4:20 p.m.: deputies.")],
        identified: "A doorbell camera.",
        aggravating: ["The offense involved a weapon"],
        mood: .divided,
        impact: "I stopped going outside after that afternoon. I had just walked to the fence when a loaded crossbow was pointed in my direction, and a bolt went into the post inches away. I keep my curtains closed now. My wife won't let the dog out alone.",
        doctrines: ["mistakeOfFact"])

    static let lakeBoatCrashDeath = SmallCases.make(
        key: "story.lakeBoatCrashDeath",
        category: .traffic,
        headlines: ["Passenger Dies When Speedboat Hits Dock at Night", "Operator Had Been Drinking"],
